window.QUESTION_POOL = [{"id": "hf1a", "group": "hf1", "deck": "HF1A", "n": 1, "typ": "v", "kennung": "HF1a-5", "tax": "Werten", "frage": "Erklären Sie das Bemessungskonzept des Eurocode 5 (EC5). Was bedeutet der Nachweis E<sub>d</sub> ≤ R<sub>d</sub>, und wie ergeben sich der Bemessungswert der Festigkeit f<sub>d</sub> und die Beiwerte k<sub>mod</sub> und γ<sub>M</sub>?", "erklaerung": "<p>Der EC5 arbeitet mit dem <b>Teilsicherheitskonzept</b> (Grenzzustand der Tragfähigkeit, GZT). Statt eines globalen Sicherheitsbeiwerts werden Einwirkungen <i>erhöht</i> und Widerstände <i>abgemindert</i>, jeweils mit eigenen Teilsicherheitsbeiwerten.</p><ul><li><b>E<sub>d</sub></b> = Bemessungswert der Einwirkung (Beanspruchung, z. B. Moment, Spannung)</li><li><b>R<sub>d</sub></b> = Bemessungswert des Widerstands (Tragfähigkeit)</li><li><b>k<sub>mod</sub></b> = Modifikationsbeiwert: berücksichtigt Lasteinwirkungsdauer (KLED) und Nutzungsklasse (Holzfeuchte). Holz unter Dauerlast und Feuchte trägt weniger.</li><li><b>γ<sub>M</sub></b> = Teilsicherheitsbeiwert Material (streut Materialeigenschaften ab).</li></ul>", "loesung": "<p><b>Grundnachweis:</b> Die Beanspruchung darf den Widerstand nicht übersteigen:</p><div class=\"formula\">E<sub>d</sub> ≤ R<sub>d</sub></div><p><b>Bemessungsfestigkeit:</b></p><div class=\"formula\">f<sub>d</sub> = k<sub>mod</sub> · f<sub>k</sub> / γ<sub>M</sub></div><ul><li>f<sub>k</sub> = charakteristische Festigkeit (5 %-Fraktile, z. B. aus Festigkeitsklasse C24)</li><li><b>γ<sub>M</sub> = 1,3</b> für Vollholz / Balkenschichtholz</li><li><b>k<sub>mod</sub> = 0,8</b> für KLED „mittel\", NKL 1/2 (Standard beheizter Wohnraum)</li></ul><p><b>Einwirkungsseite:</b> E<sub>d</sub> = γ<sub>G</sub>·G<sub>k</sub> + γ<sub>Q</sub>·Q<sub>k</sub> mit γ<sub>G</sub> = 1,35 (ständig) und γ<sub>Q</sub> = 1,5 (veränderlich).</p>"}, {"id": "hf1a", "group": "hf1", "deck": "HF1A", "n": 2, "typ": "p", "kennung": "HF1a-5", "tax": "Können", "frage": "Ein Einfeldsparren (Satteldach) hat eine Stützweite l = 4,50 m und trägt eine Bemessungs-Streckenlast q<sub>d</sub> = 3,0 kN/m (bereits mit γ-Werten). Die Bemessungs-Biegefestigkeit beträgt f<sub>m,d</sub> = 14,8 N/mm². <b>Ermitteln Sie das erforderliche Widerstandsmoment W<sub>y</sub> und wählen Sie einen Rechteckquerschnitt (b = 8 cm).</b>", "erklaerung": "<p>Beim <b>Einfeldträger unter Gleichlast</b> liegt das maximale Moment in Feldmitte. Aus dem Moment und der zulässigen Biegespannung folgt das nötige Widerstandsmoment; daraus die Querschnittshöhe.</p><div class=\"formula\">M<sub>d</sub> = q<sub>d</sub> · l² / 8 &nbsp;|&nbsp; σ<sub>m,d</sub> = M<sub>d</sub>/W<sub>y</sub> ≤ f<sub>m,d</sub> &nbsp;|&nbsp; W<sub>y</sub> = b·h²/6</div>", "loesung": "<p><b>1. Moment:</b></p><div class=\"formula\">M<sub>d</sub> = 3,0 · 4,50² / 8 = 3,0 · 20,25 / 8 = <b>7,59 kNm</b></div><p><b>2. Erf. Widerstandsmoment:</b></p><div class=\"formula\">W<sub>y,erf</sub> = M<sub>d</sub> / f<sub>m,d</sub> = 7,59·10⁶ Nmm / 14,8 N/mm² ≈ <b>513 000 mm³ = 513 cm³</b></div><p><b>3. Höhe bei b = 8 cm:</b></p><div class=\"formula\">h = √(6·W<sub>y</sub> / b) = √(6·513 / 8) = √384,8 ≈ <b>19,6 cm</b></div><p><b>Gewählt: 8/20 cm</b> (W<sub>y,vorh</sub> = 8·20²/6 = 533 cm³ > 513 cm³ ✓). Praktisch z. B. 8/22 für Durchbiegungsreserve.</p>", "ergebnis": {"wert": 513, "einheit": "cm³", "tol": 0.05, "hinweis": "W_y,erf → h≈19,6 cm → gewählt 8/20"}}, {"id": "hf1a", "group": "hf1", "deck": "HF1A", "n": 3, "typ": "v", "kennung": "HF1a-9", "tax": "Wissen", "frage": "Vergleichen Sie <b>Sparrendach, Kehlbalkendach und Pfettendach</b> hinsichtlich Tragverhalten, sinnvollem Einsatzbereich und typischen Problemen.", "erklaerung": "<p>Die drei Grundtypen unterscheiden sich darin, <i>wie</i> die Sparren gehalten werden und wohin die Kräfte fließen. Das bestimmt Spannweiten, Horizontalkräfte und den nötigen konstruktiven Aufwand.</p>", "loesung": "<table><tr><th>Typ</th><th>Tragverhalten</th><th>Einsatz</th><th>Problem</th></tr><tr><td><b>Sparrendach</b></td><td>Unverschiebliches Dreieck (Sparrenpaar + Decke als Zugband)</td><td>bis ca. 8 m Breite, Neigung &gt; 25°</td><td>hohe Horizontalkräfte → Decke/Zugband muss sie aufnehmen</td></tr><tr><td><b>Kehlbalkendach</b></td><td>Sonderform; Kehlbalken steift Sparren in halber Höhe aus (Knicklänge ↓)</td><td>bei Sparrenlängen &gt; 6 m</td><td>Kehlbalken nur im oberen Drittel (max. l/3 vom First)</td></tr><tr><td><b>Pfettendach</b></td><td>Sparren liegen auf Pfetten; Pfetten auf Pfosten/Wänden</td><td>große Spannweiten &gt; 13 m, komplexe Grundrisse</td><td>mehr Material; Pfosten/Unterzüge nötig (Pfostenabstand 3–5 m)</td></tr></table>"}, {"id": "hf1a", "group": "hf1", "deck": "HF1A", "n": 4, "typ": "p", "kennung": "HF1a-3", "tax": "Können", "frage": "Für eine Dachfläche sind gegeben: Eigengewicht g<sub>k</sub> = 0,9 kN/m², Schneelast s<sub>k</sub> = 0,85 kN/m², Sparrenabstand e = 0,80 m. <b>Berechnen Sie die Bemessungs-Streckenlast q<sub>d</sub> je Sparren</b> (Lasten als Flächenlast auf Grundfläche, ohne Wind).", "erklaerung": "<p>Flächenlasten werden über den <b>Sparrenabstand (Lasteinzugsbreite)</b> in eine Streckenlast je Sparren umgerechnet. Anschließend werden ständige und veränderliche Lasten mit ihren Teilsicherheitsbeiwerten kombiniert.</p><div class=\"formula\">q<sub>d</sub> = (γ<sub>G</sub>·g<sub>k</sub> + γ<sub>Q</sub>·s<sub>k</sub>) · e &nbsp;|&nbsp; γ<sub>G</sub>=1,35 · γ<sub>Q</sub>=1,5</div>", "loesung": "<p><b>1. Bemessungs-Flächenlast:</b></p><div class=\"formula\">f<sub>d</sub> = 1,35·0,9 + 1,5·0,85 = 1,215 + 1,275 = <b>2,49 kN/m²</b></div><p><b>2. Streckenlast je Sparren</b> (Einzugsbreite e = 0,80 m):</p><div class=\"formula\">q<sub>d</sub> = 2,49 · 0,80 = <b>1,99 kN/m ≈ 2,0 kN/m</b></div><p class=\"muted\">Hinweis: streng genommen wirkt die Last auf die geneigte Fläche; bei Überschlagsrechnungen wird oft auf die Grundfläche bezogen. In der Prüfung die gewählte Bezugsfläche angeben.</p>", "ergebnis": {"wert": 1.99, "einheit": "kN/m", "tol": 0.06, "hinweis": "≈ 2,0 kN/m je Sparren"}}, {"id": "hf1a", "group": "hf1", "deck": "HF1A", "n": 5, "typ": "p", "kennung": "HF1a-5", "tax": "Werten", "frage": "Erläutern Sie die <b>Durchbiegungsnachweise</b> nach EC5 (Gebrauchstauglichkeit). Welche Grenzwerte gelten für w<sub>inst</sub> und w<sub>fin</sub>, und warum gibt es zwei Werte?", "erklaerung": "<p>Neben der Tragfähigkeit (GZT) muss der <b>Grenzzustand der Gebrauchstauglichkeit (GZG)</b> eingehalten werden – sonst „hängt\" das Bauteil sichtbar durch, auch wenn es nicht bricht. Holz <b>kriecht</b> unter Dauerlast: die Durchbiegung wächst mit der Zeit. Deshalb zwei Werte:</p><ul><li><b>w<sub>inst</sub></b> (instantan) = sofortige, elastische Durchbiegung nach Belastung</li><li><b>w<sub>fin</sub></b> (final) = Enddurchbiegung inkl. Kriechen (Faktor k<sub>def</sub>)</li></ul>", "loesung": "<p><b>Übliche Grenzwerte:</b></p><div class=\"formula\">w<sub>inst</sub> ≤ l / 300 &nbsp;&nbsp;·&nbsp;&nbsp; w<sub>fin</sub> ≤ l / 200</div><p><b>Beispiel l = 4,50 m:</b></p><ul><li>w<sub>inst</sub> ≤ 4500/300 = <b>15 mm</b></li><li>w<sub>fin</sub> ≤ 4500/200 = <b>22,5 mm</b></li></ul><p>Das Kriechen wird über k<sub>def</sub> (abhängig von Nutzungsklasse) erfasst: w<sub>fin</sub> = w<sub>inst</sub>·(1+k<sub>def</sub>). Bei Sichtbauteilen oder Decken unter Putz können strengere Werte (l/400, l/500) gefordert sein.</p>"}, {"id": "hf1a", "group": "hf1", "deck": "HF1A", "n": 6, "typ": "v", "kennung": "HF1a-9", "tax": "Wissen", "frage": "Welche Funktion hat der <b>Kehlbalken</b> statisch, und welche konstruktiven Regeln gelten für seine Lage und seinen Anschluss?", "erklaerung": "<p>Der Kehlbalken verbindet zwei gegenüberliegende Sparren auf halber Höhe. Statisch wirkt er als <b>Druck- bzw. Zugstab</b>, der die Sparren gegeneinander abstützt und so die <b>Knicklänge</b> der Sparren halbiert sowie die Durchbiegung reduziert. Bei Wind/asymmetrischer Last überträgt er Kräfte von der windzugewandten auf die windabgewandte Seite.</p>", "loesung": "<ul><li><b>Lage:</b> im <b>oberen Drittel</b> des Sparrens, max. l/3 vom First gemessen – sonst wirkt er nicht mehr aussteifend genug.</li><li><b>Einsatz:</b> sinnvoll ab Sparrenlängen &gt; ca. 6 m.</li><li><b>Anschluss:</b> beidseitig kraftschlüssig (z. B. genagelt/verschraubt oder versatzartig); muss <b>Druck UND Zug</b> übertragen.</li><li><b>Knicknachweis:</b> Bei Druckbeanspruchung ist der Kehlbalken auf Knicken nachzuweisen (Knicklänge = Kehlbalkenlänge).</li></ul>"}, {"id": "hf1a", "group": "hf1", "deck": "HF1A", "n": 7, "typ": "v", "kennung": "HF1a-6", "tax": "Wissen", "frage": "Nennen und begründen Sie die wichtigsten <b>konstruktiven Grenzmaße</b> bei Sparren: maximale Kerventiefe, Versatzeinschnitt und die Abbrandrate für den Brandfall.", "erklaerung": "<p>Einschnitte (Kerve, Versatz) schwächen den Querschnitt und erzeugen Kerbspannungen. Deshalb sind sie konstruktiv begrenzt. Für den Brandschutz nach Abbrandmethode muss der <b>Restquerschnitt</b> nach der geforderten Zeit noch tragen.</p>", "loesung": "<ul><li><b>Kerve (Aufkämmung auf Pfette):</b> max. <b>¼ der Sparrenhöhe</b> einschneiden. Tiefer → Querschnitt zu stark geschwächt, Schub-/Biegeprobleme.</li><li><b>Versatz am Auflager:</b> Einschnitttiefe ca. <b>2 cm</b> (bzw. begrenzt nach Vorholzlänge/Holzhöhe), Vorholz lang genug gegen Abscheren.</li><li><b>Abbrandrate Vollholz:</b> ca. <b>0,65–0,7 mm/min</b>. → Bei R30 brennt rundum ca. 0,65·30 ≈ 20 mm ab; Restquerschnitt muss die Last noch tragen.</li><li><b>Transportmaße genehmigungsfrei:</b> Breite 2,55 m, Höhe 4,00 m (für vorgefertigte Bauteile relevant).</li></ul>"}, {"id": "hf1a", "group": "hf1", "deck": "HF1A", "n": 8, "typ": "v", "kennung": "HF1a-1", "tax": "Erkennen", "frage": "Vergleichen Sie <b>KVH, Brettschichtholz (BSH) und Furnierschichtholz (LVL)</b>: Aufbau, Eigenschaften und typische Einsatzgebiete.", "erklaerung": "<p>Vollholzprodukte werden durch industrielle Verklebung leistungsfähiger und maßhaltiger gemacht. Je feiner die Auflösung (Brett → Furnier), desto homogener und höher belastbar das Produkt – aber auch teurer.</p>", "loesung": "<table><tr><th>Produkt</th><th>Aufbau</th><th>Eigenschaften / Einsatz</th></tr><tr><td><b>KVH</b></td><td>keilgezinktes Vollholz, technisch getrocknet</td><td>maßhaltig, wenig Risse; Standard für Sparren, Ständer, Riegel</td></tr><tr><td><b>BSH (Brettschichtholz)</b></td><td>mind. 3 Brettlamellen faserparallel verklebt</td><td>große Spannweiten/Querschnitte, gekrümmte Träger; Hallen, Binder</td></tr><tr><td><b>LVL (Furnierschichtholz)</b></td><td>geschälte Furniere verklebt (meist faserparallel)</td><td>sehr hohe Festigkeit, schmale hohe Träger, Gurte von Stegträgern</td></tr></table><p>Faustregel: KVH für Standardquerschnitte, BSH für große Spannweiten/Sichtholz, LVL für höchstbelastete schlanke Bauteile.</p>"}, {"id": "hf1a", "group": "hf1", "deck": "HF1A", "n": 9, "typ": "p", "kennung": "HF1a-4", "tax": "Können", "frage": "Erklären Sie das <b>Ritter'sche Schnittverfahren</b> zur Bestimmung von Stabkräften im Fachwerk. Wie geht man vor, und worin liegt der Vorteil gegenüber dem Knotenpunktverfahren?", "erklaerung": "<p>Im Fachwerk werden Stäbe als <b>Pendelstäbe</b> (nur Zug/Druck) idealisiert. Das <b>Ritterschnittverfahren</b> legt einen Schnitt durch <b>max. drei Stäbe</b> mit unbekannter Kraft und nutzt die <b>Momenten-Gleichgewichtsbedingung</b> um geschickt gewählte Knoten – so lässt sich jede gesuchte Stabkraft <i>direkt</i> berechnen, ohne sich durch alle Knoten zu hangeln.</p>", "loesung": "<p><b>Vorgehen:</b></p><ol><li>Auflagerreaktionen aus Gesamt-Gleichgewicht bestimmen.</li><li>Schnitt durch den Stab legen, dessen Kraft gesucht ist (max. 3 geschnittene Stäbe).</li><li>Freikörperbild einer Schnitthälfte zeichnen, Stabkräfte als Zug (vom Knoten weg) ansetzen.</li><li><b>ΣM = 0</b> um den Schnittpunkt der beiden <i>anderen</i> geschnittenen Stäbe → gesuchte Kraft folgt direkt.</li><li>Vorzeichen: + = Zug, − = Druck.</li></ol><p><b>Vorteil:</b> Einzelne Stabkräfte gezielt und schnell bestimmbar (z. B. nur der maßgebende Untergurt), ohne alle Knoten nacheinander zu lösen wie beim Knotenpunktverfahren (Cremonaplan).</p>"}, {"id": "hf1a", "group": "hf1", "deck": "HF1A", "n": 10, "typ": "v", "kennung": "HF1a-8", "tax": "Werten", "frage": "Wie wird ein <b>Hallentragwerk in Holzbauweise ausgesteift</b>? Beschreiben Sie die Aussteifung in Längs- und Querrichtung.", "erklaerung": "<p>Ein Hallenrahmen aus Bindern und Stützen ist zunächst nur in seiner Ebene (quer) stabil. Gegen Wind <b>längs</b> zur Halle und zur Gesamtstabilität braucht es ein durchdachtes <b>Aussteifungssystem</b>, das Horizontalkräfte (Wind) bis in die Fundamente führt.</p>", "loesung": "<ul><li><b>Querrichtung (in Rahmenebene):</b> unverschiebliche Dreiecke aus Sparren/Binder + Pfosten + Decke; bzw. eingespannte Stützenfüße bei Zweigelenkrahmen.</li><li><b>Längsrichtung:</b><ul><li><b>Dachscheibe / Dachverband</b> (Windrispen, Diagonalverbände) leitet Windlast vom Giebel ein</li><li><b>Vertikalverbände</b> in den Wandebenen führen die Kräfte nach unten</li><li><b>Kopfbänder/Büge</b> zwischen Stütze und Pfette/Binder steifen die Knoten aus</li></ul></li><li>Bei großen Spannweiten: Nagelplattenbinder oder Dreieck-Streben-Bauweise (DSB).</li></ul><p>Merksatz: Jede Halle braucht in <b>beiden</b> Richtungen einen geschlossenen Kraftweg vom Dach bis zum Fundament.</p>"}, {"id": "hf1b", "group": "hf1", "deck": "HF1B", "n": 1, "typ": "v", "kennung": "HF1b-1", "tax": "Wissen", "frage": "Nennen Sie die <b>Kategorien von Holzverbindungen</b> und ordnen Sie typische Verbindungsmittel zu.", "erklaerung": "<p>Verbindungen übertragen Kräfte zwischen Bauteilen. Man unterscheidet nach Wirkprinzip – das bestimmt Tragfähigkeit, Nachgiebigkeit und Aufwand.</p>", "loesung": "<ul><li><b>Zimmermannsmäßig:</b> Zapfen, Blatt, Kamm, einfacher/doppelter Versatz, Stirn-/Fersenversatz (Kraft über Holzkontaktflächen)</li><li><b>Stiftförmige Mittel:</b> Nägel, Holzschrauben, Stabdübel, Bolzen, Passbolzen (Abscheren/Lochleibung)</li><li><b>Dübel besonderer Bauart:</b> Typ A (Appel), Typ C (Bulldog), Typ D (GEKA) – Einlass-/Einpressdübel</li><li><b>Blechformteile:</b> Sparren-Pfetten-Anker, Winkelverbinder, Balkenschuhe, Nagelbleche</li><li><b>Klebeverbindungen:</b> PUR-/RF-Leim (BSH, Verstärkungen)</li></ul>"}, {"id": "hf1b", "group": "hf1", "deck": "HF1B", "n": 2, "typ": "v", "kennung": "HF1b-1", "tax": "Werten", "frage": "Erklären Sie den <b>Versatz</b> als zimmermannsmäßige Verbindung. Welche Versagensarten sind nachzuweisen?", "erklaerung": "<p>Der Versatz überträgt <b>Druckkräfte</b> (z. B. Strebe → Schwelle) durch Holzkontakt. Die Strebenkraft wird in die Vorholzfläche eingeleitet. Kritisch sind die Druckfläche (Pressung) und das <b>Vorholz</b>, das nicht abscheren darf.</p>", "loesung": "<ul><li><b>Stirnversatz:</b> Druckfläche rechtwinklig zur Strebe – einfach, begrenzte Vorholzlänge.</li><li><b>Fersenversatz:</b> Druckfläche in Winkelhalbierender – günstigere Kraftverteilung.</li><li><b>Doppelter Versatz:</b> Kombination – höhere Tragfähigkeit.</li></ul><p><b>Nachweise:</b> 1) <b>Druckpressung</b> in der Versatzfläche (σ ≤ f<sub>c,α,d</sub>); 2) <b>Abscheren des Vorholzes</b> (Schubfläche = Vorholzlänge × Breite); 3) Einschnitttiefe t<sub>v</sub> begrenzt (Querschnittsschwächung).</p>"}, {"id": "hf1b", "group": "hf1", "deck": "HF1B", "n": 3, "typ": "p", "kennung": "HF1b-1", "tax": "Können", "frage": "Eine Strebe leitet über einen Stirnversatz eine Horizontalkomponente von H<sub>d</sub> = 18 kN ins Vorholz. Die zulässige Schubspannung im Vorholz beträgt f<sub>v,d</sub> = 2,5 N/mm², die Holzbreite b = 12 cm. <b>Ermitteln Sie die erforderliche Vorholzlänge l<sub>v</sub> gegen Abscheren.</b>", "erklaerung": "<p>Das Vorholz darf nicht abscheren. Die Schubfläche ist <b>Vorholzlänge × Breite</b>. Aus der zu übertragenden Horizontalkraft und der zulässigen Schubspannung folgt die Mindestlänge.</p><div class=\"formula\">τ = H<sub>d</sub> / (l<sub>v</sub> · b) ≤ f<sub>v,d</sub> &nbsp;→&nbsp; l<sub>v</sub> ≥ H<sub>d</sub> / (b · f<sub>v,d</sub>)</div>", "loesung": "<div class=\"formula\">l<sub>v</sub> ≥ 18 000 N / (120 mm · 2,5 N/mm²) = 18 000 / 300 = <b>60 mm</b></div><p>Konstruktiv ist meist eine <b>Mindestvorholzlänge</b> einzuhalten (Faustregel l<sub>v</sub> ≥ 150–200 mm bzw. ≥ 8·t<sub>v</sub>). → gewählt z. B. <b>l<sub>v</sub> = 200 mm</b>. Rechnerisch reichen 60 mm, die konstruktive Regel ist hier maßgebend.</p>"}, {"id": "hf1b", "group": "hf1", "deck": "HF1B", "n": 4, "typ": "v", "kennung": "HF1b-4", "tax": "Werten", "frage": "Wie tragen <b>stiftförmige Verbindungsmittel</b> (Stabdübel, Bolzen) Lasten ab, und warum sind <b>Mindestabstände</b> einzuhalten?", "erklaerung": "<p>Stabdübel/Bolzen übertragen Kräfte über <b>Lochleibung</b> (Pressung Holz gegen Stift) und <b>Biegung des Stiftes</b>. Bei mehreren Scherfugen addieren sich die Traganteile. Zu geringe Abstände → das Holz spaltet auf, bevor die volle Tragfähigkeit erreicht ist.</p>", "loesung": "<ul><li><b>Tragmechanismus:</b> Lochleibungsfestigkeit f<sub>h</sub> × Stiftdurchmesser × Holzdicke, kombiniert mit Fließmoment des Stiftes (Johansen / EC5).</li><li><b>Mindestabstände</b> (Richtwerte d = Durchmesser):<ul><li>parallel zur Faser, untereinander: ca. 5·d</li><li>zum beanspruchten Hirnholzrand (in Kraftrichtung): ca. 7·d</li><li>rechtwinklig zur Faser: ca. 3·d; zum unbeanspruchten Rand: ca. 3·d</li></ul></li><li>Ziel: <b>Spalten verhindern</b>, gleichmäßige Lasteinleitung.</li></ul>"}, {"id": "hf1b", "group": "hf1", "deck": "HF1B", "n": 5, "typ": "p", "kennung": "HF1b-2", "tax": "Können", "frage": "Ein Sparren leitet am Auflager eine Kraft von F = 4,8 kN in die Pfette. Die Verbindung erfolgt mit Nägeln, deren zulässige Tragfähigkeit je Scherfuge R<sub>d</sub> = 0,55 kN beträgt (einschnittig). <b>Wie viele Nägel sind erforderlich?</b>", "erklaerung": "<p>Die Anzahl der Verbindungsmittel ergibt sich aus der zu übertragenden Kraft geteilt durch die Tragfähigkeit pro Verbindungsmittel (je Scherfuge). Aufrunden auf ganze Stückzahl.</p><div class=\"formula\">n = F / R<sub>d</sub></div>", "loesung": "<div class=\"formula\">n = 4,8 kN / 0,55 kN = 8,7 → <b>9 Nägel</b></div><p>Praktisch: mind. 9 Nägel, unter Beachtung der Mindestabstände sinnvoll auf zwei Reihen verteilen. Bei wechselnden Lasten (Windsog!) ggf. zusätzlich Sparren-Pfetten-Anker einsetzen, da Nägel auf Herausziehen ungünstig sind.</p>"}, {"id": "hf1b", "group": "hf1", "deck": "HF1B", "n": 6, "typ": "v", "kennung": "HF1b-5", "tax": "Wissen", "frage": "Was sind <b>Dübel besonderer Bauart</b> (Typ A, C, D) und wie wirken sie?", "erklaerung": "<p>Dübel besonderer Bauart vergrößern die kraftübertragende Fläche zwischen zwei Hölzern und arbeiten meist <b>zusammen mit einem zentralen Bolzen</b> (der die Hölzer zusammenhält). Sie übertragen hohe Kräfte bei zimmermannsmäßig wirkenden Verbindungen (Fachwerk).</p>", "loesung": "<ul><li><b>Typ A (Appel):</b> Einlassdübel mit Ring/Zähnen, in vorgefräste Nut eingelassen.</li><li><b>Typ C (Bulldog):</b> Einpressdübel mit Zähnen/Krallen, beim Anziehen des Bolzens ins Holz gepresst.</li><li><b>Typ D (GEKA):</b> ein-/zweiseitige Zahnscheibe.</li></ul><p><b>Wirkung:</b> Der Dübel überträgt die Scherkraft (Holz-Holz), der Bolzen sichert den Verbund und nimmt Querzug auf. Einsatz: hochbelastete Fachwerkknoten.</p>"}, {"id": "hf1b", "group": "hf1", "deck": "HF1B", "n": 7, "typ": "v", "kennung": "HF1b-8", "tax": "Werten", "frage": "Warum müssen Dächer gegen <b>Windsog verankert</b> werden, und wo sind die kritischen Bereiche?", "erklaerung": "<p>Wind erzeugt auf Dachflächen <b>Sog</b> (Unterdruck), der die Dachhaut und den Dachstuhl <b>abheben</b> will. In Rand- und Eckbereichen ist der Sog am größten (Strömungsablösung). Die Verankerung führt diese Zugkräfte vom Sparren über Pfette/Wand bis ins Fundament.</p>", "loesung": "<ul><li><b>Windsogbeiwerte:</b> in Eck-/Randbereichen c<sub>p</sub> bis ca. <b>−1,7</b> (maßgebend für Befestigung!).</li><li><b>Verankerungskette:</b> Sparren → Sparren-Pfetten-Anker → Pfette → Zuganker/Verankerung → Wand/Decke → Fundament. Kein Glied darf fehlen.</li><li><b>Kritisch:</b> Traufe, Ortgang, First, Gebäudeecken.</li><li>Nägel auf <b>Herausziehen</b> meiden → Anker, Schrauben, Bänder verwenden.</li></ul>"}, {"id": "hf1b", "group": "hf1", "deck": "HF1B", "n": 8, "typ": "v", "kennung": "HF1b-1", "tax": "Wissen", "frage": "Worauf ist beim <b>Korrosionsschutz</b> von Stahlverbindungsmitteln zu achten, und welche <b>Normen/Regelwerke</b> sind im Verbindungsbereich relevant?", "erklaerung": "<p>Stahlteile im Holzbau müssen je nach Nutzungsklasse/Feuchte vor Korrosion geschützt werden. Werden <b>unterschiedliche Metalle</b> kombiniert, droht bei Feuchte elektrochemische Korrosion (das unedlere Metall zersetzt sich).</p>", "loesung": "<ul><li><b>Korrosionsschutz</b> nach Nutzungsklasse: feuerverzinkt / Edelstahl bei Außenbauteilen (NKL 3).</li><li><b>Mischkontakt vermeiden</b> (z. B. verzinkter Stahl + Kupfer) → Zink wird zerstört.</li><li><b>Regelwerke:</b> EC5 (DIN EN 1995, Bemessung), früher DIN 1052; DIN 4074 (Schnittholz-Sortierung); ETA-Zulassungen für Schrauben/Anker (z. B. HECO, Würth); DIN EN 14592 (stiftförmige Verbindungsmittel).</li></ul>"}, {"id": "hf1b", "group": "hf1", "deck": "HF1B", "n": 9, "typ": "p", "kennung": "HF1b-7", "tax": "Werten", "frage": "Warum werden Fachwerkknoten möglichst <b>zentrisch</b> ausgebildet, und was passiert bei <b>exzentrischem</b> Anschluss?", "erklaerung": "<p>In einem idealen Fachwerk wirken in den Stäben nur <b>Normalkräfte</b> (Zug/Druck), wenn sich die Stabachsen in <b>einem Punkt</b> (Knoten) schneiden. Treffen sie sich nicht in einem Punkt, entsteht ein Hebelarm.</p>", "loesung": "<p>Bei <b>Exzentrizität e</b> entsteht ein <b>Zusatzmoment</b>:</p><div class=\"formula\">M<sub>zus</sub> = N · e</div><p>Dieses Moment biegt die Stäbe zusätzlich → höhere Spannungen, Gefahr von Rissen/Überlastung am Knoten. <b>Folge:</b> Stabachsen im Knoten zum Schnitt bringen; lässt sich Exzentrizität nicht vermeiden, ist das Zusatzmoment im Nachweis zu berücksichtigen.</p>"}, {"id": "hf1c", "group": "hf1", "deck": "HF1C", "n": 1, "typ": "v", "kennung": "HF1c-1", "tax": "Wissen", "frage": "Erklären Sie die Begriffe <b>Regeldachneigung (RDN)</b> und <b>Mindestdachneigung</b>. Was passiert bei Unterschreitung der RDN?", "erklaerung": "<p>Die Dachneigung bestimmt die Regensicherheit einer ableitenden Deckung. Je flacher das Dach, desto länger steht Wasser auf der Deckung und desto eher dringt es ein (Stau, Flugschnee).</p>", "loesung": "<ul><li><b>Regeldachneigung (RDN):</b> unterste Neigung, bei der eine Deckungsart <b>ohne Zusatzmaßnahmen</b> regensicher ist (produktabhängig).</li><li><b>Mindestdachneigung:</b> absolute Untergrenze für ein Steildach – <b>10°</b>; darunter gilt es als Flachdach (abdichtende Bauweise).</li><li><b>Bei RDN-Unterschreitung:</b> Zusatzmaßnahmen nach <b>Klasse 1–6</b> erforderlich (von einfacher Unterspannung bis zum wasserdichten Unterdach) – je größer die Unterschreitung, desto höhere Klasse.</li></ul>"}, {"id": "hf1c", "group": "hf1", "deck": "HF1C", "n": 2, "typ": "p", "kennung": "HF1c-1", "tax": "Erkennen", "frage": "Ordnen Sie folgenden Deckungen ihre <b>Regeldachneigung</b> zu: Flachdachziegel (Ringfalz), Reformziegel (Kopf-/Seitenfalz), Biberschwanz-Doppeldeckung, Hohlpfanne.", "erklaerung": "<p>Falzziegel sind durch ihre Falze dichter und dürfen flacher gedeckt werden; Biber und Hohlpfanne brauchen mehr Neigung. Diese Werte sind klassische Prüfungs-Merkwerte.</p>", "loesung": "<table><tr><th>Deckung</th><th>RDN</th></tr><tr><td>Flachdachziegel (Ringfalz)</td><td><b>22°</b></td></tr><tr><td>Reformziegel (Kopf-/Seitenfalz)</td><td><b>25°</b></td></tr><tr><td>Biberschwanz Doppel-/Kronendeckung</td><td><b>30°</b></td></tr><tr><td>Hohlpfanne (Aufschnittdeckung)</td><td><b>40°</b></td></tr><tr><td>Biber Einfachdeckung mit Spließen</td><td><b>40°</b></td></tr></table>"}, {"id": "hf1c", "group": "hf1", "deck": "HF1C", "n": 3, "typ": "p", "kennung": "HF1c-5", "tax": "Können", "frage": "Ein Sparren ist von Trauf- bis Firstlatte 6,30 m lang. Es wird mit einem Ziegel gedeckt, dessen mittlere Höhenüberdeckung eine Lattweite von LW = 0,35 m ergibt. <b>Berechnen Sie die Anzahl der Gebinde und die genaue (eingeteilte) Lattweite.</b>", "erklaerung": "<p>Die Lattung muss <b>gleichmäßig</b> zwischen Trauf- und Firstlatte eingeteilt werden. Man bestimmt die rechnerische Gebindezahl, rundet auf, und teilt die Strecke gleichmäßig (Soll-LW ≤ max. LW).</p><div class=\"formula\">n = Sparrenlänge / LW<sub>max</sub> &nbsp;(aufrunden) &nbsp;|&nbsp; LW<sub>ein</sub> = Sparrenlänge / n</div>", "loesung": "<div class=\"formula\">n = 6,30 m / 0,35 m = 18,0 → <b>18 Gebinde</b></div><div class=\"formula\">LW<sub>eingeteilt</sub> = 6,30 m / 18 = <b>0,350 m</b></div><p>Geht die Division nicht glatt auf (z. B. 6,40 m), <b>aufrunden</b> auf 19 Gebinde → LW = 6,40/19 = 0,337 m (kleiner als max → regensicher). <b>Nie</b> abrunden, sonst LW &gt; zulässig.</p>"}, {"id": "hf1c", "group": "hf1", "deck": "HF1C", "n": 4, "typ": "v", "kennung": "HF1c-1", "tax": "Wissen", "frage": "Beschreiben Sie die drei Flachdach-Bauweisen <b>Warmdach, Kaltdach und Umkehrdach</b>.", "erklaerung": "<p>Beim Flachdach entscheidet die Lage von Dämmung, Abdichtung und Belüftung über Funktion und Tauwassersicherheit.</p>", "loesung": "<ul><li><b>Warmdach (nicht belüftet):</b> Dämmung liegt direkt unter der Abdichtung, keine Luftschicht. Dampfsperre unter der Dämmung zwingend. Häufigste Bauart.</li><li><b>Kaltdach (belüftet):</b> Belüftungsraum zwischen Dämmung und Deckschicht; Zuluft Traufe, Abluft First. Feuchte wird abgelüftet.</li><li><b>Umkehrdach:</b> Dämmung (druckfest, wasserunempfindlich, XPS) liegt <b>über</b> der Abdichtung → Abdichtung wird vor Temperatur/UV geschützt; Auflast (Kies) nötig.</li></ul>"}, {"id": "hf1c", "group": "hf1", "deck": "HF1C", "n": 5, "typ": "p", "kennung": "HF1c-5", "tax": "Können", "frage": "Ein belüftetes Steildach hat eine Dachfläche von 80 m². <b>Bestimmen Sie die erforderlichen Lüftungsquerschnitte an Traufe und First.</b>", "erklaerung": "<p>Belüftete Dächer brauchen definierte Mindestquerschnitte, damit Feuchte abtrocknen kann. Faustwerte (Fachregel): Traufe <b>2 ‰</b> der zugehörigen Dachfläche, mind. 200 cm²/m; First <b>0,5 ‰</b>.</p><div class=\"formula\">A<sub>Traufe</sub> = 2 ‰ · A<sub>Dach</sub> &nbsp;|&nbsp; A<sub>First</sub> = 0,5 ‰ · A<sub>Dach</sub></div>", "loesung": "<div class=\"formula\">A<sub>Traufe</sub> = 0,002 · 80 m² = 0,16 m² = <b>1600 cm²</b></div><div class=\"formula\">A<sub>First</sub> = 0,0005 · 80 m² = 0,04 m² = <b>400 cm²</b></div><p>Zusätzlich gilt an der Traufe der Mindestwert <b>200 cm² je m</b> Trauflänge – der größere Wert ist maßgebend. Lüftungsquerschnitt mind. 2 cm freie Höhe im Konterlattenraum.</p>"}, {"id": "hf1c", "group": "hf1", "deck": "HF1C", "n": 6, "typ": "v", "kennung": "HF1c-3", "tax": "Wissen", "frage": "Warum dürfen <b>Zink und Kupfer</b> an einem Dach nicht ungeschützt kombiniert werden?", "erklaerung": "<p>Treffen zwei unterschiedlich edle Metalle in Verbindung mit einem Elektrolyt (Regenwasser) aufeinander, entsteht ein <b>galvanisches Element</b> – elektrochemische Korrosion.</p>", "loesung": "<p><b>Kupfer ist edler als Zink.</b> Fließt Regenwasser von einem Kupferbauteil (z. B. Kupferrinne, Kupferblech) auf ein Zinkbauteil, lösen sich Kupferionen und zersetzen das unedlere <b>Zink</b> (Zink „opfert\" sich). Folge: Lochfraß, Durchrosten der Zinkteile. <b>Regel:</b> Kupfer nie <b>oberhalb</b> von Zink/verzinktem Stahl anordnen; Materialien trennen.</p>"}, {"id": "hf1c", "group": "hf1", "deck": "HF1C", "n": 7, "typ": "v", "kennung": "HF1c-1", "tax": "Erkennen", "frage": "Unterscheiden Sie <b>„harte\" und „weiche\" Bedachung</b> sowie <b>ableitende und abdichtende</b> Deckung.", "erklaerung": "<p>Diese Begriffspaare betreffen Brandschutz bzw. das Funktionsprinzip der Wasserführung – beides typische Theoriefragen.</p>", "loesung": "<ul><li><b>Harte Bedachung:</b> widerstandsfähig gegen Flugfeuer und strahlende Wärme (Ziegel, Faserzement, Metall) → geringere Gebäudeabstände zulässig.</li><li><b>Weiche Bedachung:</b> nicht flugfeuerbeständig (Reet, Holzschindeln) → größere Abstände nötig.</li><li><b>Ableitende Deckung:</b> überlappende Elemente leiten Wasser ab (Ziegel) – nicht wasserdicht, neigungsabhängig.</li><li><b>Abdichtende Deckung:</b> geschlossene wasserdichte Haut (Bitumen-/Kunststoffbahn) – auch bei 0° dicht.</li></ul>"}, {"id": "hf1c", "group": "hf1", "deck": "HF1C", "n": 8, "typ": "v", "kennung": "HF1c-1", "tax": "Wissen", "frage": "Welche <b>Fachregeln und Normen</b> sind für Dachdeckungen maßgebend?", "erklaerung": "<p>Für die Dachdeckung gilt vorrangig das Regelwerk des Dachdeckerhandwerks; der Zimmerer braucht es für Unterkonstruktion, Zusatzmaßnahmen und Anschlüsse.</p>", "loesung": "<ul><li><b>Fachregel für Dachdeckungen mit Dachziegeln und Dachsteinen</b> – zentrales Regelwerk (RDN, Zusatzmaßnahmen).</li><li><b>Fachregel für Metallarbeiten im Dachdeckerhandwerk</b> – Kehlen, An-/Abschlüsse, Bleche.</li><li><b>Merkblatt Unterdächer/Unterdeckungen/Unterspannungen</b> – Zusatzmaßnahmen-Klassen.</li><li><b>DIN EN 14437</b> – Abhebewiderstand (Windsogsicherung).</li></ul>"}, {"id": "hf1c", "group": "hf1", "deck": "HF1C", "n": 9, "typ": "p", "kennung": "HF1c-5", "tax": "Wissen", "frage": "Skizzieren/erklären Sie die wichtigsten <b>konstruktiven Details</b> einer Ziegeldeckung: Traufpunkt, First und Ortgang.", "erklaerung": "<p>An den Dachrändern muss die Deckung sauber an- und abschließen, belüftet und wind-/regensicher sein. Diese Details werden in der Prüfung oft skizziert.</p>", "loesung": "<ul><li><b>Traufpunkt:</b> Traufbohle, Lüftungsquerschnitt (Traufgitter/Vogelschutz), Rinneneinhang, Konterlattung endet über Rinne; Unterspannbahn in Rinne geführt.</li><li><b>First:</b> Trocken- oder Mörtelfirst; bei Trockenfirst Firstrolle als Lüftungsöffnung (Abluft); Firstlatte auf Firstlattenhalter.</li><li><b>Ortgang:</b> Ortgangziegel oder Windbrett; Abschluss gegen Windsog; sauberer Maßausgleich (Eindeckmaß) damit keine Schnittziegel an sichtbarer Kante.</li></ul>"}, {"id": "hf1d", "group": "hf1", "deck": "HF1D", "n": 1, "typ": "p", "kennung": "HF1d-2", "tax": "Können", "frage": "Erklären Sie die <b>Schrittmaßregel</b> nach DIN 18065 mit ihren drei Bedingungen. Berechnen Sie für eine Steigung s = 18 cm den passenden Auftritt a.", "erklaerung": "<p>Die Schrittmaßregel sorgt dafür, dass eine Treppe bequem und sicher begehbar ist. Sie beruht auf der durchschnittlichen Schrittlänge (ca. 59–65 cm). Drei Regeln müssen zusammenpassen.</p>", "loesung": "<ul><li><b>Schrittmaßregel:</b> 2s + a = 59–65 cm (Mittel 63)</li><li><b>Bequemlichkeitsregel:</b> a − s = 12 cm</li><li><b>Sicherheitsregel:</b> a + s = 46 cm</li></ul><p><b>Für s = 18 cm</b> nach Schrittmaßregel (63):</p><div class=\"formula\">a = 63 − 2·18 = 63 − 36 = <b>27 cm</b></div><p>Kontrolle: a − s = 27 − 18 = 9 (etwas unter 12, akzeptabel im Bereich); a + s = 45 ≈ 46 ✓. Steigungsverhältnis 18/27 ist bequem.</p>"}, {"id": "hf1d", "group": "hf1", "deck": "HF1D", "n": 2, "typ": "p", "kennung": "HF1d-2", "tax": "Können", "frage": "Eine Geschosshöhe beträgt H = 2,88 m. Geplant ist eine Steigung von ca. 18 cm. <b>Bestimmen Sie die Steigungsanzahl, die genaue Steigungshöhe, den Auftritt und die Lauflänge.</b>", "erklaerung": "<p>Die Steigungsanzahl ergibt sich aus Geschosshöhe / gewünschte Steigung (ganzzahlig). Daraus folgt die genaue Steigung. Die Auftrittsanzahl ist immer eine weniger als die Steigungsanzahl.</p><div class=\"formula\">n<sub>Stg</sub> = H / s &nbsp;|&nbsp; s = H / n<sub>Stg</sub> &nbsp;|&nbsp; n<sub>Auftr</sub> = n<sub>Stg</sub> − 1</div>", "loesung": "<div class=\"formula\">n<sub>Stg</sub> = 288 / 18 = 16 → <b>16 Steigungen</b></div><div class=\"formula\">s = 288 / 16 = <b>18,0 cm</b></div><p>Auftritt nach Schrittmaßregel: a = 63 − 2·18 = <b>27 cm</b>. Auftritte: 16 − 1 = <b>15</b>.</p><div class=\"formula\">Lauflänge = n<sub>Auftr</sub> · a = 15 · 27 = <b>405 cm</b></div>"}, {"id": "hf1d", "group": "hf1", "deck": "HF1D", "n": 3, "typ": "v", "kennung": "HF1d-3", "tax": "Wissen", "frage": "Nennen und beschreiben Sie die wichtigsten <b>Konstruktionsarten von Wangentreppen</b>.", "erklaerung": "<p>Bei Wangentreppen tragen seitliche Wangen die Stufen. Wie die Stufen mit der Wange verbunden sind, unterscheidet die Bauarten.</p>", "loesung": "<ul><li><b>Eingestemmte (gestemmte) Treppe:</b> Tritt- UND Setzstufen in Nuten der Wange eingelassen, von unten verkeilt – geschlossen, hochwertig.</li><li><b>Halbgestemmte Treppe:</b> nur Trittstufen eingelassen, keine Setzstufen (offen).</li><li><b>Eingeschobene Treppe:</b> Stufen von vorn in die Wange eingeschoben.</li><li><b>Aufgesattelte Treppe:</b> Wange treppenförmig ausgeschnitten, Stufen liegen oben auf.</li><li><b>Abgehängte Treppe:</b> Stufen hängen an Zugstäben.</li></ul>"}, {"id": "hf1d", "group": "hf1", "deck": "HF1D", "n": 4, "typ": "v", "kennung": "HF1d-2", "tax": "Wissen", "frage": "Welche <b>geometrischen Mindestanforderungen</b> stellt die DIN 18065 an notwendige Treppen?", "erklaerung": "<p>Damit Treppen sicher begehbar sind, gibt es Mindestmaße für Durchgang, Breite und Auftritt – besonders bei gewendelten Treppen.</p>", "loesung": "<ul><li><b>Mindestdurchgangshöhe (lichte Höhe):</b> 2,00 m – senkrecht über der Gehlinie.</li><li><b>Mindestauftritt</b> an gewendelten Stufen: 10 cm (an der Innenseite), an der Freiwange/Gehlinie 15 cm.</li><li><b>nutzbare Laufbreite</b> nach Gebäudetyp (z. B. notwendige Treppe Wohngebäude ≥ 80–100 cm).</li><li><b>Steigungs-/Auftrittsgrenzen</b> je Nutzung (notwendige Treppe: s ≤ 19/20 cm, a ≥ 23/26 cm).</li></ul>"}, {"id": "hf1d", "group": "hf1", "deck": "HF1D", "n": 5, "typ": "v", "kennung": "HF1d-3", "tax": "Wissen", "frage": "Was versteht man unter <b>Unterschneidung</b>, und wann ist sie erforderlich?", "erklaerung": "<p>Die Unterschneidung ist das Vorspringen der Trittstufe über die darunterliegende Stufe bzw. Setzstufe. Sie vergrößert die nutzbare Auftrittsfläche, ohne die Lauflänge zu verlängern.</p>", "loesung": "<p>Bei <b>offenen Treppen ohne Setzstufe</b> oder bei kleinem Auftritt sorgt die Unterschneidung dafür, dass der Fuß genug Platz findet.</p><div class=\"formula\">u ≥ 3 cm, wenn der Auftritt a &lt; 26 cm</div><p>So bleibt der effektive Gehbereich ausreichend groß und man stößt nicht an die Stufenkante.</p>"}, {"id": "hf1d", "group": "hf1", "deck": "HF1D", "n": 6, "typ": "p", "kennung": "HF1d-4", "tax": "Können", "frage": "Erklären Sie das <b>Stufenverziehen</b> bei gewendelten Treppen. Nennen Sie zeichnerische Methoden.", "erklaerung": "<p>In gewendelten Bereichen ändert sich die Stufenrichtung. Damit der Auftritt entlang der Gehlinie möglichst gleichmäßig bleibt, werden die Stufen <b>verzogen</b> – die Auftritte an der Innenwange werden kleiner, an der Außenwange größer, schön gleichmäßig übergehend.</p>", "loesung": "<p><b>Ziel:</b> gleichmäßiger Auftritt entlang der Gehlinie (ca. 30–40 cm vom inneren Handlauf bzw. Mitte).</p><p><b>Zeichnerische Methoden:</b></p><ul><li><b>Fluchtlinienverfahren (Bogenmethode):</b> Hilfslinie, auf der die Auftritte gleichmäßig übergehen.</li><li><b>Verhältnisverfahren / Proportionsmethode</b></li><li><b>Winkel- bzw. Kreisbogenmethode</b></li></ul><p>Zusätzlich gibt es das <b>rechnerische Verziehen</b>. Praktisch werden Wangen und Krümmlinge nach dem verzogenen Grundriss angerissen.</p>"}, {"id": "hf1d", "group": "hf1", "deck": "HF1D", "n": 7, "typ": "v", "kennung": "HF1d-3", "tax": "Wissen", "frage": "Welche <b>Holzfeuchte</b> sollte das Holz beim Einbau einer Innentreppe haben und warum?", "erklaerung": "<p>Holz arbeitet (schwindet/quillt) mit der Umgebungsfeuchte. Eine Innentreppe muss an das spätere Raumklima angepasst sein, sonst entstehen Risse, Fugen oder Knarren.</p>", "loesung": "<p>Einbau-Holzfeuchte: <b>12 % ± 2 %</b> (nach DIN 68368 für Treppenholz). Das entspricht dem Ausgleichsfeuchtebereich beheizter Wohnräume. So bleiben Schwind-/Quellbewegungen minimal → keine Risse, dauerhaft geschlossene Verbindungen.</p>"}, {"id": "hf1d", "group": "hf1", "deck": "HF1D", "n": 8, "typ": "v", "kennung": "HF1d-1", "tax": "Wissen", "frage": "Welche Anforderungen gelten an <b>Geländer und Handläufe</b>?", "erklaerung": "<p>Geländer sichern gegen Absturz und müssen Horizontalkräfte (Holmdruck) aufnehmen. Maße ergeben sich aus BauO/DIN 18065.</p>", "loesung": "<ul><li><b>Geländerhöhe:</b> i. d. R. ≥ 90 cm (bei Absturzhöhe &gt; 12 m ≥ 110 cm).</li><li><b>Füllstababstand:</b> ≤ 12 cm (Kindersicherheit – Kopf darf nicht durchpassen).</li><li><b>Holmdruck:</b> Geländer + Pfosten + Anschlüsse auf horizontale Linienlast bemessen (Wohnbau ca. 0,5–1,0 kN/m).</li><li><b>Handlauf:</b> griffsicher, durchgehend, gut umgreifbar.</li></ul>"}, {"id": "hf1e", "group": "hf1", "deck": "HF1E", "n": 1, "typ": "v", "kennung": "HF1e-1", "tax": "Werten", "frage": "Wovon hängt die <b>zulässige Druckspannung von Mauerwerk</b> als Auflager ab, und worauf ist beim Balkenauflager zu achten?", "erklaerung": "<p>Holzbalken/-stützen leiten Lasten punktuell ins Mauerwerk. Mauerwerk hat eine begrenzte Druckfestigkeit; bei zu kleiner Auflagerfläche entsteht Kantenpressung/Abplatzen.</p>", "loesung": "<ul><li>Zulässige Druckspannung hängt ab von <b>Steinfestigkeitsklasse</b>, <b>Mörtelgruppe</b> und <b>Schlankheit</b> der Wand (DIN 1053 / EC6).</li><li><b>Mindestauflagerlänge</b> einhalten (Last verteilen), ggf. <b>Lastverteilungssockel</b>/Mauerlatte/Beton-Auflagerstein.</li><li><b>Feuchtigkeitssperre</b> zwischen Holz und Mauerwerk (Holzschutz).</li><li>Kantenpressung vermeiden → mittige Lasteinleitung.</li></ul>"}, {"id": "hf1e", "group": "hf1", "deck": "HF1E", "n": 2, "typ": "v", "kennung": "HF1e-1", "tax": "Werten", "frage": "Warum ist zwischen <b>Holz und Mauerwerk/Beton</b> eine Feuchtigkeitssperre erforderlich, und welche Materialien kommen infrage?", "erklaerung": "<p>Mineralische Baustoffe können Feuchte aufnehmen und an das Holz weitergeben (kapillar, Kondensat). Dauerfeuchtes Holz ist durch Pilze gefährdet (Fäulnis).</p>", "loesung": "<p><b>Funktion:</b> trennt das Holz kapillar vom feuchtebelasteten Baustoff → Schutz vor Pilzbefall, dauerhafter konstruktiver Holzschutz (GK 0 anstrebbar).</p><p><b>Materialien:</b> Bitumen-Dachbahn/Bitumenpappe, PE-Folie, EPDM-Streifen, Dichtungsbahnen. Bei Schwellen zusätzlich Belüftung/Tropfkante einplanen.</p>"}, {"id": "hf1e", "group": "hf1", "deck": "HF1E", "n": 3, "typ": "v", "kennung": "HF1e-1", "tax": "Wissen", "frage": "Was bedeutet die Betonfestigkeitsklasse <b>C 20/25</b>?", "erklaerung": "<p>Beton wird nach charakteristischer Druckfestigkeit klassifiziert – ermittelt an zwei Probekörperformen. Die Klasse steht auf Plänen und ist für die Beurteilung als Auflager wichtig.</p>", "loesung": "<p><b>C</b> = Normal-/Schwerbeton (concrete). Die Zahlen sind die charakteristische Druckfestigkeit nach 28 Tagen in N/mm²:</p><ul><li><b>20</b> = Zylinderdruckfestigkeit f<sub>ck,cyl</sub> (Zylinder Ø150/300 mm)</li><li><b>25</b> = Würfeldruckfestigkeit f<sub>ck,cube</sub> (Würfel 150 mm)</li></ul><p>Höhere Klasse = höhere Tragfähigkeit/Dauerhaftigkeit. Für Auflager prüfen, ob die Druckfestigkeit für die Lasteinleitung reicht.</p>"}, {"id": "hf1e", "group": "hf1", "deck": "HF1E", "n": 4, "typ": "v", "kennung": "HF1e-1", "tax": "Wissen", "frage": "Was sind <b>Expositionsklassen</b> und wofür werden sie gebraucht?", "erklaerung": "<p>Expositionsklassen beschreiben die Umweltbedingungen, denen ein Stahlbetonbauteil ausgesetzt ist. Sie steuern Betonqualität, Mindestbetondeckung und Rissbreitenbegrenzung – wichtig für die Dauerhaftigkeit.</p>", "loesung": "<ul><li><b>X0</b> kein Korrosionsrisiko · <b>XC</b> Karbonatisierung (Feuchte/Luft) · <b>XD/XS</b> Chloride (Streusalz/Meer) · <b>XF</b> Frost · <b>XA</b> chemischer Angriff.</li><li>Beispiel: Außenbauteil bewittert → mind. XC4/XF1.</li><li>Folge: höhere Betonfestigkeitsklasse + größere Betondeckung der Bewehrung (Korrosionsschutz).</li></ul>"}, {"id": "hf1e", "group": "hf1", "deck": "HF1E", "n": 5, "typ": "v", "kennung": "HF1e-2", "tax": "Werten", "frage": "Welche Bedeutung hat <b>DIN 18202 (Maßtoleranzen)</b> für den Zimmerer beim Aufmaß der Vorgewerke?", "erklaerung": "<p>Vorgewerke (Rohbau) sind nie exakt maßhaltig. DIN 18202 legt zulässige Toleranzen für Ebenheit, Winkligkeit und Maße fest. Der Zimmerer muss prüfen, ob die Abweichungen im Rahmen sind, bevor er montiert.</p>", "loesung": "<ul><li>Regelt <b>Grenzabmaße</b> (Längen, Höhen) und <b>Ebenheits-/Winkeltoleranzen</b>.</li><li><b>Vor Montage prüfen:</b> Sind Wände lot- und fluchtgerecht? Decke eben genug? → sonst Ausgleich einplanen (Futterhölzer, Unterlagen).</li><li>Toleranzüberschreitung des Vorgewerks <b>dokumentieren und anmelden</b> (Bedenkenanzeige nach VOB) – sonst haftet evtl. der Zimmerer.</li></ul>"}, {"id": "hf1e", "group": "hf1", "deck": "HF1E", "n": 6, "typ": "p", "kennung": "HF1e-1", "tax": "Können", "frage": "Ein Deckenbalken (b = 10 cm) liegt mit F = 12 kN auf Mauerwerk auf, dessen zulässige Druckspannung σ<sub>zul</sub> = 1,2 N/mm² beträgt. <b>Ermitteln Sie die erforderliche Auflagerlänge.</b>", "erklaerung": "<p>Die Auflagerfläche (Breite × Auflagerlänge) muss so groß sein, dass die Pressung die zulässige Druckspannung des Mauerwerks nicht übersteigt.</p><div class=\"formula\">σ = F / (b · l<sub>A</sub>) ≤ σ<sub>zul</sub> → l<sub>A</sub> ≥ F / (b · σ<sub>zul</sub>)</div>", "loesung": "<div class=\"formula\">l<sub>A</sub> ≥ 12 000 N / (100 mm · 1,2 N/mm²) = 12 000 / 120 = <b>100 mm = 10 cm</b></div><p>Rechnerisch reichen 10 cm; konstruktiv ist meist eine <b>Mindestauflagerlänge von 11,5 cm</b> (½ Stein) üblich. → gewählt <b>l<sub>A</sub> = 11,5 cm</b>, mit Feuchtigkeitssperre.</p>"}, {"id": "hf1e", "group": "hf1", "deck": "HF1E", "n": 7, "typ": "v", "kennung": "HF1e-1", "tax": "Werten", "frage": "Welche <b>Schutzmaßnahmen bei erdberührendem oder bewittertem Holz</b> gibt es, und welche Rangfolge gilt (DIN 68800)?", "erklaerung": "<p>DIN 68800 ordnet Holzbauteile in Gebrauchsklassen (GK 0–5) nach Feuchtebelastung ein. Vorrang hat immer der <b>konstruktive (bauliche) Holzschutz</b> vor dem chemischen.</p>", "loesung": "<ul><li><b>Gebrauchsklassen GK 0–5:</b> GK 0 (trocken, kein Befall möglich) bis GK 4/5 (erd-/wasserberührt).</li><li><b>Rangfolge:</b> 1. <b>konstruktiv</b> (kein Bodenkontakt, Tropfkante, Belüftung, Abdeckung, Gefälle); 2. nur falls nötig <b>chemisch</b> (Imprägnierung passend zur GK).</li><li>Erdberührend: druckimprägniert oder dauerhafte Holzart (Kernholz Eiche/Lärche) + konstruktive Trennung vom Erdreich.</li></ul>"}, {"id": "hf1e", "group": "hf1", "deck": "HF1E", "n": 8, "typ": "v", "kennung": "HF1e-2", "tax": "Wissen", "frage": "Wie wird ein <b>eingespannter Stützenfuß</b> einer Hallenstütze ausgebildet?", "erklaerung": "<p>Bei Hallen mit eingespannten Stützen (Kragstützen) muss der Fußpunkt das <b>Einspannmoment</b> ins Fundament übertragen – das verlangt eine biegesteife Verbindung.</p>", "loesung": "<ul><li><b>Innenliegende Stahlblechlaschen</b> (Schlitzbleche) mit Stabdübeln, eingelassen in die Holzstütze.</li><li>Anschluss an eine <b>Fußplatte mit Ankerbolzen</b> im Stahlbetonfundament.</li><li>Das Moment wird als <b>Kräftepaar</b> (Zug-/Druckanker) ins Fundament geleitet.</li><li>Korrosionsschutz und Trennung vom Erdreich (Holz nicht in Spritzwasserzone).</li></ul>"}, {"id": "hf1f", "group": "hf1", "deck": "HF1F", "n": 1, "typ": "p", "kennung": "HF1f-1", "tax": "Können", "frage": "Berechnen Sie den <b>U-Wert</b> folgender Wand (innen→außen): 12,5 mm Gipskarton (λ=0,25), 160 mm Holzfaserdämmung zwischen Ständern – vereinfacht reine Dämmung (λ=0,040), 15 mm Holzfaserplatte (λ=0,050). R<sub>si</sub>=0,13; R<sub>se</sub>=0,04.", "erklaerung": "<p>Der U-Wert beschreibt den Wärmedurchgang. Man berechnet je Schicht den Widerstand R = d/λ, addiert die Übergangswiderstände innen/außen und bildet den Kehrwert der Summe.</p><div class=\"formula\">R = d/λ &nbsp;|&nbsp; R<sub>T</sub> = R<sub>si</sub> + ΣR + R<sub>se</sub> &nbsp;|&nbsp; U = 1/R<sub>T</sub></div>", "loesung": "<p><b>Einzelwiderstände:</b></p><ul><li>Gipskarton: 0,0125/0,25 = 0,050</li><li>Dämmung: 0,160/0,040 = 4,000</li><li>Holzfaserplatte: 0,015/0,050 = 0,300</li></ul><div class=\"formula\">R<sub>T</sub> = 0,13 + 0,050 + 4,000 + 0,300 + 0,04 = <b>4,52 m²K/W</b></div><div class=\"formula\">U = 1 / 4,52 = <b>0,221 W/(m²·K)</b></div><p>Liegt unter GEG-Grenzwert 0,24 → ✓ (Hinweis: real mindern die Holzständer den Wert geringfügig – genauer Nachweis mit Gefachanteil).</p>"}, {"id": "hf1f", "group": "hf1", "deck": "HF1F", "n": 2, "typ": "v", "kennung": "HF1f-2", "tax": "Wissen", "frage": "Nennen Sie die wichtigsten <b>U-Wert-Grenzwerte des GEG 2024</b> (Anlage 7, Bestandsänderung) für Wand, Dach und Fenster.", "erklaerung": "<p>Werden Bauteile im Bestand erneuert (z. B. Dach neu gedämmt), gelten Höchstwerte für den U-Wert. Diese sind klassische Prüfungs-Merkwerte.</p>", "loesung": "<table><tr><th>Bauteil</th><th>U<sub>max</sub> [W/(m²K)]</th></tr><tr><td>Außenwand</td><td><b>0,24</b></td></tr><tr><td>Dachflächen / oberste Geschossdecke</td><td><b>0,24</b></td></tr><tr><td>Dach mit Abdichtung (Flachdach)</td><td><b>0,20</b></td></tr><tr><td>Fenster / Fenstertüren</td><td><b>1,30</b></td></tr><tr><td>Dachflächenfenster</td><td><b>1,40</b></td></tr></table>"}, {"id": "hf1f", "group": "hf1", "deck": "HF1F", "n": 3, "typ": "v", "kennung": "HF1f-3", "tax": "Werten", "frage": "Erklären Sie das <b>Glaser-Verfahren</b>. Was wird damit nachgewiesen?", "erklaerung": "<p>Das Glaser-Verfahren prüft rechnerisch, ob in einer Konstruktion <b>Tauwasser</b> ausfällt und ob es im Sommer wieder austrocknet. Grundlage ist der Vergleich von tatsächlichem Dampfdruck und Sättigungsdampfdruck schichtweise.</p>", "loesung": "<ol><li><b>Temperaturverlauf</b> schichtweise berechnen (über die R-Werte).</li><li>Zu jeder Temperatur den <b>Sättigungsdampfdruck p<sub>s</sub></b> bestimmen.</li><li><b>Tatsächlichen Dampfdruck p</b> über die s<sub>d</sub>-Werte (Diffusionswiderstände) ermitteln.</li><li>Wo <b>p ≥ p<sub>s</sub></b> → Kondensation (Tauwasserebene).</li></ol><p><b>Bewertung:</b> Tauwassermenge (Winter) muss kleiner sein als die Verdunstungsmenge (Sommer), und Grenzwerte dürfen nicht überschritten werden. <b>Regel:</b> innen → außen diffusionsoffener (abnehmende s<sub>d</sub>).</p>"}, {"id": "hf1f", "group": "hf1", "deck": "HF1F", "n": 4, "typ": "v", "kennung": "HF1f-3", "tax": "Werten", "frage": "Unterscheiden Sie <b>Dampfbremse und Dampfsperre</b> und erklären Sie die Regel „innen dichter als außen\".", "erklaerung": "<p>Auf der warmen Innenseite muss der Eintritt von Wasserdampf in die Dämmung begrenzt werden, während die Konstruktion nach außen austrocknen können soll. Maß dafür ist der <b>s<sub>d</sub>-Wert</b> (wasserdampfdiffusionsäquivalente Luftschichtdicke in m).</p>", "loesung": "<ul><li><b>Dampfbremse:</b> s<sub>d</sub> ≈ 0,5–10 m – begrenzt Dampfeintrag, lässt Rücktrocknung zu (oft feuchtevariabel).</li><li><b>Dampfsperre:</b> s<sub>d</sub> &gt; 100 m – nahezu dampfdicht (z. B. Alukaschierung, Kühlräume).</li></ul><p><b>Regel:</b> innen hoher s<sub>d</sub> (z. B. ≥ 2 m), außen niedriger s<sub>d</sub> (≤ 0,3 m) → Dampf, der eindringt, kann nach außen entweichen. Verhältnis Faustregel ca. <b>innen:außen ≥ 6:1</b>.</p>"}, {"id": "hf1f", "group": "hf1", "deck": "HF1F", "n": 5, "typ": "v", "kennung": "HF1f-7", "tax": "Werten", "frage": "Bei einem <b>Kühlraum</b> wird die Dampfsperre auf der Außenseite (warme Seite) angeordnet – warum?", "erklaerung": "<p>Wasserdampf wandert immer von <b>warm nach kalt</b>. Beim normalen Wohnraum ist innen warm. Beim Kühlraum ist es umgekehrt: außen ist es wärmer und feuchter als innen.</p>", "loesung": "<p>Da der Dampf von der warmen Außenseite zur kalten Innenseite drängt, muss die <b>Dampfsperre auf der warmen Außenseite</b> liegen – sie hält den Dampf <b>vor</b> der Dämmung ab. Läge sie innen, würde Feuchte in die Dämmung eindringen und am kalten Innenraum kondensieren → Durchfeuchtung, Verlust der Dämmwirkung, Eisbildung. <b>Merksatz:</b> Dampfsperre immer auf die <b>warme Seite</b>.</p>"}, {"id": "hf1f", "group": "hf1", "deck": "HF1F", "n": 6, "typ": "p", "kennung": "HF1f-4", "tax": "Wissen", "frage": "Erklären Sie die Schallschutz-Kennwerte <b>R'<sub>w</sub></b> und <b>L'<sub>n,w</sub></b>. Nennen Sie die Mindestanforderungen (DIN 4109) für Wohnungstrennwand und -trenndecke.", "erklaerung": "<p>Im Schallschutz unterscheidet man Luftschall (Sprache, Musik) und Trittschall (Gehen). Für beide gibt es bewertete Einzahlwerte – aber mit gegensätzlicher „Richtung\".</p>", "loesung": "<ul><li><b>R'<sub>w</sub></b> = bewertetes Bau-Schalldämm-Maß (Luftschall) – <b>je höher, desto besser</b>.</li><li><b>L'<sub>n,w</sub></b> = bewerteter Norm-Trittschallpegel – <b>je kleiner, desto besser</b>.</li></ul><p><b>Mindestanforderungen DIN 4109-1 (Neubau):</b></p><table><tr><th>Bauteil</th><th>Anforderung</th></tr><tr><td>Wohnungstrennwand</td><td>R'<sub>w</sub> ≥ <b>53 dB</b></td></tr><tr><td>Wohnungstrenndecke</td><td>R'<sub>w</sub> ≥ <b>54 dB</b>, L'<sub>n,w</sub> ≤ <b>50 dB</b></td></tr><tr><td>Haustrennwand (Reihenhaus)</td><td>R'<sub>w</sub> ≥ <b>59–62 dB</b></td></tr></table>"}, {"id": "hf1f", "group": "hf1", "deck": "HF1F", "n": 7, "typ": "v", "kennung": "HF1f-4", "tax": "Werten", "frage": "Erklären Sie <b>Massegesetz</b> und <b>Masse-Feder-Masse-System</b> im Schallschutz. Was bewirkt Entkopplung?", "erklaerung": "<p>Es gibt zwei grundlegende Wege, Luftschall zu dämmen: über Masse (einschalig) oder über mehrschalige, federnd getrennte Aufbauten – Letzteres ist im leichten Holzbau der Schlüssel.</p>", "loesung": "<ul><li><b>Massegesetz (einschalig):</b> Je mehr Masse pro Fläche, desto besser die Dämmung – Verdopplung der Masse ≈ +6 dB. Im Holzbau allein nicht effizient (zu leicht).</li><li><b>Masse-Feder-Masse:</b> zwei Schalen, getrennt durch eine „Feder\" (Dämmung/Luft). Wirkt wie ein Tiefpassfilter und dämmt deutlich besser als die reine Masse – <b>Prinzip im Holzbau</b>.</li><li><b>Entkopplung:</b> Unterbrechung starrer Verbindungen (Federschienen, elastische Abhänger, getrennte Ständer) → verhindert Körperschall-Brücken. Achtung <b>Flankenübertragung</b>.</li></ul>"}, {"id": "hf1f", "group": "hf1", "deck": "HF1F", "n": 8, "typ": "p", "kennung": "HF1f-4", "tax": "Können", "frage": "Eine Holzbalkendecke soll im <b>Trittschall</b> verbessert werden. Nennen Sie wirksame Maßnahmen und ordnen Sie sie ein.", "erklaerung": "<p>Holzdecken sind leicht und im tiefen Frequenzbereich (&lt;100 Hz) kritisch. Trittschall verbessert man durch Masse, Entkopplung und einen schwimmenden Aufbau.</p>", "loesung": "<ul><li><b>Schwimmender Estrich</b> auf Trittschalldämmung: dynamische Steifigkeit s' ≤ 10 MN/m³ (optimal ≤ 7–8) – entkoppelt Gehfläche von der Rohdecke.</li><li><b>Rohdeckenbeschwerung</b> (Splitt, Gehwegplatten 100–300 kg/m²): mehr Masse → tiefe Frequenzen.</li><li><b>Abgehängte Unterdecke mit Federschienen</b>: bis ca. +25 dB Verbesserung.</li><li><b>Trennung/Entkopplung</b> der Schichten, Randdämmstreifen (keine Schallbrücken zum Estrich).</li></ul><p>Kombination dieser Maßnahmen bringt am meisten; einzelne Maßnahme reicht für hohe Anforderungen meist nicht.</p>"}, {"id": "hf1f", "group": "hf1", "deck": "HF1F", "n": 9, "typ": "v", "kennung": "HF1f-5", "tax": "Wissen", "frage": "Erklären Sie die <b>Feuerwiderstandsklassen</b> (R, E, I) und die beiden Wege, im Holzbau einen Feuerwiderstand zu erreichen.", "erklaerung": "<p>Der Feuerwiderstand gibt an, wie lange ein Bauteil im Brandfall seine Funktion behält. Die Buchstaben benennen die Funktion, die Zahl die Minuten.</p>", "loesung": "<ul><li><b>R</b> = Tragfähigkeit (résistance), <b>E</b> = Raumabschluss, <b>I</b> = Wärmedämmung; Zahl = Minuten (R30, R60, R90).</li></ul><p><b>Zwei Wege im Holzbau:</b></p><ol><li><b>Abbrandmethode (Überdimensionierung):</b> Querschnitt so groß, dass der Restquerschnitt nach Abbrand (≈0,65–0,7 mm/min) die Last noch trägt.</li><li><b>Kapselung/Bekleidung:</b> Brandschutzplatten (Gipsfeuerschutz, Kalziumsilikat) schützen das Holz – Klasse K (z. B. K<sub>2</sub>30 = 30 min Schutz des dahinterliegenden Holzes).</li></ol>"}, {"id": "hf1f", "group": "hf1", "deck": "HF1F", "n": 10, "typ": "v", "kennung": "HF1f-5", "tax": "Werten", "frage": "Was sind <b>Gebäudeklassen</b>, ab welchem Abstand ist eine <b>Brandwand</b> nötig, und welche Baustoffklasse hat Holz?", "erklaerung": "<p>Die Bauordnung stuft Gebäude nach Höhe/Nutzung in Gebäudeklassen (GK) ein; daraus folgen die Brandschutzanforderungen. Brandwände verhindern Brandübertragung zwischen Gebäuden/Abschnitten.</p>", "loesung": "<ul><li><b>Gebäudeklassen GK 1–5</b> (MBO/LBO) nach Höhe, Fläche, Nutzungseinheiten. <b>GK 4:</b> hochfeuerhemmende Bauteile (REI 60) aus brennbaren Baustoffen zulässig → Holzbau möglich. <b>Aktuell (Muster-Holzbau-Richtlinie 2021):</b> Holz ist inzwischen auch in <b>GK 4 und GK 5</b> für feuerbeständige Bauteile (REI 90) zulässig, sofern eine brandschutztechnisch wirksame <b>Kapselung</b> (K<sub>2</sub>60) das Holz schützt.</li><li><b>Brandwand</b> erforderlich bei Gebäudeabstand <b>&lt; 5,00 m</b> (bzw. an Grundstücksgrenze); Anforderung <b>F90-A / REI 90-M</b>, nicht brennbar.</li><li><b>Baustoffklasse Holz:</b> normal entflammbar – <b>D-s2,d0</b> (EN 13501-1) bzw. <b>B2</b> (DIN 4102).</li><li>Stahl verliert ab ca. 500 °C stark an Festigkeit → Verbindungsmittel schützen.</li></ul>"}, {"id": "hf1g", "group": "hf1", "deck": "HF1G", "n": 1, "typ": "v", "kennung": "HF1g-1", "tax": "Erkennen", "frage": "Unterscheiden Sie <b>Luftdichtheitsebene</b> und <b>Winddichtigkeitsebene</b>: Lage und Funktion.", "erklaerung": "<p>Eine Holzkonstruktion braucht zwei getrennte Dichtungsebenen mit unterschiedlichen Aufgaben – innen gegen warme Raumluft, außen gegen kalte Außenluft.</p>", "loesung": "<ul><li><b>Luftdichtheitsebene (raumseitig):</b> verhindert, dass warme, feuchte Raumluft <b>in</b> die Konstruktion strömt (Konvektion) → Schutz vor Tauwasser. Liegt auf der <b>warmen Innenseite</b> der Dämmung.</li><li><b>Winddichtigkeitsebene (außenseitig):</b> verhindert, dass kalte Außenluft die Dämmung <b>durchströmt</b> (Auskühlung, Wärmeverlust). Liegt <b>außen</b> auf der Dämmung.</li></ul>"}, {"id": "hf1g", "group": "hf1", "deck": "HF1G", "n": 2, "typ": "v", "kennung": "HF1g-1", "tax": "Werten", "frage": "Warum ist die <b>Konvektion</b> (Luftströmung) für den Feuchteeintrag gefährlicher als die <b>Diffusion</b>?", "erklaerung": "<p>Feuchte gelangt auf zwei Wegen in die Konstruktion: durch Diffusion (durch das Material) und durch Konvektion (mit strömender Luft durch Fugen/Leckagen). Die Mengen unterscheiden sich dramatisch.</p>", "loesung": "<p>Durch eine <b>Fuge/Leckage</b> transportiert strömende Luft ein Vielfaches der Feuchtemenge gegenüber reiner Diffusion durch die Fläche – in der Praxis oft das <b>10- bis 100-fache</b>. Deshalb ist die luftdichte Ausführung (verklebte Stöße, Anschlüsse) der wichtigste Tauwasserschutz. <b>Merke:</b> „Diffusion ist planbar, Konvektion ist der Schaden.\"</p>"}, {"id": "hf1g", "group": "hf1", "deck": "HF1G", "n": 3, "typ": "p", "kennung": "HF1g-2", "tax": "Können", "frage": "Erklären Sie den <b>Blower-Door-Test</b>: Ablauf, Messgröße und Grenzwerte des n₅₀-Wertes.", "erklaerung": "<p>Mit der Differenzdruck-Messung (Blower-Door) wird die Luftdichtheit eines Gebäudes geprüft. Ein Ventilator erzeugt 50 Pa Über-/Unterdruck; gemessen wird, wie viel Luft pro Stunde durch die Leckagen strömt.</p><div class=\"formula\">n₅₀ = V̇₅₀ / V<sub>Gebäude</sub> &nbsp;[h⁻¹]</div>", "loesung": "<ul><li><b>Ablauf:</b> Ventilator in Tür/Fenster, Gebäude auf 50 Pa Druckdifferenz, Volumenstrom messen (Über- und Unterdruck).</li><li><b>n₅₀</b> = Luftwechselrate bei 50 Pa (wie oft das Luftvolumen pro Stunde ausgetauscht wird).</li><li><b>Grenzwerte:</b><ul><li>ohne Lüftungsanlage (Fensterlüftung): n₅₀ ≤ <b>3,0 h⁻¹</b></li><li>mit Lüftungsanlage: n₅₀ ≤ <b>1,5 h⁻¹</b></li><li>Passivhaus: n₅₀ ≤ <b>0,6 h⁻¹</b></li></ul></li></ul>"}, {"id": "hf1g", "group": "hf1", "deck": "HF1G", "n": 4, "typ": "v", "kennung": "HF1g-3", "tax": "Wissen", "frage": "Welche <b>Materialien</b> eignen sich für die Luftdichtung (innen) und für die Winddichtung (außen)?", "erklaerung": "<p>Beide Ebenen lassen sich mit Bahnen oder Plattenwerkstoffen herstellen – entscheidend ist die dauerhafte Verklebung der Stöße und Anschlüsse.</p>", "loesung": "<ul><li><b>Luftdichtung innen:</b> Dampfbrems-/Luftdichtungsfolien (Stöße verklebt), OSB-/Spanplatten mit abgeklebten Fugen, Gipskarton-/Gipsfaserplatten mit verspachtelten Stößen, Innenputz auf Mauerwerk.</li><li><b>Winddichtung außen:</b> diffusionsoffene Unterspann-/Unterdeckbahnen (s<sub>d</sub> ≤ 0,2 m), Holzfaserdämmplatten, diffusionsoffene Holzwerkstoffplatten.</li><li><b>Verbindung:</b> systemgeprüfte Klebebänder, Klebemassen, Manschetten.</li></ul>"}, {"id": "hf1g", "group": "hf1", "deck": "HF1G", "n": 5, "typ": "v", "kennung": "HF1g-3", "tax": "Werten", "frage": "Warum wird die <b>Installationsebene</b> raumseitig <b>vor</b> der Luftdichtheitsebene angeordnet?", "erklaerung": "<p>Spätere Elektro-/Sanitärinstallationen (Dosen, Leitungen) durchdringen sonst die Luftdichtungsfolie und erzeugen viele Leckagen. Eine zusätzliche Ebene löst das Problem.</p>", "loesung": "<p>Die <b>Installationsebene</b> (Lattung 4–6 cm raumseitig der Folie, oft gedämmt) nimmt Leitungen und Dosen auf, <b>ohne</b> die Luftdichtheitsebene zu durchstoßen. Vorteile:</p><ul><li>Luftdichtung bleibt <b>unverletzt</b> → dauerhaft dicht.</li><li>Zusätzlicher Dämmwert.</li><li>Folie wird vor mechanischer Beschädigung geschützt.</li></ul>"}, {"id": "hf1g", "group": "hf1", "deck": "HF1G", "n": 6, "typ": "v", "kennung": "HF1g-3", "tax": "Werten", "frage": "Erläutern Sie das <b>Gefälle der Diffusionswiderstände</b> (s<sub>d</sub>-Werte) im Wand-/Dachaufbau. Geben Sie Beispielwerte an.", "erklaerung": "<p>Damit eingedrungene Feuchte nach außen austrocknen kann, müssen die Schichten von innen nach außen <b>diffusionsoffener</b> werden – der Dampfwiderstand nimmt ab.</p>", "loesung": "<p><b>Regel:</b> innen hoher s<sub>d</sub>, außen niedriger s<sub>d</sub>.</p><ul><li>Beispiel: innen Dampfbremse <b>s<sub>d</sub> ≈ 2–10 m</b>, außen Unterdeckbahn <b>s<sub>d</sub> ≤ 0,2 m</b>.</li><li>Feuchtevariable Dampfbremsen passen ihren s<sub>d</sub> der Jahreszeit an (winter dicht, sommer offen → bessere Rücktrocknung).</li></ul><div class=\"formula\">s<sub>d</sub> = µ · d &nbsp;(µ = Diffusionswiderstandszahl, d = Schichtdicke)</div>"}, {"id": "hf1g", "group": "hf1", "deck": "HF1G", "n": 7, "typ": "v", "kennung": "HF1g-3", "tax": "Wissen", "frage": "Wo liegen die <b>typischen Schwachstellen</b> der Luftdichtheit, und wie werden sie ausgeführt?", "erklaerung": "<p>Leckagen treten fast immer an Anschlüssen und Durchdringungen auf, nicht in der Fläche. Diese Details müssen sorgfältig geplant werden.</p>", "loesung": "<ul><li><b>Durchdringungen:</b> Rohre, Kabel, Kaminzüge → Manschetten/Klebebänder.</li><li><b>Anschlüsse:</b> Fenster/Türen, Trauf, Giebel, First, Innenwände → Folie anschließen und verkleben.</li><li><b>Folienstöße:</b> mit Überlappung über/unter der Lattung, vollflächig verklebt.</li><li><b>Wand-/Decken-Übergänge</b> und Steckdosen (luftdichte Dosen oder Installationsebene).</li></ul>"}, {"id": "hf1g", "group": "hf1", "deck": "HF1G", "n": 8, "typ": "v", "kennung": "HF1g-1", "tax": "Wissen", "frage": "Welche <b>Normen</b> regeln die Luftdichtheit, und welcher Zusammenhang besteht zu DIN 68800-2 (Holzschutz)?", "erklaerung": "<p>Die Luftdichtheit ist sowohl energetisch (GEG) als auch für den Feuchteschutz (Holzschutz) relevant – eine luftdichte Hülle vermeidet Tauwasser und damit Pilzgefahr.</p>", "loesung": "<ul><li><b>DIN 4108-7:</b> Planung und Ausführung der Luftdichtheit, Anschluss-/Detailregeln.</li><li><b>GEG/EnEV:</b> fordert Nachweis der Luftdichtheit, wenn reduzierte Lüftungswärmeverluste angesetzt werden.</li><li><b>DIN 68800-2:</b> Bei raumseitig luftdichter, fachgerecht geplanter Ausführung ist <b>Wasserdampfkonvektion ausgeschlossen</b> → Einstufung in <b>GK 0</b> möglich (kein chemischer Holzschutz nötig).</li></ul>"}, {"id": "hf1h", "group": "hf1", "deck": "HF1H", "n": 1, "typ": "v", "kennung": "HF1h-1", "tax": "Wissen", "frage": "Beschreiben Sie Aufbau und Vorteile eines <b>Stegträgers (TJI-Träger)</b>.", "erklaerung": "<p>Stegträger sind industriell gefertigte I-Profile aus Holzwerkstoffen. Sie ersetzen Vollholzsparren/-balken bei großen Spannweiten und in der Gebäudehülle.</p>", "loesung": "<ul><li><b>Aufbau:</b> Ober- und Untergurt aus <b>Furnierschichtholz (LVL)</b> oder KVH, dazwischen ein dünner <b>Steg aus OSB/HDF</b> (I-Querschnitt).</li><li><b>Vorteile:</b> sehr <b>leicht</b> bei hoher Tragfähigkeit; große Höhen für viel Dämmung; <b>minimale Wärmebrücke</b> (dünner Steg); maßhaltig, kein Schwinden/Verdrehen; große Stützweiten.</li><li>Einsatz: Sparren, Deckenbalken, Wandständer in Passivhaus-Wänden.</li></ul>"}, {"id": "hf1h", "group": "hf1", "deck": "HF1H", "n": 2, "typ": "v", "kennung": "HF1h-1", "tax": "Werten", "frage": "Vergleichen Sie <b>Aufsparrendämmung und Zwischensparrendämmung</b> (Vor-/Nachteile).", "erklaerung": "<p>Bei der Dachdämmung kann die Dämmung zwischen oder über den Sparren liegen. Das beeinflusst Wärmebrücken, Optik und Aufwand.</p>", "loesung": "<table><tr><th></th><th>Aufsparrendämmung</th><th>Zwischensparrendämmung</th></tr><tr><td>Lage</td><td>über den Sparren (durchgehend)</td><td>im Gefach zwischen Sparren</td></tr><tr><td>Wärmebrücke</td><td><b>keine</b> (Sparren bleibt warm)</td><td>Sparren wirkt als Wärmebrücke</td></tr><tr><td>Optik</td><td>Sparren innen sichtbar möglich</td><td>Sparren verdeckt</td></tr><tr><td>Aufwand/Kosten</td><td>höher; Dach wird höher</td><td>günstiger, einfacher</td></tr></table><p>Oft Kombination beider Systeme für hohe Dämmwerte.</p>"}, {"id": "hf1h", "group": "hf1", "deck": "HF1H", "n": 3, "typ": "p", "kennung": "HF1h-1", "tax": "Können", "frage": "Skizzieren/benennen Sie den <b>Schichtaufbau eines extensiv begrünten Flachdachs</b> (von unten nach oben) und nennen Sie die statische Zusatzlast.", "erklaerung": "<p>Das Gründach ist ein Prüfungsklassiker. Der Schichtaufbau muss Abdichtung schützen, Wasser speichern/ableiten und durchwurzelungsfest sein. Die Zusatzlast ist statisch zu berücksichtigen.</p>", "loesung": "<p><b>Von unten nach oben:</b></p><ol><li>Dampfsperre</li><li>Wärmedämmung</li><li>Abdichtung (durchwurzelungsfest oder mit Wurzelschutzbahn)</li><li>Schutz-/Speichervlies</li><li>Dränschicht</li><li>Filtervlies</li><li>Vegetationsschicht (Substrat)</li><li>Bepflanzung</li></ol><p><b>Statische Zusatzlast:</b> Extensivbegrünung ca. <b>bis 150 kg/m²</b> (wassergesättigt) → im Tragwerk ansetzen.</p>"}, {"id": "hf1h", "group": "hf1", "deck": "HF1H", "n": 4, "typ": "v", "kennung": "HF1h-1", "tax": "Werten", "frage": "Warum ist die <b>Ausklinkung eines BSH-Trägers am Auflager</b> problematisch und wie wird verstärkt?", "erklaerung": "<p>Wird ein Träger am Auflager unten ausgeklinkt (z. B. für Höhenanschluss), entsteht an der einspringenden Ecke eine Spannungsspitze – Gefahr von <b>Querzugrissen</b> rechtwinklig zur Faser.</p>", "loesung": "<ul><li><b>Problem:</b> An der Ausklinkungsecke wirken hohe <b>Querzug- und Schubspannungen</b> → Holz reißt entlang der Faser auf (Querzug ist die schwächste Beanspruchung von Holz).</li><li><b>Verstärkung:</b><ul><li>eingeleimte/eingeschraubte <b>Gewindestangen</b> oder <b>Vollgewindeschrauben</b> senkrecht zur Rissrichtung</li><li>aufgeklebte/aufgenagelte <b>Sperrholz-/Stahllaschen</b></li><li>Ausklinkungshöhe begrenzen, Ecke ausrunden</li></ul></li></ul>"}, {"id": "hf1h", "group": "hf1", "deck": "HF1H", "n": 5, "typ": "v", "kennung": "HF1h-1", "tax": "Wissen", "frage": "Wie werden <b>Brettstapelelemente</b> verbunden und was ist beim Schwindverhalten zu beachten?", "erklaerung": "<p>Brettstapel/Brettsperrholz bestehen aus vielen hochkant stehenden Brettern. Die Verbindung und das Quell-/Schwindverhalten quer zur Faser sind planungsrelevant.</p>", "loesung": "<ul><li><b>Verbindung:</b> Nut & Feder, Holzdübel/Buchendübel, Stabdübel oder Vernagelung der einzelnen Lamellen.</li><li><b>Schwinden/Quellen:</b> quer zur Faser deutlich größer als längs → bei breiten Elementen Schwindfugen/Bewegungen einplanen, Einbauholzfeuchte beachten.</li><li>Vorteil: massive, diffusionsfähige Bauteile mit guter Speichermasse.</li></ul>"}, {"id": "hf1h", "group": "hf1", "deck": "HF1H", "n": 6, "typ": "p", "kennung": "HF1h-2", "tax": "Werten", "frage": "Was ist beim Einplanen einer <b>PV- oder Solarthermie-Anlage</b> auf einem Sparrendach konstruktiv zu beachten?", "erklaerung": "<p>Dachanlagen bringen Zusatzlasten und Durchdringungen. Befestigung und Abdichtung müssen dauerhaft und statisch korrekt sein.</p>", "loesung": "<ul><li><b>Statische Mehrbelastung:</b> PV ca. <b>15 kg/m²</b> + Sog-/Drucklasten durch Wind → Sparren/Anker prüfen.</li><li><b>Befestigung:</b> Dachhaken auf den <b>Sparren/Konterlattung</b> (nicht nur Lattung), Lastweiterleitung ins Tragwerk.</li><li><b>Durchdringungen</b> der Dachhaut <b>wasserdicht</b> ausführen (Solthermie-Leitungen, Dachhaken).</li><li>Solarthermie: zusätzlich Verschattung/Verrohrung; PV: Leitungsführung + Erdung/Blitzschutz.</li></ul>"}, {"id": "hf1h", "group": "hf1", "deck": "HF1H", "n": 7, "typ": "v", "kennung": "HF1h-1", "tax": "Können", "frage": "Welche Planungspunkte sind bei <b>vorgefertigten Holzrahmenbau-Wandelementen</b> (Kranmontage) zu beachten?", "erklaerung": "<p>Großelemente werden im Werk gefertigt und auf der Baustelle mit dem Kran montiert. Das verlangt Planung von Transport, Hebepunkten und Anschlüssen.</p>", "loesung": "<ul><li><b>Transportmaße:</b> genehmigungsfrei Breite 2,55 m, Höhe 4,00 m – sonst Sondertransport.</li><li><b>Hebepunkte/Lastaufnahme</b> einplanen (Anschlagmittel, Schwerpunkt).</li><li><b>Montagereihenfolge</b> und Stoßausbildung der Elemente (luftdicht, statisch).</li><li><b>Installationsebene/Leitungsführung</b> bereits im Werk berücksichtigen.</li><li>Witterungsschutz und Maßhaltigkeit der Vorgewerke (Bodenplatte!) prüfen.</li></ul>"}, {"id": "hf1h", "group": "hf1", "deck": "HF1H", "n": 8, "typ": "v", "kennung": "HF1h-1", "tax": "Werten", "frage": "Was ist bei einem <b>Wärmedämmverbundsystem (WDVS)</b> in der Altbausanierung – besonders zum Brandschutz – zu beachten?", "erklaerung": "<p>Das WDVS wird außen auf die Bestandswand geklebt/gedübelt. Bei brennbaren Dämmstoffen (EPS) und mehrgeschossigen Gebäuden sind Brandschutzmaßnahmen nötig.</p>", "loesung": "<ul><li><b>Befestigung:</b> Kleben + Dübeln auf tragfähigem, ebenem Untergrund (Toleranzen prüfen).</li><li><b>Brandschutzriegel</b> (nicht brennbare Mineralwolle-Streifen) bei EPS-Systemen oberhalb von Öffnungen/geschossweise – verhindert Brandausbreitung in der Dämmebene.</li><li>Anschlüsse an Fenster/Sockel/Dach dauerhaft dicht; Sockel: Spritzwasser-/Feuchteschutz.</li></ul>"}, {"id": "hf2a", "group": "hf2", "deck": "HF2A", "n": 1, "typ": "v", "kennung": "HF2a-1", "tax": "Wissen", "frage": "Nennen Sie die wichtigsten <b>Bauholzarten</b> mit Rohdichte und Dauerhaftigkeitsklasse. Unterscheiden Sie Nadel- und Laubhölzer.", "erklaerung": "<p>Holzart, Rohdichte und natürliche Dauerhaftigkeit bestimmen Tragfähigkeit und Einsatzbereich. Die Dauerhaftigkeitsklasse (1 = sehr dauerhaft … 5 = nicht dauerhaft) ist für den Holzschutz wichtig.</p>", "loesung": "<table><tr><th>Holzart</th><th>Rohdichte</th><th>Dauerhaftigkeit</th></tr><tr><td>Fichte (Nadel)</td><td>~460 kg/m³</td><td>Klasse 4</td></tr><tr><td>Kiefer (Nadel)</td><td>~520 kg/m³</td><td>3–4</td></tr><tr><td>Lärche (Nadel)</td><td>~590 kg/m³</td><td>3–4</td></tr><tr><td>Eiche (Laub)</td><td>~675 kg/m³</td><td>Klasse 2 (dauerhaft!)</td></tr><tr><td>Buche (Laub)</td><td>~700 kg/m³</td><td>Klasse 5 (sehr gering!)</td></tr></table><p>Merke: Buche ist schwer und fest, aber <b>kaum dauerhaft</b> → nur im trockenen Innenbereich; Eiche/Lärche für bewitterte Bauteile.</p>"}, {"id": "hf2a", "group": "hf2", "deck": "HF2A", "n": 2, "typ": "v", "kennung": "HF2a-1", "tax": "Werten", "frage": "Was bedeutet die <b>Anisotropie</b> des Holzes, und welche drei Richtungen unterscheidet man?", "erklaerung": "<p>Holz ist ein gewachsener Faserwerkstoff. Seine Eigenschaften (Festigkeit, Schwinden, Wärme-/Feuchteverhalten) sind <b>richtungsabhängig</b> – das nennt man Anisotropie.</p>", "loesung": "<ul><li><b>axial (längs zur Faser):</b> höchste Festigkeit (Zug/Druck), geringstes Schwinden (~0,01 %).</li><li><b>radial (zum Mark):</b> mittleres Schwinden (~0,17 %).</li><li><b>tangential (Jahrringrichtung):</b> größtes Schwinden (~0,30 %) → Ursache für Risse und Verzug.</li></ul><p>Folge: Holz reißt und verzieht sich beim Trocknen unterschiedlich – Quer­zug ist die schwächste Beanspruchung.</p>"}, {"id": "hf2a", "group": "hf2", "deck": "HF2A", "n": 3, "typ": "p", "kennung": "HF2a-1", "tax": "Erkennen", "frage": "Erklären Sie die <b>Festigkeitsklassen C16, C24, C30</b> und ihre Zuordnung zu den visuellen Sortierklassen. Was sagt die Zahl aus?", "erklaerung": "<p>Bauholz wird nach Festigkeit klassifiziert (DIN EN 338) bzw. visuell sortiert (DIN 4074). Die Zahl in der C-Klasse ist die charakteristische Biegefestigkeit in N/mm².</p>", "loesung": "<table><tr><th>Festigkeitsklasse</th><th>visuelle Klasse</th><th>Biegefestigkeit</th></tr><tr><td>C16</td><td>S7</td><td>16 N/mm²</td></tr><tr><td><b>C24</b></td><td><b>S10</b></td><td>24 N/mm² (Standard!)</td></tr><tr><td>C30</td><td>S13</td><td>30 N/mm²</td></tr></table><p><b>C</b> = Coniferous (Nadelholz), <b>D</b> = Deciduous (Laubholz, z. B. D30/D40). <b>C24</b> ist das Standard-Bauholz im Hausbau.</p>"}, {"id": "hf2a", "group": "hf2", "deck": "HF2A", "n": 4, "typ": "v", "kennung": "HF2a-1", "tax": "Wissen", "frage": "Unterscheiden Sie <b>Kernholz, Splintholz und Reifholz</b>.", "erklaerung": "<p>Der Stammquerschnitt ist nicht homogen. Die Zonen unterscheiden sich in Funktion, Farbe und Dauerhaftigkeit – relevant für Holzauswahl und Holzschutz.</p>", "loesung": "<ul><li><b>Splintholz:</b> äußere, lebende Zone – leitet Wasser, heller, feuchter, <b>weniger dauerhaft</b>, anfälliger für Insekten/Pilze.</li><li><b>Kernholz:</b> innere, abgestorbene Zone – eingelagerte Stoffe, dunkler, trockener, <b>dauerhafter</b> (z. B. Eiche, Lärche).</li><li><b>Reifholz:</b> kernholzartig trockene Innenzone <b>ohne Farbunterschied</b> (z. B. Fichte, Tanne).</li></ul>"}, {"id": "hf2a", "group": "hf2", "deck": "HF2A", "n": 5, "typ": "v", "kennung": "HF2a-1", "tax": "Werten", "frage": "Vergleichen Sie die wichtigsten <b>Holzwerkstoffe</b> (KVH, BSH, BSP/CLT, OSB, MDF, Sperrholz) nach Aufbau und Einsatz.", "erklaerung": "<p>Holzwerkstoffe entstehen durch Verkleben von Brettern, Furnieren oder Spänen. Je nach Aufbau ergeben sich Maßhaltigkeit, Tragfähigkeit und Einsatzbereich.</p>", "loesung": "<table><tr><th>Werkstoff</th><th>Aufbau / Einsatz</th></tr><tr><td><b>KVH</b></td><td>keilgezinktes, getrocknetes Vollholz (u ≤ 18 %); Sparren, Ständer</td></tr><tr><td><b>BSH</b></td><td>≥ 3 faserparallele Lamellen (GL24); große Spannweiten, Binder</td></tr><tr><td><b>BSP/CLT</b></td><td>kreuzweise verleimt → sperrt Schwinden; Wand-/Deckenelemente</td></tr><tr><td><b>OSB</b></td><td>ausgerichtete Späne; OSB/3-4 tragend & luftdicht (Aussteifung)</td></tr><tr><td><b>MDF</b></td><td>feine Fasern; Innenausbau, nicht tragend</td></tr><tr><td><b>Sperrholz</b></td><td>kreuzweise Furniere; sehr formstabil</td></tr></table>"}, {"id": "hf2a", "group": "hf2", "deck": "HF2A", "n": 6, "typ": "p", "kennung": "HF2a-1", "tax": "Können", "frage": "Eine Holzprobe wiegt feucht 540 g, nach dem Darren (vollständig trocken) 450 g. <b>Berechnen Sie die Holzfeuchte u.</b> Darf das Holz nach ATV DIN 18334 eingebaut werden?", "erklaerung": "<p>Die Holzfeuchte ist der Massenanteil Wasser, bezogen auf die <b>Darrmasse</b> (Trockenmasse). Das gravimetrische Darrverfahren ist die genaueste Methode.</p><div class=\"formula\">u = (m<sub>feucht</sub> − m<sub>darr</sub>) / m<sub>darr</sub> · 100 %</div>", "loesung": "<div class=\"formula\">u = (540 − 450) / 450 · 100 = 90 / 450 · 100 = <b>20 %</b></div><p><b>Bewertung:</b> ATV DIN 18334 erlaubt für Bauholz max. <b>18 %</b> Einbaufeuchte. 20 % &gt; 18 % → das Holz ist <b>zu feucht</b> und darf so <b>nicht eingebaut</b> werden (erst weiter trocknen).</p>"}, {"id": "hf2a", "group": "hf2", "deck": "HF2A", "n": 7, "typ": "v", "kennung": "HF2a-1", "tax": "Wissen", "frage": "Erklären Sie <b>Fasersättigungsbereich</b> und <b>Schwinden/Quellen</b>. Geben Sie die Schwindmaße an.", "erklaerung": "<p>Holz nimmt Feuchte auf und gibt sie ab, bis es mit der Umgebung im Gleichgewicht ist. Bis zum Fasersättigungsbereich sitzt Wasser nur in den Zellwänden – darunter beginnt das Arbeiten des Holzes.</p>", "loesung": "<ul><li><b>Fasersättigung:</b> ca. <b>30 %</b> Holzfeuchte. <b>Darüber</b> (freies Wasser) kein Schwinden; <b>darunter</b> schwindet/quillt das Holz.</li><li><b>Schwindmaße pro 1 % Feuchteänderung:</b> axial ~0,01 %, radial ~0,17 %, <b>tangential ~0,30 %</b>.</li><li><b>Gleichgewichtsfeuchte Wohnraum:</b> 7–15 %.</li><li>Rechenwert EC5 (Querschnittsänderung): ~0,25 % je % tangential.</li></ul>"}, {"id": "hf2a", "group": "hf2", "deck": "HF2A", "n": 8, "typ": "v", "kennung": "HF2a-4", "tax": "Wissen", "frage": "Was beschreibt der <b>λ-Wert</b> bei Dämmstoffen, und was bedeuten die <b>WLG-Klassen</b>? Nennen Sie Beispiele.", "erklaerung": "<p>Die Wärmeleitfähigkeit λ (in W/(m·K)) ist die zentrale Kenngröße eines Dämmstoffs: Je kleiner λ, desto besser die Dämmwirkung. Die WLG-Klasse benennt λ·1000.</p>", "loesung": "<ul><li><b>λ-Wert</b>: kleiner = besser dämmend. WLG 035 ↔ λ = 0,035 W/(m·K).</li><li><b>Beispiele:</b> Mineralwolle WLG 035; EPS WLG 032–040; XPS WLG 030–035; Holzweichfaser WLG 040–045; Zellulose ~040.</li><li>Faustregel Dämmstoffwahl: Wärmeschutz (λ), Brandschutz, Feuchteverhalten, Ökobilanz abwägen.</li></ul>"}, {"id": "hf2a", "group": "hf2", "deck": "HF2A", "n": 9, "typ": "v", "kennung": "HF2a-1", "tax": "Wissen", "frage": "Was bedeutet die Kennzeichnung <b>„S 10 TS\"</b> auf einem Balken?", "erklaerung": "<p>Bauschnittholz wird nach DIN 4074 sortiert und gekennzeichnet. Die Kennzeichnung gibt Sortierklasse und Sortierfeuchte an.</p>", "loesung": "<ul><li><b>S 10</b> = visuelle Sortierklasse S10 (entspricht Festigkeitsklasse C24).</li><li><b>TS</b> = <b>trocken sortiert</b> (Holzfeuchte u ≤ 20 % bei der Sortierung).</li></ul><p>Gegenstück: „S 10 MS\" = nass sortiert (u &gt; 20 %). Zusätzlich gehören CE-/Ü-Zeichen und Hersteller zur Kennzeichnung.</p>"}, {"id": "hf2b", "group": "hf2", "deck": "HF2B", "n": 1, "typ": "v", "kennung": "HF2b-1", "tax": "Wissen", "frage": "Nennen Sie die <b>6 R der Logistik</b>.", "erklaerung": "<p>Die 6 R fassen das Ziel der Materialwirtschaft zusammen: das Material in jeder Hinsicht passend bereitzustellen.</p>", "loesung": "<p>Das <b>richtige</b> …</p><ol><li>Material</li><li>in der richtigen <b>Menge</b></li><li>in der richtigen <b>Qualität</b></li><li>zur richtigen <b>Zeit</b></li><li>am richtigen <b>Ort</b></li><li>zum richtigen <b>Preis</b></li></ol><p>Merkhilfe für jede Frage zur Materialdisposition/Arbeitsvorbereitung.</p>"}, {"id": "hf2b", "group": "hf2", "deck": "HF2B", "n": 2, "typ": "v", "kennung": "HF2b-1", "tax": "Können", "frage": "Was muss bei der <b>Wareneingangskontrolle</b> von Bauholz geprüft werden, und warum sofort?", "erklaerung": "<p>Mängel müssen unverzüglich erkannt und gerügt werden – sonst gehen Reklamationsansprüche verloren. Die Kontrolle gleicht Lieferung mit Bestellung ab.</p>", "loesung": "<ul><li><b>Vollständigkeit/Menge:</b> Lieferschein ↔ Bestellung.</li><li><b>Maßhaltigkeit:</b> Länge, Breite, Stärke.</li><li><b>Güte/Sichtprüfung:</b> Risse, Verzug, Äste, Schädlingsbefall (DIN 4074).</li><li><b>Holzfeuchte</b> stichprobenartig (Ziel 15–18 %).</li><li><b>Kennzeichnung:</b> CE-/Ü-Zeichen vorhanden?</li></ul><p><b>Warum sofort:</b> Verzögerte Rüge mindert/verwirkt Reklamationsansprüche; bei unterlassener Kontrolle haftet der Unternehmer.</p>"}, {"id": "hf2b", "group": "hf2", "deck": "HF2B", "n": 3, "typ": "p", "kennung": "HF2b-1", "tax": "Werten", "frage": "Bei der Anlieferung wird an einem Balken eine Holzfeuchte von 22 % gemessen. <b>Bewerten Sie:</b> Annehmen, einbauen, reklamieren?", "erklaerung": "<p>Zielwert bei Wareneingang ist 15–18 %, die maximale Einbaufeuchte nach ATV DIN 18334 liegt bei 18 %. Über diesem Wert ist das Holz für den sofortigen Einbau ungeeignet.</p>", "loesung": "<ul><li>22 % &gt; 18 % (max. Einbaufeuchte) und über dem Zielbereich 15–18 %.</li><li><b>Folge:</b> Mangel dokumentieren und <b>rügen</b> (Lieferschein-Vorbehalt, schriftlich). Holz nicht einbauen.</li><li>Option: nachtrocknen lassen oder Austausch fordern (Nacherfüllung).</li><li>Risiko bei Einbau: Schwinden, Risse, Fugen, Pilzgefahr.</li></ul>"}, {"id": "hf2b", "group": "hf2", "deck": "HF2B", "n": 4, "typ": "v", "kennung": "HF2b-2", "tax": "Können", "frage": "Welche Regeln gelten für die <b>fachgerechte Holzlagerung</b>?", "erklaerung": "<p>Falsch gelagertes Holz verzieht sich, wird feucht oder schimmelt. Wichtig sind Unterlüftung, Schutz vor Bodenfeuchte/UV und sichere Stapel.</p>", "loesung": "<ul><li><b>Unterlegung:</b> Kanthölzer (z. B. 12×12), Abstand ~1 m; Stapelhölzer mind. 80×80 mm, lotrecht übereinander.</li><li><b>Belüftung:</b> Stapel mit Zwischenleisten, keine Bodenfeuchte (Abstand zum Boden).</li><li><b>Stapelhöhe:</b> Halle max. 4× Stapelbreite (Schnittholz) / 6× (Platten); im Freien max. 3×.</li><li><b>Schutz:</b> Abdeckung gegen Regen/UV, Hirnholz schützen, Dämmstoffe trocken lagern. Schiefstellung max. ~2°.</li></ul>"}, {"id": "hf2b", "group": "hf2", "deck": "HF2B", "n": 5, "typ": "v", "kennung": "HF2b-3", "tax": "Wissen", "frage": "Erklären Sie die <b>Altholzklassen A I bis A IV</b>. Welche ist gefährlicher Abfall?", "erklaerung": "<p>Die Altholzverordnung teilt Holzabfälle nach Behandlung ein. Das steuert Entsorgungsweg und Kosten.</p>", "loesung": "<table><tr><th>Klasse</th><th>Beschreibung</th></tr><tr><td><b>A I</b></td><td>naturbelassen / nur mechanisch bearbeitet (Paletten, unbeh. Holz)</td></tr><tr><td><b>A II</b></td><td>verleimt, gestrichen, beschichtet – ohne Holzschutz & Halogene</td></tr><tr><td><b>A III</b></td><td>mit halogenorganischen Verbindungen (z. B. PVC-Beschichtung)</td></tr><tr><td><b>A IV</b></td><td>mit Holzschutzmitteln behandelt → <b>gefährlicher Abfall (Sondermüll)!</b></td></tr></table><p>Beispiel A IV: Bahnschwellen, imprägnierte Außenkonstruktionen.</p>"}, {"id": "hf2b", "group": "hf2", "deck": "HF2B", "n": 6, "typ": "v", "kennung": "HF2b-3", "tax": "Wissen", "frage": "Beschreiben Sie die <b>Abfallhierarchie</b> und die Trennpflicht auf Baustellen.", "erklaerung": "<p>Das Kreislaufwirtschaftsgesetz / die GewAbfV geben eine Rangfolge vor, wie mit Abfall umzugehen ist – Vermeiden steht über Beseitigen.</p>", "loesung": "<p><b>Abfallhierarchie (5 Stufen):</b></p><ol><li>Vermeiden</li><li>Wiederverwenden (Vorbereitung)</li><li>Recycling</li><li>sonstige Verwertung (z. B. energetisch)</li><li>Beseitigen (Deponie)</li></ol><ul><li>Auf Baustellen Abfälle <b>getrennt</b> sammeln (GewAbfV, mehrere Fraktionen: Holz, Metall, Folie, Bauschutt …).</li><li>Dokumentation/Nachweise aufbewahren (Entsorgungsnachweise).</li></ul>"}, {"id": "hf2b", "group": "hf2", "deck": "HF2B", "n": 7, "typ": "v", "kennung": "HF2b-3", "tax": "Wissen", "frage": "Welche Sicherheits- und Prüfpflichten gelten beim <b>innerbetrieblichen Transport</b> (Gabelstapler, Kran)?", "erklaerung": "<p>Hebezeuge und Flurförderzeuge sind unfallträchtig. Es gelten DGUV-Regeln, Prüfpflichten und Qualifikationsanforderungen.</p>", "loesung": "<ul><li><b>Gabelstapler:</b> nur unterwiesene Fahrer mit Befähigung; Sicherheitsabstand ~0,5 m; <b>jährliche Prüfpflicht</b> (Sachkundiger).</li><li><b>Kran/Anschlagmittel:</b> jährliche Prüfung; Anschlagmittel (Gurte, Ketten) vor Gebrauch sichtprüfen, Tragfähigkeit beachten.</li><li>Ladungssicherung beim außerbetrieblichen Transport (Zurrgurte, Formschluss).</li><li>Grundlage: <b>DGUV Regel 100-001</b>, BetrSichV, BG-BAU-Schriften (S215 Stapler).</li></ul>"}, {"id": "hf2b", "group": "hf2", "deck": "HF2B", "n": 8, "typ": "v", "kennung": "HF2b-1", "tax": "Wissen", "frage": "Welche <b>Mängelrechte</b> hat der Besteller bei mangelhafter Lieferung, und in welcher Reihenfolge?", "erklaerung": "<p>Das BGB (Kaufrecht §§ 433 ff.) regelt die Rechte bei Sachmängeln. Vorrang hat die Nacherfüllung, bevor weitergehende Rechte greifen.</p>", "loesung": "<ol><li><b>Nacherfüllung</b> (Nachbesserung oder Ersatzlieferung) – zuerst!</li><li>bei Scheitern/Fristablauf: <b>Minderung</b> oder <b>Rücktritt</b></li><li>ggf. <b>Schadensersatz</b></li></ol><p>Voraussetzung: rechtzeitige <b>Mängelrüge</b>. Der Unternehmer haftet, wenn er die Wareneingangskontrolle unterlässt.</p>"}, {"id": "hf2b", "group": "hf2", "deck": "HF2B", "n": 9, "typ": "v", "kennung": "HF2b-1", "tax": "Wissen", "frage": "Was sagen <b>CE- und Ü-Zeichen</b> auf Bauprodukten aus?", "erklaerung": "<p>Kennzeichen belegen die Konformität eines Bauprodukts mit europäischen bzw. nationalen Anforderungen – Voraussetzung für die Verwendbarkeit.</p>", "loesung": "<ul><li><b>CE-Zeichen:</b> Produkt entspricht einer harmonisierten europäischen Norm/ETA – Leistungserklärung (DoP) vorhanden, frei handelbar im EWR.</li><li><b>Ü-Zeichen:</b> nationales Übereinstimmungszeichen (für national geregelte Produkte ohne CE).</li></ul><p>Bei Wareneingang prüfen: korrekte Kennzeichnung = Voraussetzung für den Einbau und Teil der Dokumentation.</p>"}, {"id": "hf2c", "group": "hf2", "deck": "HF2C", "n": 1, "typ": "v", "kennung": "HF2c-1", "tax": "Wissen", "frage": "Welche <b>Lagerarten</b> gibt es im Zimmereibetrieb und wofür eignen sie sich?", "erklaerung": "<p>Je nach Material (Schnittholz, Platten, Dämmstoff) und Witterungsempfindlichkeit braucht es unterschiedliche Lagerformen.</p>", "loesung": "<ul><li><b>Freifläche (befestigt, evtl. überdacht):</b> witterungsunempfindliches Gut, Stapel auf Unterleghölzern.</li><li><b>Regallager:</b> Plattenmaterial (stehend/liegend), Längsgut, Kleinteile – übersichtlich, kommissionierbar.</li><li><b>Überdachte Halle:</b> empfindliches Holz/KVH/BSH, Dämmstoffe, fertige Bauteile (trocken, UV-geschützt).</li></ul>"}, {"id": "hf2c", "group": "hf2", "deck": "HF2C", "n": 2, "typ": "v", "kennung": "HF2c-1", "tax": "Wissen", "frage": "Welche <b>Sicherheitszonen und Verkehrswege</b> sind im Lager zu beachten?", "erklaerung": "<p>Wo Stapler und Personen zusammentreffen, muss genug Platz für sicheres Manövrieren bleiben. Verkehrswege werden nach Fahrzeugbreite bemessen.</p>", "loesung": "<ul><li><b>Fahrgassenbreite</b> für Stapler: Fahrzeug-/Lastbreite + beidseits <b>0,5 m</b> Sicherheitsabstand.</li><li>Getrennte oder markierte <b>Fußgängerwege</b>.</li><li>Freihalten von Flucht- und Rettungswegen, Übersichtlichkeit an Kreuzungen.</li><li>Standsichere Stapel, keine Überschreitung der zulässigen Stapelhöhe.</li></ul>"}, {"id": "hf2c", "group": "hf2", "deck": "HF2C", "n": 3, "typ": "v", "kennung": "HF2c-1", "tax": "Wissen", "frage": "Erklären Sie die Begriffe <b>Inventur, Mindestbestand und Nachbestellpunkt</b>.", "erklaerung": "<p>Die Bestandsführung sichert, dass Material verfügbar ist, ohne unnötig Kapital im Lager zu binden.</p>", "loesung": "<ul><li><b>Inventur:</b> mengen-/wertmäßige Bestandsaufnahme (mind. jährlich).</li><li><b>Mindestbestand (eiserner Bestand):</b> Sicherheitsreserve gegen Lieferverzug/Schwankungen.</li><li><b>Nachbestellpunkt (Meldebestand):</b> Bestand, bei dem nachbestellt wird, damit die Lieferzeit überbrückt wird, bevor der Mindestbestand erreicht ist.</li></ul><div class=\"formula\">Meldebestand = Tagesverbrauch · Lieferzeit + Mindestbestand</div>"}, {"id": "hf2c", "group": "hf2", "deck": "HF2C", "n": 4, "typ": "v", "kennung": "HF2c-2", "tax": "Wissen", "frage": "Beschreiben Sie die <b>Logistikkette</b> eines Bauauftrags von der Arbeitsvorbereitung bis zur Entsorgung.", "erklaerung": "<p>Material durchläuft mehrere Stationen. Eine durchdachte Kette vermeidet Stillstände, Doppeltransporte und Lagerschäden.</p>", "loesung": "<ol><li><b>Materialdisposition / Arbeitsvorbereitung:</b> Stücklisten, Mengen, Termine.</li><li><b>Bestellung & Anlieferung:</b> Lieferschein, Wareneingangskontrolle.</li><li><b>Lagerung (Baustelle/Hof):</b> Unterlegung, Witterungsschutz.</li><li><b>Verarbeitung:</b> Just-in-time oder mit Puffer.</li><li><b>Entsorgung</b> von Resten/Verpackung (getrennt).</li></ol>"}, {"id": "hf2c", "group": "hf2", "deck": "HF2C", "n": 5, "typ": "v", "kennung": "HF2c-2", "tax": "Wissen", "frage": "Welche Elemente gehören in einen <b>Baustelleneinrichtungsplan (BE-Plan)</b>?", "erklaerung": "<p>Der BE-Plan organisiert die Baustelle räumlich, damit Abläufe, Sicherheit und Logistik funktionieren. Ein typischer Skizzier-Auftrag in der Prüfung.</p>", "loesung": "<ul><li><b>Kran</b> (Standort, Ausladung/Schwenkbereich)</li><li><b>Lagerflächen</b> (Material, Vorfertigung)</li><li><b>Zufahrt/Verkehrswege</b>, Wendeflächen</li><li><b>Baustrom</b>verteiler, <b>Wasser</b>anschluss</li><li><b>Sanitär/Container</b> (Aufenthalt, Büro)</li><li><b>Absperrung/Sicherung</b>, Schutzgerüst, Müllplatz</li></ul>"}, {"id": "hf2c", "group": "hf2", "deck": "HF2C", "n": 6, "typ": "v", "kennung": "HF2c-1", "tax": "Wissen", "frage": "Wie ist eine <b>Holzliste (Stückliste)</b> aufgebaut?", "erklaerung": "<p>Die Holzliste leitet aus der Konstruktionszeichnung alle Bauteile mit Mengen ab – Grundlage für Bestellung und Kalkulation.</p>", "loesung": "<p>Typische Spalten:</p><table><tr><th>Pos.</th><th>Stk.</th><th>Querschnitt b×h</th><th>Länge</th><th>Volumen</th><th>Material/Güte</th><th>Bemerkung</th></tr><tr><td>1</td><td>12</td><td>8/20 cm</td><td>4,50 m</td><td>0,864 m³</td><td>C24 KVH</td><td>Sparren</td></tr></table><p>Am Ende: Netto-Volumen + Verschnitt = <b>Bestellmenge</b>.</p>"}, {"id": "hf2c", "group": "hf2", "deck": "HF2C", "n": 7, "typ": "v", "kennung": "HF2c-1", "tax": "Wissen", "frage": "Was umfasst die <b>Arbeitsvorbereitung (AV)</b> im Holzbau?", "erklaerung": "<p>Die AV plant alle Schritte vor der Ausführung, damit Material, Maschinen und Personal termingerecht zusammenkommen.</p>", "loesung": "<ul><li><b>Abbundplan</b> und Werkpläne (Maße, Verbindungen)</li><li><b>Stücklisten</b> / Materialdisposition</li><li><b>Montageanweisung</b> und Reihenfolge</li><li><b>Terminplanung</b> (Balken-/Gantt-Diagramm)</li><li>Maschinen-/Personaleinsatz, Geräte</li></ul>"}, {"id": "hf2c", "group": "hf2", "deck": "HF2C", "n": 8, "typ": "p", "kennung": "HF2c-1", "tax": "Können", "frage": "Ein Material hat einen Tagesverbrauch von 5 Stück, die Lieferzeit beträgt 6 Tage, der Mindestbestand 10 Stück. <b>Berechnen Sie den Meldebestand (Nachbestellpunkt).</b>", "erklaerung": "<p>Der Meldebestand muss den Verbrauch während der Lieferzeit plus die Sicherheitsreserve abdecken, damit das Lager nicht leerläuft.</p><div class=\"formula\">Meldebestand = Tagesverbrauch · Lieferzeit + Mindestbestand</div>", "loesung": "<div class=\"formula\">Meldebestand = 5 · 6 + 10 = 30 + 10 = <b>40 Stück</b></div><p>Sinkt der Bestand auf 40 Stück, wird nachbestellt. Während der 6 Tage Lieferzeit werden 30 Stück verbraucht – es bleiben genau die 10 Stück Mindestbestand als Reserve.</p>"}, {"id": "hf2d", "group": "hf2", "deck": "HF2D", "n": 1, "typ": "v", "kennung": "HF2d-1", "tax": "Werten", "frage": "Erklären Sie die <b>Hierarchie der Holzschutzmaßnahmen</b> nach DIN 68800.", "erklaerung": "<p>Holzschutz folgt einer klaren Rangfolge: Erst wird das Holz konstruktiv trocken gehalten, chemischer Schutz ist nur die letzte Option.</p>", "loesung": "<ol><li><b>Baulicher (konstruktiver) Holzschutz</b> – Vorrang! Holz trocken halten (Überstand, Belüftung, Abstand).</li><li><b>Physikalischer Holzschutz</b> – technische Trocknung (verhindert Pilz-/Insektenbefall durch niedrige Feuchte).</li><li><b>Chemischer Holzschutz</b> – nur als „ultima ratio\", wenn die konstruktiven Maßnahmen nicht ausreichen.</li></ol><p>Begründung: Umwelt, Gesundheit, Entsorgungskosten (behandeltes Holz = Sondermüll).</p>"}, {"id": "hf2d", "group": "hf2", "deck": "HF2D", "n": 2, "typ": "v", "kennung": "HF2d-1", "tax": "Wissen", "frage": "Vergleichen Sie <b>natürliche und technische Holztrocknung</b> (Zeiten, Zielfeuchten).", "erklaerung": "<p>Holz muss vor dem Einbau auf die Gebrauchsfeuchte getrocknet werden. Das geht langsam an der Luft oder schnell und kontrolliert in der Kammer.</p>", "loesung": "<table><tr><th></th><th>Natürlich (Luft)</th><th>Technisch (Kammer)</th></tr><tr><td>Dauer</td><td>~1 Jahr je 2 cm Dicke</td><td>Tage, kontrolliert</td></tr><tr><td>Zielfeuchte</td><td>~18–20 %</td><td>≤ 15–18 % (bis 12 %)</td></tr><tr><td>Vorteil</td><td>kostengünstig, schonend</td><td>schnell, gezielt, abtötend</td></tr></table><p>Lieferfeuchte: <b>KVH u ≤ 18 %</b>, <b>BSH u ≤ 15 %</b> (tragende Teile bis 12 %).</p>"}, {"id": "hf2d", "group": "hf2", "deck": "HF2D", "n": 3, "typ": "p", "kennung": "HF2d-1", "tax": "Können", "frage": "Eine Probe wiegt feucht 308 g, darrtrocken 280 g. <b>Berechnen Sie die Holzfeuchte</b> und ordnen Sie sie ein.", "erklaerung": "<p>Das Darrverfahren liefert die exakte Holzfeuchte über die Differenz zur Trockenmasse.</p><div class=\"formula\">u = (m<sub>feucht</sub> − m<sub>darr</sub>) / m<sub>darr</sub> · 100 %</div>", "loesung": "<div class=\"formula\">u = (308 − 280) / 280 · 100 = 28 / 280 · 100 = <b>10 %</b></div><p>10 % liegt im Bereich der <b>Gleichgewichtsfeuchte beheizter Innenräume (7–15 %)</b> → ideal z. B. für Innenausbau/Treppen. Deutlich unter der max. Einbaufeuchte 18 %.</p>"}, {"id": "hf2d", "group": "hf2", "deck": "HF2D", "n": 4, "typ": "v", "kennung": "HF2d-1", "tax": "Erkennen", "frage": "Vergleichen Sie die <b>elektrische und die gravimetrische Holzfeuchtemessung</b>.", "erklaerung": "<p>Für die Praxis ist Schnelligkeit wichtig, für Streitfälle Genauigkeit. Beide Verfahren haben unterschiedliche Stärken.</p>", "loesung": "<ul><li><b>Elektrisch (Widerstandsmessung):</b> schnell, zerstörungsfrei, Stichprobe; misst v. a. den Oberflächenbereich; Genauigkeit ±2 %. Für Baustelle ideal.</li><li><b>Gravimetrisch (Darrverfahren):</b> exakt, aber zerstörend und zeitaufwändig (wiegen → darren → wiegen). Referenzverfahren.</li></ul>"}, {"id": "hf2d", "group": "hf2", "deck": "HF2D", "n": 5, "typ": "v", "kennung": "HF2d-1", "tax": "Wissen", "frage": "Welche <b>Lieferfeuchten</b> haben KVH und BSH, und warum ist die technische Trocknung hier wichtig?", "erklaerung": "<p>Industrieprodukte werden technisch getrocknet, damit sie maßhaltig sind und nicht im Bauteil nacharbeiten.</p>", "loesung": "<ul><li><b>KVH:</b> u ≤ <b>18 %</b> (technisch getrocknet, keilgezinkt).</li><li><b>BSH:</b> u ≤ <b>15 %</b> (Verleimung erfordert trockenes Holz; tragende Teile bis 12 %).</li></ul><p>Niedrige, definierte Feuchte → kein nachträgliches Schwinden/Reißen, Verleimung hält, Befall durch Pilze/Insekten ausgeschlossen (unter ~20 %).</p>"}, {"id": "hf2d", "group": "hf2", "deck": "HF2D", "n": 6, "typ": "v", "kennung": "HF2d-3", "tax": "Werten", "frage": "Was ist bei <b>chemischen Holzschutzmitteln</b> hinsichtlich Wirkstoffen, Zulassung und Anwendungsverboten zu beachten?", "erklaerung": "<p>Chemische Mittel sind streng geregelt, weil sie Mensch und Umwelt belasten können. Einsatz nur wo nötig und nur zugelassene Mittel.</p>", "loesung": "<ul><li><b>Wirkstoffklassen:</b> Fungizide (gegen Pilze), Insektizide (gegen Insekten); moderne Mittel CKW-/halogenfrei.</li><li><b>Zulassung</b> erforderlich (Prüfzeichen); nur nach Gebrauchsklasse einsetzen.</li><li><b>Verbote:</b> großflächige Anwendung in Aufenthaltsräumen unzulässig; Arbeitsschutz (PSA) beim Auftrag.</li><li>Anwendungsmaß beachten (Streich-/Spritzmenge je m²/m³).</li></ul>"}, {"id": "hf2d", "group": "hf2", "deck": "HF2D", "n": 7, "typ": "v", "kennung": "HF2d-4", "tax": "Werten", "frage": "Warum ist <b>chemisch behandeltes Holz ein Entsorgungsproblem</b>?", "erklaerung": "<p>Die Behandlung, die das Holz schützt, macht es am Lebensende zu belastetem Abfall.</p>", "loesung": "<p>Mit Holzschutzmitteln behandeltes Holz ist <b>Altholzklasse A IV</b> = <b>gefährlicher / überwachungsbedürftiger Abfall (Sondermüll)</b>. Folgen:</p><ul><li>teure Sonderentsorgung (kein normaler Altholz-Recyclingweg)</li><li>Dokumentations-/Nachweispflichten</li><li>Umweltbelastung</li></ul><p>→ starkes Argument für den Vorrang des konstruktiven Holzschutzes.</p>"}, {"id": "hf2d", "group": "hf2", "deck": "HF2D", "n": 8, "typ": "v", "kennung": "HF2d-1", "tax": "Wissen", "frage": "Welche Teile umfasst die <b>DIN 68800</b> (Holzschutz)?", "erklaerung": "<p>Die DIN 68800 ist das zentrale Holzschutz-Regelwerk und in vier Teile gegliedert – von Grundlagen bis Bekämpfung.</p>", "loesung": "<ul><li><b>Teil 1:</b> Allgemeines / Grundlagen.</li><li><b>Teil 2:</b> Vorbeugende <b>bauliche</b> Maßnahmen (konstruktiver Holzschutz).</li><li><b>Teil 3:</b> Vorbeugender <b>chemischer</b> Holzschutz.</li><li><b>Teil 4:</b> <b>Bekämpfungs</b>maßnahmen gegen Pilze und tierische Schädlinge.</li></ul>"}, {"id": "hf2e", "group": "hf2", "deck": "HF2E", "n": 1, "typ": "v", "kennung": "HF2e-1", "tax": "Werten", "frage": "Was ist das Ziel des <b>konstruktiven Holzschutzes</b>, und welche Holzfeuchte soll erreicht werden?", "erklaerung": "<p>Konstruktiver Holzschutz plant die Einbausituation so, dass Holz dauerhaft trocken bleibt – dann sind Pilze und Insekten ausgeschlossen, ohne Chemie.</p>", "loesung": "<p><b>Ziel:</b> Holzfeuchte dauerhaft <b>≤ 20 %</b> halten → Einstufung in <b>GK 0</b>, kein chemischer Holzschutz nötig.</p><p>Erreicht durch: kein Erd-/Wasserkontakt, schnelle Abtrocknung (Belüftung), Schutz vor Bewitterung, Wasserableitung.</p>"}, {"id": "hf2e", "group": "hf2", "deck": "HF2E", "n": 2, "typ": "p", "kennung": "HF2e-1", "tax": "Erkennen", "frage": "Erklären Sie die <b>Gebrauchsklassen GK 0 bis GK 4</b> nach DIN 68800 mit je einem Beispiel. Welche GK hat ein Pfosten im Erdreich?", "erklaerung": "<p>Die Gebrauchsklasse beschreibt die Feuchtebelastung eines Bauteils und bestimmt die nötigen Schutzmaßnahmen / Holzauswahl.</p>", "loesung": "<table><tr><th>GK</th><th>Situation</th><th>Beispiel</th></tr><tr><td>0</td><td>dauerhaft trocken (u ≤ 20 %)</td><td>Dachstuhl im Haus</td></tr><tr><td>1</td><td>unter Dach, trocken, kein Erdkontakt</td><td>Innenpfosten</td></tr><tr><td>2</td><td>unter Dach, gelegentlich feucht</td><td>überdachter Außenpfosten</td></tr><tr><td>3</td><td>außen bewittert, kein Erdkontakt</td><td>Fassade, Terrasse</td></tr><tr><td>4</td><td>Erd- oder Süßwasserkontakt</td><td>Pfosten im Boden</td></tr></table><p><b>Pfosten im Erdreich → GK 4</b>: dauerhaftes Holz (Eiche, Lärche) oder druckimprägniert + konstruktive Trennung vom Boden.</p>"}, {"id": "hf2e", "group": "hf2", "deck": "HF2E", "n": 3, "typ": "v", "kennung": "HF2e-1", "tax": "Können", "frage": "Nennen Sie die wichtigsten <b>konstruktiven Maßnahmen</b> zum Schutz von Außenholz.", "erklaerung": "<p>Wasser ist der Feind des Holzes. Konstruktive Maßnahmen sorgen dafür, dass Wasser gar nicht erst stehen bleibt und das Holz schnell abtrocknet.</p>", "loesung": "<ul><li><b>Dachüberstand:</b> schützt Fassade und Anschlüsse vor Regen.</li><li><b>Hinterlüftung:</b> Luftspalt hinter Bekleidung → schnelles Abtrocknen.</li><li><b>Bodenabstand:</b> Holz mind. 30 cm über Gelände.</li><li><b>Hirnholzschutz:</b> Abdeckung/Metallkappe, Abschrägung 15–20° für Wasserablauf.</li><li><b>Entwässerung/Gefälle:</b> keine Wassersäcke; Tropfkanten.</li><li><b>Trennlagen</b> zwischen Holz und Beton/Mauerwerk.</li></ul>"}, {"id": "hf2e", "group": "hf2", "deck": "HF2E", "n": 4, "typ": "p", "kennung": "HF2e-2", "tax": "Können", "frage": "Eine hinterlüftete Holzfassade ist zu planen. <b>Nennen Sie die Kennwerte</b> für Mindestluftspalt und Hinterlüftungsquerschnitt sowie den Bodenabstand.", "erklaerung": "<p>Die Hinterlüftung funktioniert nur mit ausreichendem Spalt und offenen Zu-/Abluftquerschnitten. Diese Werte sind prüfungsrelevant.</p>", "loesung": "<ul><li><b>Mindestluftspalt:</b> ≥ <b>20 mm</b> (besser 30–40 mm).</li><li><b>Be-/Entlüftungsquerschnitt:</b> ≥ <b>50 cm² je m</b> Wandlänge für Zu- und Abluft (DIN 68800-2 / Zimmerer-Fachregel; Insektengitter vorsehen). <i>Achtung:</i> die oft genannten <b>200 cm²/m</b> sind der <b>Trauf-Wert beim Dach</b>, nicht für Fassaden!</li><li><b>Bodenabstand der Bekleidung:</b> ≥ <b>300 mm</b> über Gelände (Spritzwasser).</li><li>Unterkonstruktion mit Abstand, Konterlattung; kein Holz-zu-Boden-Kontakt.</li></ul>"}, {"id": "hf2e", "group": "hf2", "deck": "HF2E", "n": 5, "typ": "v", "kennung": "HF2e-1", "tax": "Werten", "frage": "Wie wird <b>Hirnholz</b> geschützt und warum ist es besonders gefährdet?", "erklaerung": "<p>Hirnholz (Stirnholz, Schnitt quer zur Faser) saugt Wasser kapillar wie ein Schwamm entlang der Fasern – die kritischste Stelle für Feuchteaufnahme.</p>", "loesung": "<ul><li><b>Gefahr:</b> kapillare Wasseraufnahme entlang der Faser → tiefes Eindringen, Fäulnis.</li><li><b>Schutz:</b> Abschrägung <b>15–20°</b> (Wasser läuft ab), Metall-/Blechabdeckung, Überstand, ggf. Hirnholzversiegelung als letztes Mittel.</li><li>Konstruktiv: Hirnholz nie nach oben offen oder in Spritzwasserzone.</li></ul>"}, {"id": "hf2e", "group": "hf2", "deck": "HF2E", "n": 6, "typ": "v", "kennung": "HF2e-1", "tax": "Können", "frage": "Welche besonderen Maßnahmen gelten bei <b>Balkonen und Terrassen</b>?", "erklaerung": "<p>Balkone/Terrassen sind stark bewittert (GK 3) und brauchen ein durchdachtes Entwässerungs- und Hinterlüftungskonzept (Zimmerer-Fachregel 02).</p>", "loesung": "<ul><li><b>Gefälle</b> und sichere <b>Entwässerung</b> (kein stehendes Wasser).</li><li><b>Abdichtung</b> der tragenden Konstruktion (z. B. Folie/Bahn) unter dem Belag.</li><li><b>Hinterlüftung</b> des Belags (Abstandshalter, Spalt zwischen Dielen).</li><li><b>Trennlagen</b> an Auflagern, kein direkter Erd-/Betonkontakt.</li><li>Dauerhafte Holzart/Imprägnierung passend zur GK.</li></ul>"}, {"id": "hf2e", "group": "hf2", "deck": "HF2E", "n": 7, "typ": "v", "kennung": "HF2e-1", "tax": "Werten", "frage": "Begründen Sie, warum <b>konstruktiver Holzschutz dem chemischen vorzuziehen</b> ist.", "erklaerung": "<p>Beide schützen das Holz, aber konstruktiver Schutz ist nachhaltiger und wirtschaftlicher über den Lebenszyklus.</p>", "loesung": "<ul><li><b>Umwelt/Gesundheit:</b> keine Biozide in Innenräumen/Umwelt.</li><li><b>Entsorgung:</b> unbehandeltes Holz = A I/A II (günstig), behandeltes = A IV (Sondermüll).</li><li><b>Dauerhaftigkeit:</b> trockenes Holz hält ohne Nachbehandlung; Chemie wirkt zeitlich begrenzt.</li><li><b>Kosten:</b> langfristig günstiger; entspricht DIN-68800-Vorrang.</li></ul>"}, {"id": "hf2e", "group": "hf2", "deck": "HF2E", "n": 8, "typ": "p", "kennung": "HF2e-1", "tax": "Können", "frage": "Ein Terrassenpfosten soll auf einem Punktfundament stehen. <b>Bestimmen Sie die Gebrauchsklasse</b> und planen Sie geeignete Maßnahmen.", "erklaerung": "<p>Aufgabe wie in der Prüfung: erst GK bestimmen, dann passende konstruktive Maßnahmen ableiten.</p>", "loesung": "<ul><li><b>GK:</b> bei korrekter Ausführung <b>GK 3</b> (bewittert, kein direkter Erdkontakt) – nicht GK 4, weil der Pfosten <b>nicht</b> im Boden steht.</li><li><b>Maßnahmen:</b><ul><li>Pfostenträger/Stützenfuß aus Metall mit <b>Abstandshalter</b> (≥ ca. 5–10 cm über Fundament, Spritzwasser).</li><li>Hirnholz unten geschützt, Wasser kann ablaufen.</li><li>dauerhafte Holzart (Lärche/Eiche) oder Imprägnierung.</li><li>Abdeckung des oberen Hirnholzes / Abschrägung.</li></ul></li></ul>"}, {"id": "hf2f", "group": "hf2", "deck": "HF2F", "n": 1, "typ": "p", "kennung": "HF2f-1", "tax": "Können", "frage": "Berechnen Sie das <b>Holzvolumen</b> für 12 Sparren mit Querschnitt 8/20 cm und Länge 4,50 m.", "erklaerung": "<p>Das Volumen eines Kantholzes ist Breite × Höhe × Länge (alles in Metern → m³). Bei Stückzahlen die Anzahl multiplizieren.</p><div class=\"formula\">V = b · h · l · n</div>", "loesung": "<div class=\"formula\">V = 0,08 · 0,20 · 4,50 · 12 = 0,016 · 4,50 · 12</div><div class=\"formula\">= 0,072 · 12 = <b>0,864 m³</b></div><p>Pro Sparren 0,072 m³, gesamt <b>0,864 m³</b> (netto, ohne Verschnitt).</p>"}, {"id": "hf2f", "group": "hf2", "deck": "HF2F", "n": 2, "typ": "p", "kennung": "HF2f-1", "tax": "Können", "frage": "Nennen Sie die typischen <b>Verschnittzuschläge</b> und berechnen Sie die Bestellmenge für 0,864 m³ Bauholz (1,5 %).", "erklaerung": "<p>Beim Zuschnitt entsteht Verschnitt. Auf das Netto-Volumen wird ein materialabhängiger Zuschlag addiert.</p><div class=\"formula\">V<sub>bestell</sub> = V<sub>netto</sub> · (1 + Verschnitt/100)</div>", "loesung": "<p><b>Verschnittsätze (aus Altklausuren):</b> Bauholz <b>1,5 %</b>, Traufbohlen <b>8 %</b>, Profilbretter <b>15 %</b>, Lattung 10–15 %, Dämmplatten 5–10 %.</p><div class=\"formula\">V<sub>bestell</sub> = 0,864 · 1,015 = <b>0,877 m³</b></div>"}, {"id": "hf2f", "group": "hf2", "deck": "HF2F", "n": 3, "typ": "p", "kennung": "HF2f-2", "tax": "Können", "frage": "Ein Satteldach hat eine Halbspannweite a = 4,00 m und eine Firsthöhe h = 3,00 m. <b>Berechnen Sie die Sparrenlänge</b> (ohne Überstand).", "erklaerung": "<p>Der Sparren ist die Hypotenuse des rechtwinkligen Dreiecks aus Halbspannweite und Firsthöhe (Satz des Pythagoras).</p><div class=\"formula\">s = √(a² + h²)</div>", "loesung": "<div class=\"formula\">s = √(4,00² + 3,00²) = √(16 + 9) = √25 = <b>5,00 m</b></div><p>Klassisches 3-4-5-Dreieck. Für die Bestelllänge Dachüberstand (z. B. 0,40–0,70 m) addieren.</p>"}, {"id": "hf2f", "group": "hf2", "deck": "HF2F", "n": 4, "typ": "p", "kennung": "HF2f-2", "tax": "Können", "frage": "Eine Dachfläche hat eine Grundfläche (Projektion) von 60 m² bei einer Dachneigung von 40°. <b>Berechnen Sie die wahre Dachfläche.</b>", "erklaerung": "<p>Die geneigte Dachfläche ist größer als ihre waagerechte Projektion. Man rechnet mit 1/cos α hoch.</p><div class=\"formula\">A<sub>schräg</sub> = A<sub>grund</sub> / cos α</div>", "loesung": "<div class=\"formula\">A<sub>schräg</sub> = 60 / cos 40° = 60 / 0,766 = <b>78,3 m²</b></div><p>Für Deckung/Lattung/Dämmung immer die <b>wahre (schräge) Fläche</b> verwenden, nicht die Grundfläche.</p>"}, {"id": "hf2f", "group": "hf2", "deck": "HF2F", "n": 5, "typ": "p", "kennung": "HF2f-3", "tax": "Können", "frage": "Wie viel <b>Lattung (Laufmeter)</b> wird für eine Dachfläche von 78 m² bei einer Lattweite von 0,35 m benötigt (inkl. 12 % Verschnitt)?", "erklaerung": "<p>Die Lattenmenge ergibt sich aus Dachfläche / Lattweite (= Gesamtlänge der Latten), plus Verschnitt.</p><div class=\"formula\">L = A / LW · (1 + Verschnitt/100)</div>", "loesung": "<div class=\"formula\">L = 78 / 0,35 = 222,9 lfm</div><div class=\"formula\">L<sub>bestell</sub> = 222,9 · 1,12 = <b>≈ 250 lfm</b></div><p>Pro m² Dachfläche werden also rund 1/0,35 ≈ 2,86 lfm Latten benötigt.</p>"}, {"id": "hf2f", "group": "hf2", "deck": "HF2F", "n": 6, "typ": "p", "kennung": "HF2f-2", "tax": "Können", "frage": "Für ein Sparrendach ist die <b>Zwischensparrendämmung</b> zu ermitteln: 10 Felder à 0,78 m Breite, Sparrenlänge 5,00 m. <b>Berechnen Sie die Dämmfläche</b> (5 % Verschnitt).", "erklaerung": "<p>Die Dämmfläche ist die Summe der Gefachflächen (Feldbreite × Sparrenlänge × Anzahl), plus Verschnitt.</p>", "loesung": "<div class=\"formula\">A = 0,78 · 5,00 · 10 = 39,0 m²</div><div class=\"formula\">A<sub>bestell</sub> = 39,0 · 1,05 = <b>≈ 41,0 m²</b></div><p>Dicke nach U-Wert-Anforderung wählen (z. B. 200 mm).</p>"}, {"id": "hf2f", "group": "hf2", "deck": "HF2F", "n": 7, "typ": "v", "kennung": "HF2f-1", "tax": "Wissen", "frage": "Wie ist eine <b>Holzliste / Massenermittlung</b> aufgebaut und wozu dient sie?", "erklaerung": "<p>Die Holzliste übersetzt die Zeichnung in bestellbare Mengen – Grundlage für Einkauf und Kalkulation. Häufigste Rechenaufgabe in HF2.</p>", "loesung": "<p>Spalten: <b>Pos. | Stk. | Querschnitt | Länge | Volumen | Material | Bemerkung</b>.</p><ol><li>je Position Volumen = b·h·l·Stk.</li><li>Positionen aufsummieren → Netto-Volumen</li><li>+ Verschnitt → Bestellmenge</li></ol><p>Dient als Basis für Materialbestellung, Kalkulation und Transportplanung.</p>"}, {"id": "hf2f", "group": "hf2", "deck": "HF2F", "n": 8, "typ": "p", "kennung": "HF2f-1", "tax": "Können", "frage": "Eine Probe wiegt feucht 470 g, darrtrocken 400 g. <b>Berechnen Sie die Holzfeuchte</b> – darf das Holz eingebaut werden?", "erklaerung": "<p>Standardaufgabe: Darrformel anwenden und mit der zulässigen Einbaufeuchte (18 %) vergleichen.</p><div class=\"formula\">u = (m<sub>feucht</sub> − m<sub>darr</sub>) / m<sub>darr</sub> · 100 %</div>", "loesung": "<div class=\"formula\">u = (470 − 400) / 400 · 100 = 70 / 400 · 100 = <b>17,5 %</b></div><p>17,5 % &lt; 18 % → das Holz <b>darf eingebaut werden</b> (ATV DIN 18334 erfüllt).</p>"}, {"id": "hf2f", "group": "hf2", "deck": "HF2F", "n": 9, "typ": "v", "kennung": "HF2f-1", "tax": "Wissen", "frage": "Welche Norm regelt die <b>Aufmaßregeln</b> für Zimmerarbeiten, und was besagt das Prinzip der Abrechnung?", "erklaerung": "<p>Damit Leistungen einheitlich abgerechnet werden, gibt es genormte Aufmaßregeln (welche Flächen brutto, welche Abzüge).</p>", "loesung": "<ul><li><b>ATV DIN 18334</b> (VOB/C) regelt Aufmaß/Abrechnung der Zimmerarbeiten.</li><li>Häufig <b>Brutto-Flächen</b> mit definierten <b>Abzugsregeln</b> (kleine Öffnungen bis zu einer Grenze nicht abgezogen).</li><li><b>DIN 276</b> ordnet die Kosten (Kostengruppen) für die Kalkulation.</li></ul>"}, {"id": "hf2g", "group": "hf2", "deck": "HF2G", "n": 1, "typ": "v", "kennung": "HF2g-1", "tax": "Wissen", "frage": "Unterscheiden Sie die wichtigsten <b>Gerüstarten</b>.", "erklaerung": "<p>Gerüste werden nach Abstützung und Einsatz unterschieden. Das bestimmt Aufbau und Anwendung.</p>", "loesung": "<ul><li><b>Standgerüst (Fassadengerüst):</b> am Boden abgestützt, häufigste Form für Fassadenarbeiten.</li><li><b>Hängegerüst:</b> von oben aufgehängt, wenn keine Bodenabstützung möglich ist.</li><li><b>Raumgerüst (Arbeitsgerüst):</b> freistehend, z. B. für Innenarbeiten/Decken.</li><li><b>Bockgerüst:</b> einfaches Gerüst für geringe Höhen.</li></ul>"}, {"id": "hf2g", "group": "hf2", "deck": "HF2G", "n": 2, "typ": "p", "kennung": "HF2g-1", "tax": "Erkennen", "frage": "Erklären Sie die <b>Gerüstlastklassen</b> nach DIN EN 12811. Welche Klasse ist für Zimmer-/Fassadenarbeiten geeignet?", "erklaerung": "<p>Die Lastklasse legt die zulässige Nutzlast der Gerüstlage fest – je schwerer die Arbeit/Material, desto höhere Klasse.</p>", "loesung": "<table><tr><th>Klasse</th><th>Nutzlast</th><th>Einsatz</th></tr><tr><td>1</td><td>0,75 kN/m²</td><td>Besichtigung</td></tr><tr><td>2</td><td>1,50</td><td>leichte Arbeiten</td></tr><tr><td><b>3</b></td><td><b>2,00</b></td><td><b>Zimmer-/Fassadenarbeiten</b></td></tr><tr><td>4</td><td>3,00</td><td>Putzarbeiten</td></tr><tr><td>5</td><td>4,50</td><td>schwere Arbeiten</td></tr><tr><td>6</td><td>6,00</td><td>sehr schwere Arbeiten</td></tr></table><p>Für Zimmerarbeiten i. d. R. <b>Klasse 3</b>.</p>"}, {"id": "hf2g", "group": "hf2", "deck": "HF2G", "n": 3, "typ": "v", "kennung": "HF2g-2", "tax": "Wissen", "frage": "Welche zentralen <b>Sicherheitsregeln</b> gelten beim Gerüst (Vorlaufmaß, Absturzsicherung, Belagbreite)?", "erklaerung": "<p>Gerüste sind Hauptunfallquelle am Bau. DGUV/DIN EN 12811 geben klare Maße für Sicherheit vor.</p>", "loesung": "<ul><li><b>Wandabstand des Belags:</b> max. <b>30 cm</b> (sonst zusätzlicher Seitenschutz innen).</li><li><b>Absturzsicherung</b> ab <b>2,0 m</b> Absturzhöhe: dreiteiliger Seitenschutz (Geländerholm + Zwischenholm + Bordbrett).</li><li><b>Belagbreite</b>: mind. 60 cm (Klasse 1–2), 90 cm (ab Klasse 3).</li><li>Auf-/Abbau nur durch unterwiesene Personen; Kennzeichnung/Freigabe (Gerüstschein).</li></ul>"}, {"id": "hf2g", "group": "hf2", "deck": "HF2G", "n": 4, "typ": "v", "kennung": "HF2g-1", "tax": "Erkennen", "frage": "Unterscheiden Sie <b>Fanggerüst, Dachfanggerüst und Schutzdach</b>.", "erklaerung": "<p>Schutzgerüste sollen Personen oder Passanten im Absturz-/Gefahrfall sichern – je nach Lage unterschiedlich ausgeführt.</p>", "loesung": "<ul><li><b>Fanggerüst:</b> fängt abstürzende Personen auf (Belag knapp unter der Arbeitsstelle, breiter Seitenschutz).</li><li><b>Dachfanggerüst:</b> speziell für Dacharbeiten – an/unter der Traufe, fängt abrutschende Personen (Schutzwand höher).</li><li><b>Schutzdach (Schutzdachgerüst):</b> schützt Passanten/Verkehr <b>unter</b> der Baustelle vor herabfallenden Teilen.</li></ul>"}, {"id": "hf2g", "group": "hf2", "deck": "HF2G", "n": 5, "typ": "v", "kennung": "HF2g-1", "tax": "Wissen", "frage": "Was sind <b>Lehrgerüste</b> und wann werden sie im Holzbau gebraucht?", "erklaerung": "<p>Lehrgerüste sind temporäre Hilfskonstruktionen, die ein Bauteil während Herstellung/Montage in Form halten, bis es selbst tragfähig ist.</p>", "loesung": "<ul><li>Stützen/formen <b>Bogenbinder, Gewölbe, gekrümmte Träger</b> während der Montage.</li><li>Tragen die Last, bis der Verbund/die Aushärtung/Verbindung wirksam ist.</li><li>Müssen selbst standsicher und genau ausgerichtet sein (Maßhaltigkeit des Endbauteils!).</li></ul>"}, {"id": "hf2g", "group": "hf2", "deck": "HF2G", "n": 6, "typ": "v", "kennung": "HF2g-3", "tax": "Wissen", "frage": "Welche <b>Betonschalungen</b> sind für den Zimmerer relevant und wie sind sie aufgebaut?", "erklaerung": "<p>Zimmerer stellen häufig Schalungen für Beton her. Wand- und Deckenschalung unterscheiden sich im Aufbau und in der Belastung (Frischbetondruck).</p>", "loesung": "<ul><li><b>Wandschalung:</b> Schaltafeln (Holz/Stahl), <b>Schalungsanker</b> (nehmen den Frischbetondruck auf), Abstandhalter, Riegel/Gurtung.</li><li><b>Deckenschalung:</b> Schaltafeln auf <b>Schalungsträgern (H20/T20)</b>, abgestützt durch Deckenstützen; Höhe/Gefälle einstellen.</li><li>Schalung muss dicht, maßhaltig und gegen Aufschwimmen/Verschieben gesichert sein.</li></ul>"}, {"id": "hf2g", "group": "hf2", "deck": "HF2G", "n": 7, "typ": "p", "kennung": "HF2g-3", "tax": "Werten", "frage": "Wovon hängt der <b>Frischbetondruck</b> auf eine Wandschalung ab?", "erklaerung": "<p>Frischer Beton ist flüssig und drückt seitlich auf die Schalung. Der maximale Druck steigt mit Einfüllhöhe/Geschwindigkeit und sinkt mit zunehmender Erstarrung.</p>", "loesung": "<ul><li><b>Betonierhöhe/Steiggeschwindigkeit:</b> schnelleres/höheres Einfüllen → höherer Druck.</li><li><b>Konsistenz</b> des Betons (fließfähiger = höherer Druck).</li><li><b>Temperatur:</b> kälter → langsameres Erstarren → höherer Druck.</li><li><b>Erstarrungsverlauf:</b> sobald Beton ansteift, sinkt der wirksame Druck.</li></ul><p>→ Schalung + Anker auf den maßgebenden Frischbetondruck bemessen.</p>"}, {"id": "hf2g", "group": "hf2", "deck": "HF2G", "n": 8, "typ": "p", "kennung": "HF2g-2", "tax": "Können", "frage": "Für eine <b>Fassadenverkleidung</b> ist ein Gerüst zu planen. <b>Welche Lastklasse</b> wählen Sie und welche Sicherheitsmaße sind einzuhalten?", "erklaerung": "<p>Praxisaufgabe: Lastklasse nach Arbeit + Material wählen und die Sicherheitsregeln benennen.</p>", "loesung": "<ul><li><b>Lastklasse 3</b> (2,0 kN/m²) – ausreichend für Zimmer-/Fassadenarbeiten mit Materiallagerung.</li><li><b>Belagbreite</b> ≥ 90 cm.</li><li><b>Wandabstand</b> ≤ 30 cm (sonst Innenseitenschutz).</li><li><b>Dreiteiliger Seitenschutz</b> ab 2 m Höhe.</li><li>Standsicherheit (Verankerung an Fassade), Freigabe/Kennzeichnung.</li></ul>"}, {"id": "hf2h", "group": "hf2", "deck": "HF2H", "n": 1, "typ": "p", "kennung": "HF2h-1", "tax": "Werten", "frage": "Eine Rohdecke weicht auf einem Stichmaßabstand von 4 m um <b>20 mm</b> ab. <b>Ist das nach DIN 18202 zulässig?</b>", "erklaerung": "<p>DIN 18202 (Tabelle 2, Ebenheit) gibt je Messpunktabstand eine zulässige Abweichung vor. Man vergleicht den Messwert mit dem Grenzwert für den passenden Abstand.</p>", "loesung": "<table><tr><th>Stichmaßabstand</th><th>zul. Abweichung</th></tr><tr><td>0,1 m</td><td>3 mm</td></tr><tr><td>1,0 m</td><td>8 mm</td></tr><tr><td>4,0 m</td><td><b>15 mm</b></td></tr><tr><td>15,0 m</td><td>25 mm</td></tr></table><p><b>Bewertung:</b> bei 4 m sind max. <b>15 mm</b> zulässig. 20 mm &gt; 15 mm → <b>NICHT zulässig</b>. Mangel dokumentieren und rügen, Ausgleich vor Eigenleistung klären.</p>"}, {"id": "hf2h", "group": "hf2", "deck": "HF2H", "n": 2, "typ": "v", "kennung": "HF2h-2", "tax": "Können", "frage": "Wie sollte ein Zimmerer das <b>Aufmaß von Vorleistungen</b> dokumentieren?", "erklaerung": "<p>Bevor man auf einem Vorgewerk aufbaut, prüft man dessen Maßhaltigkeit und hält Abweichungen nachvollziehbar fest – das schützt vor Haftung.</p>", "loesung": "<ul><li><b>Vor Beginn der eigenen Arbeit messen</b> (Lot, Flucht, Ebenheit, Maße).</li><li><b>Aufmaßprotokoll:</b> Datum, Bauteil, Ort, Soll-/Istmaß, Abweichung.</li><li><b>Fotos und Maßskizzen</b> als Beleg.</li><li>Abweichungen <b>schriftlich</b> an Auftraggeber/Vorgewerk melden.</li></ul>"}, {"id": "hf2h", "group": "hf2", "deck": "HF2H", "n": 3, "typ": "v", "kennung": "HF2h-2", "tax": "Wissen", "frage": "Was ist eine <b>Mängelrüge</b> gegenüber dem Vorgewerk und welche Form-/Fristanforderungen gelten?", "erklaerung": "<p>Stellt der Zimmerer Mängel am Vorgewerk fest, muss er diese anzeigen, bevor er darauf aufbaut – sonst haftet er ggf. mit.</p>", "loesung": "<ul><li><b>Form:</b> schriftlich (E-Mail, Brief, Bautagebuch) – beweissicher.</li><li><b>Frist:</b> <b>unverzüglich</b> nach Feststellung (Versäumnis → Mithaftung).</li><li><b>Inhalt:</b> was weicht wo wie stark ab; Auswirkung auf das eigene Gewerk; Aufforderung zur Abhilfe.</li></ul>"}, {"id": "hf2h", "group": "hf2", "deck": "HF2H", "n": 4, "typ": "v", "kennung": "HF2h-2", "tax": "Wissen", "frage": "Was ist eine <b>Behinderungsanzeige</b> nach VOB/B § 6 und warum ist sie wichtig?", "erklaerung": "<p>Wird die eigene Leistung behindert (z. B. Vorgewerk nicht fertig, Witterung, fehlende Pläne), muss das dem Auftraggeber angezeigt werden, um Ansprüche zu sichern.</p>", "loesung": "<ul><li><b>Wann:</b> sobald eine Behinderung die Ausführung verzögert – <b>sofort, schriftlich</b> an den Auftraggeber.</li><li><b>Warum:</b> ohne Anzeige <b>kein Anspruch</b> auf Bauzeitverlängerung oder Mehrkostenvergütung.</li><li><b>Pflicht:</b> selbst zur Abhilfe beitragen (Schadensminderung).</li></ul>"}, {"id": "hf2h", "group": "hf2", "deck": "HF2H", "n": 5, "typ": "v", "kennung": "HF2h-2", "tax": "Erkennen", "frage": "Worin unterscheiden sich <b>Mängelrüge und Behinderungsanzeige</b>?", "erklaerung": "<p>Beide sind schriftliche Anzeigen, betreffen aber unterschiedliche Sachverhalte und Adressaten – ein beliebter Prüfungsvergleich.</p>", "loesung": "<table><tr><th></th><th>Mängelrüge</th><th>Behinderungsanzeige</th></tr><tr><td>Betrifft</td><td>mangelhafte Vorleistung/Lieferung</td><td>Verzögerung/Behinderung der eigenen Leistung</td></tr><tr><td>Ziel</td><td>Mangel beseitigen, Haftung abwehren</td><td>Bauzeit + Mehrkosten sichern</td></tr><tr><td>Grundlage</td><td>VOB/B §13, BGB</td><td>VOB/B §6</td></tr></table>"}, {"id": "hf2h", "group": "hf2", "deck": "HF2H", "n": 6, "typ": "p", "kennung": "HF2h-1", "tax": "Können", "frage": "Eine Wand ist 2,5 m hoch und steht 10 mm aus dem Lot. <b>Beurteilen Sie die Winkel-/Lotabweichung</b> nach DIN 18202 (Richtwert 3 mm/m).", "erklaerung": "<p>Für Lot-/Winkelabweichungen von Wänden gilt ein Richtwert je Meter Bauteilhöhe. Man rechnet die zulässige Gesamtabweichung aus.</p><div class=\"formula\">zul = 3 mm/m · Höhe</div>", "loesung": "<div class=\"formula\">zul = 3 mm/m · 2,5 m = <b>7,5 mm</b></div><p>Die gemessenen <b>10 mm &gt; 7,5 mm</b> → Abweichung <b>überschritten</b>. Dokumentieren, rügen, Ausgleich (z. B. Ausgleichshölzer) vor Montage einplanen.</p>"}, {"id": "hf2h", "group": "hf2", "deck": "HF2H", "n": 7, "typ": "v", "kennung": "HF2h-2", "tax": "Werten", "frage": "Welche Folgen hat eine <b>unterlassene Behinderungsanzeige</b>?", "erklaerung": "<p>Die VOB knüpft Ansprüche an die rechtzeitige, formgerechte Anzeige. Wer schweigt, verliert in der Regel seine Rechte.</p>", "loesung": "<ul><li><b>Kein Anspruch</b> auf Verlängerung der Ausführungsfristen.</li><li><b>Keine Mehrkostenvergütung</b> für den Verzug.</li><li>ggf. eigene <b>Verzugshaftung</b>, obwohl ein Dritter die Ursache setzte.</li></ul><p>→ Anzeige ist die Voraussetzung, um Ansprüche überhaupt geltend machen zu können.</p>"}, {"id": "hf2h", "group": "hf2", "deck": "HF2H", "n": 8, "typ": "v", "kennung": "HF2h-2", "tax": "Wissen", "frage": "Was regelt <b>VOB/B § 13</b> (Mängelansprüche)?", "erklaerung": "<p>§ 13 VOB/B regelt die Gewährleistung für die fertige Bauleistung – Rechte des Auftraggebers bei Mängeln und Verjährungsfristen.</p>", "loesung": "<ul><li>Anspruch auf <b>mangelfreie Leistung</b>; bei Mängeln <b>Nacherfüllung</b> (Beseitigung).</li><li>danach ggf. <b>Minderung</b>, <b>Selbstvornahme</b> auf Kosten des AN, Schadensersatz.</li><li><b>Verjährung</b> Bauwerk i. d. R. <b>4 Jahre</b> (VOB) bzw. 5 Jahre (BGB) ab Abnahme.</li></ul>"}, {"id": "hf3a", "group": "hf3", "deck": "HF3A", "n": 1, "typ": "v", "kennung": "HF3a-1", "tax": "Wissen", "frage": "Nennen Sie die drei <b>Vergabearten</b> nach VOB/A § 3 und grenzen Sie sie ab.", "erklaerung": "<p>Öffentliche Auftraggeber sind an Vergaberegeln gebunden. Die Vergabeart richtet sich nach Auftragswert und Situation.</p>", "loesung": "<ul><li><b>Öffentliche Ausschreibung:</b> unbeschränkte Zahl von Unternehmen wird öffentlich zur Angebotsabgabe aufgefordert (Regelfall, größter Wettbewerb).</li><li><b>Beschränkte Ausschreibung:</b> nur eine begrenzte, ausgewählte Zahl von Firmen wird aufgefordert (ggf. mit Teilnahmewettbewerb).</li><li><b>Freihändige Vergabe / Verhandlungsvergabe:</b> Auftrag wird ohne förmliches Verfahren vergeben (kleine Aufträge, Dringlichkeit, Spezialleistung).</li></ul>"}, {"id": "hf3a", "group": "hf3", "deck": "HF3A", "n": 2, "typ": "v", "kennung": "HF3a-2", "tax": "Wissen", "frage": "Wie läuft eine <b>öffentliche Ausschreibung</b> grundsätzlich ab?", "erklaerung": "<p>Die öffentliche Ausschreibung soll transparenten Wettbewerb sichern. Sie folgt festen Schritten von der Bekanntmachung bis zum Zuschlag.</p>", "loesung": "<ol><li><b>Bekanntmachung</b> (öffentlich, mit Leistungsbeschreibung/LV).</li><li>Bewerber fordern <b>Vergabeunterlagen</b> an.</li><li><b>Angebotsabgabe</b> form- und fristgerecht (verschlossen).</li><li><b>Submission</b> (Öffnungstermin), Prüfung & Wertung.</li><li><b>Zuschlag</b> auf das wirtschaftlichste Angebot (nicht zwingend billigste).</li></ol>"}, {"id": "hf3a", "group": "hf3", "deck": "HF3A", "n": 3, "typ": "v", "kennung": "HF3a-3", "tax": "Können", "frage": "Welche Wege der <b>privaten Auftragsbeschaffung</b> gibt es, und warum ist Empfehlungsmarketing wertvoll?", "erklaerung": "<p>Im privaten Markt entscheidet Vertrauen. Zufriedene Kunden und ein gutes Netzwerk bringen oft mehr als Werbung.</p>", "loesung": "<ul><li><b>Empfehlungsmarketing / Mundpropaganda:</b> günstigste und glaubwürdigste Akquise; zufriedene Kunden empfehlen weiter.</li><li><b>Stammkunden</b> pflegen (Wiederholungsaufträge).</li><li><b>Netzwerk</b> (Architekten, Bauträger, andere Gewerke).</li><li><b>Eigenwerbung</b>: Website, Referenzen, Beschriftung, lokale Präsenz.</li></ul>"}, {"id": "hf3a", "group": "hf3", "deck": "HF3A", "n": 4, "typ": "v", "kennung": "HF3a-3", "tax": "Werten", "frage": "Welche Chancen und Risiken bieten <b>Handwerker-Plattformen</b> (z. B. MyHammer)?", "erklaerung": "<p>Online-Plattformen vermitteln Aufträge, schaffen aber starken Preiswettbewerb. Chancen und Risiken müssen abgewogen werden.</p>", "loesung": "<table><tr><th>Chancen</th><th>Risiken</th></tr><tr><td>schneller Zugang zu Aufträgen</td><td>starker Preisdruck / Dumping</td></tr><tr><td>Auslastung von Lücken</td><td>Gebühren/Provisionen</td></tr><tr><td>Bewertungen als Werbung</td><td>oft „Geiz\"-Kunden, wenig Bindung</td></tr></table><p>Sinnvoll selektiv nutzen, nicht als alleinige Quelle.</p>"}, {"id": "hf3a", "group": "hf3", "deck": "HF3A", "n": 5, "typ": "v", "kennung": "HF3a-3", "tax": "Werten", "frage": "Was versteht man unter einer <b>Angebotsstrategie</b> – wann bietet man an, wann nicht?", "erklaerung": "<p>Nicht jeder Auftrag ist lohnend. Eine bewusste Auswahl schützt vor Verzettelung und Verlustaufträgen.</p>", "loesung": "<ul><li><b>Kapazität:</b> Ist der Betrieb frei? (sonst selektiv/teurer anbieten)</li><li><b>Deckungsbeitrag:</b> trägt der Auftrag zu Fixkosten + Gewinn bei?</li><li><b>Risiko:</b> Bonität des Kunden, Komplexität, Haftung.</li><li><b>Strategie:</b> Referenzauftrag, Folgegeschäft, Region.</li></ul><p>Bei voller Auslastung: nur lukrative Aufträge mit gutem Preis annehmen.</p>"}, {"id": "hf3a", "group": "hf3", "deck": "HF3A", "n": 6, "typ": "v", "kennung": "HF3a-2", "tax": "Wissen", "frage": "Was regelt <b>VOB/A § 8</b> (Vergabeunterlagen)?", "erklaerung": "<p>Damit alle Bieter die gleiche Grundlage haben, sind Inhalt und Form der Vergabeunterlagen geregelt.</p>", "loesung": "<ul><li>Inhalt der <b>Vergabe-/Verdingungsunterlagen</b>: Anschreiben, Bewerbungsbedingungen, Vertragsbedingungen und <b>Leistungsbeschreibung (LV)</b>.</li><li>Die Leistung ist <b>eindeutig und erschöpfend</b> zu beschreiben, damit Angebote vergleichbar sind.</li><li>keine ungewöhnlichen Wagnisse auf den Bieter abwälzen.</li></ul>"}, {"id": "hf3a", "group": "hf3", "deck": "HF3A", "n": 7, "typ": "v", "kennung": "HF3a-3", "tax": "Wissen", "frage": "Welche Anforderungen an <b>Form und Frist</b> von Angeboten stellt VOB/A § 13?", "erklaerung": "<p>Formfehler führen zum Ausschluss. Deshalb sind Form und Frist der Angebote streng geregelt.</p>", "loesung": "<ul><li>Angebote form- und fristgerecht, <b>verschlossen</b> (bzw. elektronisch signiert) bis zum Submissionstermin.</li><li><b>Vollständig</b> ausgefüllt, alle geforderten Preise/Erklärungen.</li><li><b>Bindefrist</b> beachten (Angebot bleibt bis Zuschlag verbindlich).</li><li>Nachträgliche Änderungen / verspätete Angebote → <b>Ausschluss</b>.</li></ul>"}, {"id": "hf3a", "group": "hf3", "deck": "HF3A", "n": 8, "typ": "p", "kennung": "HF3a-1", "tax": "Erkennen", "frage": "Ordnen Sie zu: Für welche Situationen eignen sich öffentliche, beschränkte bzw. freihändige Vergabe?", "erklaerung": "<p>Die Wahl der Vergabeart hängt v. a. vom Auftragswert und besonderen Umständen ab (Schwellenwerte, Dringlichkeit).</p>", "loesung": "<ul><li><b>Öffentliche Ausschreibung:</b> Regelfall, größere Aufträge über den Wertgrenzen → maximaler Wettbewerb.</li><li><b>Beschränkte Ausschreibung:</b> mittlere Aufträge, oder wenn öffentliche Ausschreibung unwirtschaftlich/unzweckmäßig wäre, Eignung wichtig.</li><li><b>Freihändige Vergabe:</b> kleine Auftragswerte, Dringlichkeit, Patent-/Spezialleistung, nur ein geeigneter Anbieter.</li></ul><p>Faustregel: je höher der Wert, desto formeller das Verfahren.</p>"}, {"id": "hf3b", "group": "hf3", "deck": "HF3B", "n": 1, "typ": "v", "kennung": "HF3b-1", "tax": "Wissen", "frage": "Beschreiben Sie das <b>Kalkulationsschema</b> der Angebotskalkulation (von den Einzelkosten bis zum Angebotspreis).", "erklaerung": "<p>Der Angebotspreis baut sich stufenweise aus den Einzelkosten der Teilleistungen plus Zuschlägen auf. Wer das Schema kennt, kann jede Position kalkulieren.</p>", "loesung": "<ol><li><b>Einzelkosten der Teilleistungen (EKdT):</b> Material + Lohn + Geräte + Nachunternehmer.</li><li>+ <b>Baustellengemeinkosten (BGK)</b> (Bauleitung, Einrichtung).</li><li>= Herstellkosten</li><li>+ <b>Allgemeine Geschäftskosten (AGK)</b> (Verwaltung, Büro).</li><li>+ <b>Wagnis & Gewinn (W&G)</b>.</li><li>= Angebotssumme netto + <b>MwSt</b> = Angebotspreis.</li></ol>"}, {"id": "hf3b", "group": "hf3", "deck": "HF3B", "n": 2, "typ": "p", "kennung": "HF3b-3", "tax": "Können", "frage": "Berechnen Sie den <b>Stundenverrechnungssatz</b>: Mittellohn 22,00 €/h, Lohnzusatzkosten 82 %, anteilige Gemeinkosten 95 % auf die Lohnkosten, Wagnis & Gewinn 8 %.", "erklaerung": "<p>Der Stundenverrechnungssatz ist der Preis, zu dem eine Arbeitsstunde verkauft wird. Er enthält neben dem Lohn die Lohnzusatzkosten, Gemeinkosten und W&G.</p>", "loesung": "<p><b>1. Kalkulationslohn</b> (Lohn + Zusatzkosten):</p><div class=\"formula\">22,00 · 1,82 = 40,04 €/h</div><p><b>2. + Gemeinkosten 95 %:</b></p><div class=\"formula\">40,04 · 1,95 = 78,08 €/h</div><p><b>3. + Wagnis & Gewinn 8 %:</b></p><div class=\"formula\">78,08 · 1,08 = <b>84,33 €/h</b> (netto)</div><p>Dieser Satz wird mit dem Zeitaufwand je Position multipliziert.</p>"}, {"id": "hf3b", "group": "hf3", "deck": "HF3B", "n": 3, "typ": "p", "kennung": "HF3b-4", "tax": "Können", "frage": "Ermitteln Sie den <b>Einheitspreis</b> für 1 m² Dachschalung: Material 9,50 €/m² (inkl. 15 % Verschnitt), Zeitaufwand 0,25 h/m², Stundensatz 84,00 €/h.", "erklaerung": "<p>Der Einheitspreis (EP) einer LV-Position setzt sich aus den Materialkosten je Einheit und den Lohnkosten (Zeitaufwand × Stundensatz) zusammen (+ ggf. Geräteanteil).</p><div class=\"formula\">EP = Materialkosten + (Zeit · Stundensatz)</div>", "loesung": "<p><b>Lohnanteil:</b></p><div class=\"formula\">0,25 h/m² · 84,00 €/h = 21,00 €/m²</div><p><b>Einheitspreis:</b></p><div class=\"formula\">EP = 9,50 + 21,00 = <b>30,50 €/m²</b> (netto)</div><p>Bei 120 m² Dachfläche → Positionsbetrag 120 · 30,50 = 3 660 € netto.</p>"}, {"id": "hf3b", "group": "hf3", "deck": "HF3B", "n": 4, "typ": "p", "kennung": "HF3b-3", "tax": "Können", "frage": "Berechnen Sie den <b>Maschinenstundensatz</b> einer Abbundmaschine: Anschaffung 60 000 €, Nutzungsdauer 10 Jahre, 1 200 Betriebsstunden/Jahr, Reparatur+Betriebsstoffe 6,00 €/h, kalk. Zinssatz 5 % (halber Anschaffungswert).", "erklaerung": "<p>Der Maschinenstundensatz verteilt Abschreibung, Verzinsung und laufende Kosten auf die Betriebsstunden – Grundlage, um Gerätekosten zu kalkulieren.</p><div class=\"formula\">Satz = (AfA + Zinsen)/Std. + Reparatur + Betriebsstoffe</div>", "loesung": "<p><b>AfA/Jahr:</b> 60 000 / 10 = 6 000 € → /1200 h = 5,00 €/h</p><p><b>Zinsen/Jahr:</b> 5 % auf halben Wert = 0,05 · 30 000 = 1 500 € → /1200 h = 1,25 €/h</p><p><b>Reparatur/Betriebsstoffe:</b> 6,00 €/h</p><div class=\"formula\">Maschinenstundensatz = 5,00 + 1,25 + 6,00 = <b>12,25 €/h</b></div>"}, {"id": "hf3b", "group": "hf3", "deck": "HF3B", "n": 5, "typ": "v", "kennung": "HF3b-5", "tax": "Wissen", "frage": "Unterscheiden Sie <b>Skonto, Rabatt und Nachlass</b>.", "erklaerung": "<p>Diese Preisnachlässe unterscheiden sich in Anlass und Berechnung – wichtig für Angebot und Rechnung.</p>", "loesung": "<ul><li><b>Skonto:</b> Abzug für <b>schnelle Zahlung</b> innerhalb einer Frist (z. B. 2 % bei Zahlung in 10 Tagen) – Finanzierungsanreiz.</li><li><b>Rabatt:</b> Preisnachlass aus bestimmtem Grund (Mengen-, Treue-, Wiederverkäuferrabatt), oft vorab vereinbart.</li><li><b>Nachlass:</b> einmalige Minderung der Gesamt-/Angebotssumme (z. B. zum Auftragsabschluss).</li></ul>"}, {"id": "hf3b", "group": "hf3", "deck": "HF3B", "n": 6, "typ": "v", "kennung": "HF3b-4", "tax": "Wissen", "frage": "Was regeln <b>§ 631 und § 632 BGB</b> zum Werkvertrag?", "erklaerung": "<p>Der Werkvertrag ist die rechtliche Grundlage jedes Bauauftrags. Diese Paragraphen regeln Leistung, Vergütung und Kostenvoranschlag.</p>", "loesung": "<ul><li><b>§ 631 BGB:</b> Der Unternehmer schuldet die Herstellung des <b>versprochenen Werks (Erfolg!)</b>, der Besteller die Vergütung.</li><li><b>§ 632 BGB:</b> Vergütung gilt als stillschweigend vereinbart, wenn Werk üblicherweise nur gegen Bezahlung erfolgt; ein <b>Kostenvoranschlag ist im Zweifel nicht zu vergüten</b>.</li></ul>"}, {"id": "hf3b", "group": "hf3", "deck": "HF3B", "n": 7, "typ": "v", "kennung": "HF3b-4", "tax": "Wissen", "frage": "Was ist das <b>EFB-Preisblatt</b> und wann wird es benötigt?", "erklaerung": "<p>Bei öffentlichen Aufträgen muss der Bieter seine Preisbildung offenlegen. Dafür dienen die EFB-Formblätter (Einheitliche Formblätter Preise).</p>", "loesung": "<ul><li><b>EFB-Preis (z. B. Formblatt 221/222):</b> legt die <b>Zuschlagskalkulation</b> offen (Lohn, Stoffkosten, Geräte, Zuschläge für BGK/AGK/W&G).</li><li>Pflicht bei <b>öffentlichen Ausschreibungen</b> zur Prüfung der Angemessenheit der Preise.</li><li>Dient dem Auftraggeber zur Bewertung und bei Nachträgen.</li></ul>"}, {"id": "hf3b", "group": "hf3", "deck": "HF3B", "n": 8, "typ": "v", "kennung": "HF3b-4", "tax": "Wissen", "frage": "Wie ist ein <b>Leistungsverzeichnis (LV)</b> aufgebaut und worauf achtet man beim Lesen?", "erklaerung": "<p>Das LV beschreibt alle Leistungen positionsweise. Wer es richtig liest, kalkuliert vollständig und vermeidet Lücken.</p>", "loesung": "<ul><li><b>Gliederung:</b> Titel/Lose → Positionen mit <b>Ordnungszahl (OZ)</b>, Kurz-/Langtext, <b>Menge</b>, <b>Einheit</b>, EP, GP.</li><li>Auf <b>Mengeneinheit</b> (m, m², m³, Stk, psch) und <b>Aufmaßgrundlage</b> achten.</li><li><b>Vorbemerkungen</b> beachten (Nebenleistungen, Bauzeiten).</li><li>Eventualpositionen / Bedarfspositionen erkennen.</li></ul>"}, {"id": "hf3b", "group": "hf3", "deck": "HF3B", "n": 9, "typ": "p", "kennung": "HF3b-4", "tax": "Können", "frage": "Eine Netto-Angebotssumme beträgt 14 800 €. <b>Berechnen Sie den Bruttobetrag</b> (19 % MwSt).", "erklaerung": "<p>Auf die Netto-Angebotssumme wird die Umsatzsteuer aufgeschlagen, um den Bruttopreis (Endpreis für den Kunden) zu erhalten.</p><div class=\"formula\">Brutto = Netto · 1,19</div>", "loesung": "<div class=\"formula\">MwSt = 14 800 · 0,19 = 2 812 €</div><div class=\"formula\">Brutto = 14 800 + 2 812 = <b>17 612 €</b></div>"}, {"id": "hf3c", "group": "hf3", "deck": "HF3C", "n": 1, "typ": "v", "kennung": "HF3c-1", "tax": "Wissen", "frage": "Was ist ein <b>Balkenplan (Gantt-Diagramm)</b> und was bedeutet der „kritische Pfad\"?", "erklaerung": "<p>Der Balkenplan stellt Vorgänge zeitlich als Balken dar. Er zeigt Dauer, Reihenfolge und Abhängigkeiten der Bauabschnitte.</p>", "loesung": "<ul><li><b>Balkenplan:</b> jeder Vorgang = waagerechter Balken auf einer Zeitachse; Länge = Dauer, Lage = Termin.</li><li><b>Meilensteine:</b> wichtige Zwischenziele (Dauer 0).</li><li><b>Kritischer Pfad:</b> die Vorgangskette ohne Puffer – verzögert sich hier ein Vorgang, verschiebt sich der <b>Endtermin</b>.</li></ul>"}, {"id": "hf3c", "group": "hf3", "deck": "HF3C", "n": 2, "typ": "v", "kennung": "HF3c-2", "tax": "Wissen", "frage": "Was umfasst die <b>Kapazitätsplanung</b> und warum ist sie wichtig?", "erklaerung": "<p>Damit Termine halten, müssen Personal und Geräte zur richtigen Zeit in richtiger Menge verfügbar sein.</p>", "loesung": "<ul><li>Ermittlung des <b>Arbeitskräfte- und Gerätebedarfs</b> je Bauabschnitt (aus Mengen × Aufwandswerten).</li><li>Abgleich mit verfügbarer Kapazität → Engpässe erkennen.</li><li>Ziel: gleichmäßige Auslastung, keine Leerläufe/Überlast, Termintreue.</li></ul>"}, {"id": "hf3c", "group": "hf3", "deck": "HF3C", "n": 3, "typ": "v", "kennung": "HF3c-1", "tax": "Wissen", "frage": "Was wird in der <b>Arbeitsvorbereitung (AV)</b> vor Baubeginn geplant?", "erklaerung": "<p>Die AV stellt sicher, dass auf der Baustelle alles bereitsteht – Pläne, Material, Geräte, Personal, Sicherheit.</p>", "loesung": "<ul><li>Werk-/Abbundpläne, <b>Stücklisten</b>, Materialdisposition.</li><li><b>Montageanweisung</b>: Reihenfolge, Transportlage, <b>Anschlagpunkte</b>, Bauteilgewichte.</li><li>Termin- und Kapazitätsplanung, Geräteeinsatz.</li><li>Baustelleneinrichtung, Sicherheit (Gerüst, PSA).</li></ul>"}, {"id": "hf3c", "group": "hf3", "deck": "HF3C", "n": 4, "typ": "v", "kennung": "HF3c-3", "tax": "Können", "frage": "Wie wird die <b>Qualität</b> auf der Baustelle gesichert und dokumentiert?", "erklaerung": "<p>Qualitätssicherung heißt, Fehler früh zu erkennen und nachweisbar korrekt zu arbeiten – das schützt vor Gewährleistungsstreit.</p>", "loesung": "<ul><li><b>Eigenüberwachung:</b> Maße, Holzfeuchte, Verbindungen prüfen.</li><li><b>Dokumentation:</b> <b>Bautagebuch</b>, Foto­dokumentation, Prüfprotokolle, Lieferscheine.</li><li>Soll-Ist-Vergleich, Checklisten.</li><li>Dokumente als Nachweis bei Abnahme/Streit aufbewahren.</li></ul>"}, {"id": "hf3c", "group": "hf3", "deck": "HF3C", "n": 5, "typ": "v", "kennung": "HF3c-3", "tax": "Wissen", "frage": "Wie läuft die <b>förmliche Abnahme</b> nach VOB/B § 12 ab?", "erklaerung": "<p>Die Abnahme ist der zentrale Moment im Bauvertrag: Sie bestätigt die Leistung und löst wichtige Rechtsfolgen aus.</p>", "loesung": "<ul><li>Gemeinsame Begehung; Ergebnis in einem <b>Abnahmeprotokoll</b> (Mängel, Vorbehalte, Restleistungen, Datum, Unterschriften).</li><li><b>Rechtsfolgen der Abnahme:</b> Beginn der Gewährleistungsfrist, Fälligkeit der Schlusszahlung, <b>Gefahrübergang</b>, Umkehr der Beweislast.</li><li>Teilabnahmen möglich.</li></ul>"}, {"id": "hf3c", "group": "hf3", "deck": "HF3C", "n": 6, "typ": "v", "kennung": "HF3c-3", "tax": "Wissen", "frage": "Was besagt die <b>Abnahmefiktion</b> nach § 640 BGB?", "erklaerung": "<p>Verweigert der Besteller die Abnahme ohne Mängelangabe, kann das Werk trotzdem als abgenommen gelten – damit der Unternehmer nicht endlos im Risiko bleibt.</p>", "loesung": "<p>Setzt der Unternehmer dem Besteller nach Fertigstellung eine <b>angemessene Frist</b> zur Abnahme und verweigert dieser sie <b>nicht unter Angabe mindestens eines Mangels</b>, gilt das Werk nach Fristablauf als <b>abgenommen</b> (Abnahmefiktion). Bei Verbrauchern ist ein Hinweis auf diese Folge nötig.</p>"}, {"id": "hf3c", "group": "hf3", "deck": "HF3C", "n": 7, "typ": "v", "kennung": "HF3c-3", "tax": "Wissen", "frage": "Wer trägt nach § 644 BGB die <b>Gefahr</b> – und bis wann?", "erklaerung": "<p>Die Gefahrtragung regelt, wer das Risiko trägt, wenn das Werk vor Fertigstellung beschädigt wird (z. B. Sturm).</p>", "loesung": "<p>Bis zur <b>Abnahme</b> trägt der <b>Unternehmer</b> die Vergütungsgefahr: Geht das Werk vorher unter/wird beschädigt (ohne Verschulden des Bestellers), erhält er keine Vergütung und muss neu herstellen. <b>Mit der Abnahme</b> geht die Gefahr auf den Besteller über. → Abnahme ist auch deshalb so wichtig.</p>"}, {"id": "hf3c", "group": "hf3", "deck": "HF3C", "n": 8, "typ": "v", "kennung": "HF3c-3", "tax": "Wissen", "frage": "Was ist eine <b>Bedenkenanzeige</b> nach VOB/B § 4 Abs. 3 und welche Wirkung hat sie?", "erklaerung": "<p>Erkennt der Unternehmer Probleme an Planung, Vorleistung oder angeordneter Ausführung, muss er Bedenken anmelden – sonst haftet er mit.</p>", "loesung": "<ul><li><b>Wann:</b> bei Bedenken gegen Art der Ausführung, Güte von Vorleistungen/Stoffen, Anordnungen des AG.</li><li><b>Form:</b> <b>unverzüglich und schriftlich</b> an den Auftraggeber, vor Ausführung.</li><li><b>Wirkung:</b> korrekte Bedenkenanzeige <b>befreit von der Haftung</b>, wenn der AG trotzdem die Ausführung verlangt.</li></ul>"}, {"id": "hf3d", "group": "hf3", "deck": "HF3D", "n": 1, "typ": "v", "kennung": "HF3d-1", "tax": "Wissen", "frage": "Erklären Sie die <b>Normen- und Regelhierarchie</b> im Bauwesen.", "erklaerung": "<p>Nicht alle Regeln sind gleichrangig. Gesetze stehen über Verträgen, technische Normen konkretisieren den „Stand der Technik\".</p>", "loesung": "<ol><li><b>Gesetze/Verordnungen</b> (BGB, Landesbauordnung) – verbindlich.</li><li><b>VOB</b> (bei Vereinbarung Vertragsbestandteil).</li><li><b>DIN-Normen / EC</b> – anerkannte Regeln der Technik.</li><li><b>Hersteller-Zulassungen</b> (ETA, abZ/aBG) – produktspezifisch.</li></ol><p>Einhaltung = „Stand der Technik\" → Rechts- und Haftungssicherheit.</p>"}, {"id": "hf3d", "group": "hf3", "deck": "HF3D", "n": 2, "typ": "v", "kennung": "HF3d-1", "tax": "Wissen", "frage": "Erklären Sie die <b>Nutzungsklassen (NKL 1/2/3)</b> nach EC5 und ihre Bedeutung.", "erklaerung": "<p>Die Nutzungsklasse beschreibt das Feuchteklima des Bauteils. Sie beeinflusst Festigkeit (k_mod), Verformung (k_def) und Holzschutz.</p>", "loesung": "<ul><li><b>NKL 1:</b> innen, beheizt, trocken (Holzfeuchte ~ ≤ 12 %). Beispiel: Wohnraum.</li><li><b>NKL 2:</b> überdacht, gelegentlich feucht (~ ≤ 20 %). Beispiel: belüfteter Dachraum, Carport.</li><li><b>NKL 3:</b> bewittert/außen, hohe Feuchte. Beispiel: ungeschützte Außenbauteile.</li></ul><p>Höhere NKL → kleineres k<sub>mod</sub>, größeres Kriechen (k<sub>def</sub>), höhere Holzschutzanforderung.</p>"}, {"id": "hf3d", "group": "hf3", "deck": "HF3D", "n": 3, "typ": "v", "kennung": "HF3d-1", "tax": "Wissen", "frage": "Welche <b>Sortierklassen</b> kennt DIN 4074 und wie hängen sie mit den Festigkeitsklassen zusammen?", "erklaerung": "<p>Bauholz wird visuell (oder maschinell) sortiert. Die Sortierklasse bestimmt die zulässige Festigkeitsklasse.</p>", "loesung": "<table><tr><th>Sortierklasse (DIN 4074)</th><th>Festigkeitsklasse (EN 338)</th></tr><tr><td>S7</td><td>C16</td></tr><tr><td>S10</td><td>C24 (Standard, auch Dachlatten)</td></tr><tr><td>S13</td><td>C30</td></tr></table><p>Sortierkriterien: Äste, Faserneigung, Risse, Baumkante, Markröhre. Schwindrisse bis zur halben Bauteildicke sind i. d. R. zulässig.</p>"}, {"id": "hf3d", "group": "hf3", "deck": "HF3D", "n": 4, "typ": "v", "kennung": "HF3d-4", "tax": "Wissen", "frage": "Was regelt die <b>ATV DIN 18334</b>, und was ist der Unterschied zwischen Nebenleistung und Besonderer Leistung?", "erklaerung": "<p>Die ATV DIN 18334 (VOB/C) ist die Ausführungsnorm für Zimmer- und Holzbauarbeiten. Sie unterscheidet, welche Leistungen im Einheitspreis enthalten sind.</p>", "loesung": "<ul><li><b>Geltung:</b> Zimmer- und Holzbauarbeiten – Ausführung, Stoffe, Abrechnung.</li><li><b>Nebenleistung:</b> ohne besondere Vergütung im EP enthalten (z. B. einfaches Aufmaß, Gerüst bis 3,50 m Arbeitshöhe).</li><li><b>Besondere Leistung:</b> nur bei Vereinbarung, <b>gesondert zu vergüten</b> (z. B. Gerüst &gt; 3,50 m, besondere Schutzmaßnahmen).</li></ul>"}, {"id": "hf3d", "group": "hf3", "deck": "HF3D", "n": 5, "typ": "v", "kennung": "HF3d-2", "tax": "Werten", "frage": "Worin unterscheiden sich <b>BGB-Werkvertrag und VOB/B</b> bei der Gewährleistung?", "erklaerung": "<p>Je nachdem, ob die VOB/B vereinbart ist, gelten unterschiedliche Fristen und Regeln für Mängelansprüche.</p>", "loesung": "<table><tr><th></th><th>BGB</th><th>VOB/B</th></tr><tr><td>Verjährung Bauwerk</td><td><b>5 Jahre</b> ab Abnahme</td><td><b>4 Jahre</b> ab Abnahme</td></tr><tr><td>Geltung</td><td>immer (gesetzlich)</td><td>nur wenn vereinbart</td></tr><tr><td>Abschläge</td><td>§ 632a</td><td>§ 16 (21 Tage)</td></tr></table><p>VOB/B muss als Ganzes vereinbart werden (sonst AGB-Inhaltskontrolle).</p>"}, {"id": "hf3d", "group": "hf3", "deck": "HF3D", "n": 6, "typ": "v", "kennung": "HF3d-3", "tax": "Werten", "frage": "Wie befreit eine <b>Bedenkenanzeige</b> von der Haftung, und welche Voraussetzungen müssen erfüllt sein?", "erklaerung": "<p>Der Unternehmer hat eine Prüf- und Hinweispflicht. Erkennt er Mängel an Vorgaben, muss er warnen – sonst haftet er trotz fremder Ursache.</p>", "loesung": "<ul><li>Voraussetzungen: <b>unverzüglich</b>, <b>schriftlich</b>, an den <b>richtigen Adressaten</b> (AG/Bauleitung), <b>inhaltlich konkret</b> (welche Folge droht).</li><li>Führt der AG die Ausführung trotzdem an → <b>Haftungsbefreiung</b> des Unternehmers (VOB/B § 13 Abs. 3 / § 4).</li><li>Ohne Anzeige: volle Mängelhaftung, auch wenn die Ursache beim Planer/Vorgewerk lag.</li></ul>"}, {"id": "hf3d", "group": "hf3", "deck": "HF3D", "n": 7, "typ": "v", "kennung": "HF3d-1", "tax": "Wissen", "frage": "Was ist die <b>Bauhandwerkersicherung</b> nach § 650f BGB?", "erklaerung": "<p>Der Unternehmer geht in Vorleistung und trägt das Risiko, am Ende nicht bezahlt zu werden. § 650f gibt ihm ein Sicherungsrecht.</p>", "loesung": "<ul><li>Der Unternehmer kann vom Besteller eine <b>Sicherheit</b> (z. B. Bankbürgschaft) in Höhe der noch nicht gezahlten Vergütung verlangen.</li><li>Wird sie nicht gestellt, darf der Unternehmer die Arbeit <b>einstellen</b> oder kündigen.</li><li>Gilt nicht gegenüber Verbrauchern beim Verbraucherbauvertrag/einzelnen Fällen.</li></ul>"}, {"id": "hf3d", "group": "hf3", "deck": "HF3D", "n": 8, "typ": "v", "kennung": "HF3d-1", "tax": "Wissen", "frage": "Welches <b>Widerrufsrecht</b> hat ein Verbraucher (§ 650l BGB / Verbraucherbauvertrag)?", "erklaerung": "<p>Verbraucher werden im Bauvertragsrecht besonders geschützt. Bei Verbraucherbauverträgen besteht ein Widerrufsrecht.</p>", "loesung": "<ul><li><b>Widerrufsfrist 14 Tage</b> ab Vertragsschluss (bei ordnungsgemäßer Belehrung).</li><li>Ohne/Fehlerhafte Belehrung: bis zu <b>12 Monate + 14 Tage</b>.</li><li>Pflicht zur <b>Baubeschreibung</b> (§ 650k) und Textform (§ 650i).</li></ul>"}, {"id": "hf3d", "group": "hf3", "deck": "HF3D", "n": 9, "typ": "p", "kennung": "HF3d-1", "tax": "Werten", "frage": "Ein Verbindungsmittel wird <b>abweichend von seiner ETA-Zulassung</b> eingebaut (falscher Achsabstand). <b>Beurteilen Sie die Haftungsfolge.</b>", "erklaerung": "<p>Zulassungen (ETA/abZ) gelten nur bei Einhaltung der Einbaubedingungen. Jede Abweichung kann die Zulassung – und damit die Verwendbarkeit – entfallen lassen.</p>", "loesung": "<ul><li>Mit der Abweichung <b>erlischt die Zulassung</b> für diesen Einbau → kein gültiger Verwendbarkeitsnachweis.</li><li>Folge: Das Bauteil entspricht <b>nicht dem Stand der Technik</b> → <b>Mangel</b>; der Unternehmer haftet voll (Nacherfüllung/Schadensersatz).</li><li>Zusätzlich mögliche <b>Sicherheits-/Standsicherheitsprobleme</b>.</li><li>Richtig: nach Zulassung einbauen oder Einzelnachweis/Zustimmung im Einzelfall einholen.</li></ul>"}, {"id": "hf3e", "group": "hf3", "deck": "HF3E", "n": 1, "typ": "v", "kennung": "HF3e-2", "tax": "Erkennen", "frage": "Welche <b>Genehmigungsverfahren</b> kennt die Brandenburgische Bauordnung (BbgBO)?", "erklaerung": "<p>Je nach Größe/Art des Vorhabens ist ein unterschiedlich aufwendiges Verfahren nötig – von verfahrensfrei bis zum regulären Verfahren.</p>", "loesung": "<ul><li><b>§ 61 Verfahrensfrei:</b> kleine, risikoarme Vorhaben ohne Genehmigung.</li><li><b>§ 62 Bauanzeigeverfahren:</b> Wohngebäude <b>GK 1–2</b> im Geltungsbereich eines B-Plans; Baubeginn nach 1 Monat, wenn die Behörde nicht untersagt.</li><li><b>§ 63 Vereinfachtes Verfahren:</b> Wohngebäude <b>GK 1–3</b> im B-Plan-Bereich; nur eingeschränkte Prüfung (B-Plan + sonstiges öff. Recht), Genehmigungsfiktion nach 3 Monaten.</li><li><b>§ 64 Reguläres Baugenehmigungsverfahren:</b> volle Prüfung (BauGB + BbgBO + sonstiges Recht), v. a. Sonderbauten.</li></ul><p class=\"muted\">Stand 2026 – Verfahrens-§§ 59–64 werden erst zum 1.1.2027 novelliert (für Prüfung Sept. 2026 noch nicht relevant).</p>"}, {"id": "hf3e", "group": "hf3", "deck": "HF3E", "n": 2, "typ": "v", "kennung": "HF3e-2", "tax": "Erkennen", "frage": "Nennen Sie typische <b>verfahrensfreie Vorhaben</b> nach § 61 BbgBO.", "erklaerung": "<p>Kleine, risikoarme Bauten dürfen ohne Genehmigung errichtet werden – materielle Vorschriften (Abstand, Standsicherheit) gelten trotzdem.</p>", "loesung": "<ul><li>Gebäude <b>ohne Aufenthaltsräume</b> bis <b>75 m³</b> Brutto-Rauminhalt (Gartenhaus, Schuppen; nicht im Außenbereich).</li><li><b>Terrassenüberdachungen</b> bis <b>30 m²</b> Fläche und 4 m Tiefe.</li><li><b>Garagen/Carports</b> bis <b>50 m²</b> Brutto-Grundfläche, mittlere Wandhöhe ≤ 3 m.</li><li><b>Gartenlauben</b> inkl. Freisitz bis 24 m² in Kleingartenanlagen.</li><li><b>Bedachung inkl. Wärmedämmung</b> und <b>Solaranlagen</b> auf dem Dach (außer Hochhäuser).</li></ul><p><b>Achtung:</b> verfahrensfrei ≠ vorschriftenfrei – Abstandsflächen, B-Plan, Standsicherheit und Brandschutz bleiben einzuhalten.</p>"}, {"id": "hf3e", "group": "hf3", "deck": "HF3E", "n": 3, "typ": "p", "kennung": "HF3e-2", "tax": "Können", "frage": "Eine Wand ist 6,00 m hoch. <b>Berechnen Sie die erforderliche Abstandsfläche</b> nach § 6 BbgBO (0,4 H, mind. 3 m).", "erklaerung": "<p>Abstandsflächen sichern Belichtung, Belüftung und Brandschutz zwischen Gebäuden. Die Tiefe richtet sich nach der Wandhöhe.</p><div class=\"formula\">T = 0,4 · H, mindestens 3,0 m</div>", "loesung": "<div class=\"formula\">T = 0,4 · 6,00 m = <b>2,40 m</b></div><p>Da <b>2,40 m &lt; 3,0 m</b>, greift der <b>Mindestwert 3,00 m</b> → maßgebende Abstandsfläche = <b>3,00 m</b>. Die Abstandsfläche muss auf dem <b>eigenen Grundstück</b> liegen und darf sich nicht mit anderen überdecken. (In Gewerbe-/Industriegebieten nur 0,2 H.)</p>"}, {"id": "hf3e", "group": "hf3", "deck": "HF3E", "n": 4, "typ": "v", "kennung": "HF3e-2", "tax": "Wissen", "frage": "Für welche Vorhaben ist ein <b>Zimmerermeister bauvorlageberechtigt</b> (§ 65 BbgBO)?", "erklaerung": "<p>Die Bauvorlageberechtigung erlaubt das Einreichen von Bauanträgen. Handwerksmeister haben eine eingeschränkte (kleine) Bauvorlageberechtigung.</p>", "loesung": "<ul><li>Freistehende Gebäude bis <b>100 m² Grundfläche</b>, max. <b>2 Geschosse</b>.</li><li>Gebäude <b>ohne Aufenthaltsräume</b> (Garagen, Carports, Nebengebäude) bis <b>150 m²</b>.</li><li>Wintergärten, <b>Terrassen-/Balkonüberdachungen</b> bis <b>50 m²</b>.</li><li>Bei <b>GK 1–2</b>: <b>Dachgauben</b> und <b>Änderungen an der Dachkonstruktion</b> bei Sanierung/Instandhaltung (= Zimmerer-Kerngeschäft).</li></ul><p><b>Über 100 m²</b> (z. B. typisches freistehendes EFH) → nicht mehr berechtigt → Architekt/Bauingenieur erforderlich.</p>"}, {"id": "hf3e", "group": "hf3", "deck": "HF3E", "n": 5, "typ": "v", "kennung": "HF3e-3", "tax": "Wissen", "frage": "Was bedeuten <b>GRZ und GFZ</b> im Bebauungsplan?", "erklaerung": "<p>Der Bebauungsplan steuert das Maß der baulichen Nutzung. GRZ und GFZ begrenzen, wie viel auf einem Grundstück gebaut werden darf.</p>", "loesung": "<ul><li><b>GRZ (Grundflächenzahl):</b> Anteil der Grundstücksfläche, der überbaut werden darf. GRZ 0,4 → 40 % bebaubar.</li><li><b>GFZ (Geschossflächenzahl):</b> Verhältnis der gesamten Geschossfläche zur Grundstücksfläche. GFZ 0,8 → Geschossfläche = 0,8 × Grundstück.</li></ul><p>Dazu: Firsthöhe, Dachform, Baulinien/Baugrenzen.</p>"}, {"id": "hf3e", "group": "hf3", "deck": "HF3E", "n": 6, "typ": "p", "kennung": "HF3e-3", "tax": "Können", "frage": "Ein Grundstück ist 600 m² groß, die GRZ beträgt 0,3. <b>Wie groß darf die überbaute Fläche maximal sein?</b>", "erklaerung": "<p>Die maximal überbaubare Grundfläche ist GRZ × Grundstücksfläche.</p><div class=\"formula\">A<sub>überbaut</sub> = GRZ · A<sub>Grundstück</sub></div>", "loesung": "<div class=\"formula\">A = 0,3 · 600 m² = <b>180 m²</b></div><p>Maximal 180 m² Grundfläche dürfen überbaut werden (Nebenanlagen wie Garagen ggf. mit Überschreitungsfaktor bis 0,45 nach BauNVO).</p>"}, {"id": "hf3e", "group": "hf3", "deck": "HF3E", "n": 7, "typ": "v", "kennung": "HF3e-2", "tax": "Erkennen", "frage": "Unterscheiden Sie <b>Amtlichen Lageplan (AL) und Objektbezogenen Lageplan (OBL)</b>.", "erklaerung": "<p>Für den Bauantrag werden Lagepläne benötigt. Der amtliche Teil kommt vom Vermesser, der objektbezogene vom Entwurfsverfasser.</p>", "loesung": "<ul><li><b>Amtlicher Lageplan (AL):</b> erstellt vom <b>ÖbVI</b> (öffentlich bestellter Vermessungsingenieur), M 1:200 (oft 1:500), enthält Grenzen, Höhen, Festsetzungen, Dienstbarkeiten, Bäume usw.</li><li><b>Objektbezogener Lageplan (OBL):</b> vom Architekten/Meister, zeigt die <b>Planung</b> (Gebäude, Abstände, Zufahrt) – meist auf dem AL aufbauend.</li></ul>"}, {"id": "hf3e", "group": "hf3", "deck": "HF3E", "n": 8, "typ": "v", "kennung": "HF3e-1", "tax": "Wissen", "frage": "Welche Pflichten ergeben sich aus dem <b>Denkmalschutz</b> (BbgDSchG) für Arbeiten am Baudenkmal?", "erklaerung": "<p>Eingriffe an Denkmälern sind genehmigungspflichtig. Der Eigentümer muss erhalten, jede Veränderung braucht Zustimmung.</p>", "loesung": "<ul><li><b>§ 7 BbgDSchG:</b> Erhaltungspflicht des Eigentümers.</li><li><b>§ 9 BbgDSchG:</b> <b>Genehmigungspflicht</b> für jede Veränderung am Denkmal.</li><li>Frühzeitige Abstimmung mit der <b>Unteren Denkmalschutzbehörde (UDB)</b> und ggf. dem Landesamt für Denkmalpflege.</li></ul>"}, {"id": "hf3e", "group": "hf3", "deck": "HF3E", "n": 9, "typ": "v", "kennung": "HF3e-1", "tax": "Wissen", "frage": "Welche Grundregeln und Maßnahmenstufen gelten bei der <b>Denkmal-Instandsetzung</b>?", "erklaerung": "<p>Denkmalpflege folgt dem Prinzip, so viel Original wie möglich zu erhalten und Eingriffe rückgängig machbar zu halten.</p>", "loesung": "<ul><li><b>Maßnahmenstufen:</b> Konservieren → Restaurieren → Revitalisieren/Umnutzen (so wenig Eingriff wie möglich).</li><li><b>Grundregeln:</b> <b>Reversibilität</b> (rückbaubar) und <b>Materialkompatibilität</b> (keine schädlichen Fremdmaterialien).</li><li>Holzbau: harzreiche Kiefer/Eiche statt KVH, giftfreie Verfahren, Bestands-/Befundaufnahme dokumentieren.</li></ul>"}, {"id": "hf3e", "group": "hf3", "deck": "HF3E", "n": 10, "typ": "v", "kennung": "HF3e-2", "tax": "Können", "frage": "Ordnen Sie folgende Gebäude einer <b>Gebäudeklasse</b> (§ 2 BbgBO) zu und nennen Sie die Anforderung an tragende Wände: (a) freistehendes EFH, 6 m hoch, 140 m²; (b) Wohnhaus mit 4 Wohnungen, 11 m hoch, je 90 m²; (c) freistehende Gartenlaube ohne Aufenthaltsraum, 20 m².", "erklaerung": "<p>Die Gebäudeklasse richtet sich nach der <b>Höhe</b> (= Fußbodenoberkante des höchsten Geschosses mit Aufenthaltsraum über Gelände, NICHT Firsthöhe!), der Zahl/Größe der <b>Nutzungseinheiten</b> und der Grundfläche. Aus der GK folgt die Feuerwiderstandsanforderung.</p>", "loesung": "<ul><li><b>(a)</b> ≤ 7 m, freistehend, 1 NE, ≤ 400 m² → <b>GK 1</b>. Tragende Wände: keine besondere Feuerwiderstands-Anforderung.</li><li><b>(b)</b> ≤ 13 m, Nutzungseinheiten je ≤ 400 m² → <b>GK 4</b>. Tragende Wände <b>hochfeuerhemmend (F60 / REI 60)</b> – Holzbau mit Kapselung K₂60 möglich.</li><li><b>(c)</b> Nebengebäude ohne Aufenthaltsraum, ≤ 7 m → <b>GK 1</b> (und nach § 61 verfahrensfrei).</li></ul><p>Merke: nicht die Firsthöhe zählt, sondern die <b>FOK des höchsten Aufenthaltsgeschosses</b>.</p>"}, {"id": "hf3e", "group": "hf3", "deck": "HF3E", "n": 11, "typ": "v", "kennung": "HF3e-2", "tax": "Werten", "frage": "Ein Bauherr plant in Brandenburg ein <b>fünfgeschossiges Wohnhaus (13 m hoch) in Holzbauweise</b>. Ist das zulässig, welche Gebäudeklasse liegt vor und welche brandschutztechnische Anforderung/Nachweis gilt?", "erklaerung": "<p>Seit der BbgBO-Novelle 2020 ist Holzbau nicht mehr auf niedrige Gebäudeklassen beschränkt. Entscheidend ist der Nachweis des Feuerwiderstands über Kapselung.</p>", "loesung": "<p><b>Ja, zulässig.</b> „Bauen mit Holz ist unter Maßgabe der Technischen Baubestimmungen in allen Gebäudeklassen <b>bis zur Hochhausgrenze (22 m)</b> möglich.“ Ein Gebäude mit 13 m ist <b>GK 4</b>.</p><ul><li>Anforderung tragende/aussteifende Bauteile: <b>hochfeuerhemmend (F60 / REI 60)</b>.</li><li>Nachweis über brandschutztechnisch wirksame <b>Bekleidung/Kapselung K₂60</b> (schützt das Holz 60 min) nach Holzbau-Richtlinie.</li><li>Bei <b>GK 5</b> (> 13 m bis Hochhausgrenze): <b>feuerbeständig (F90)</b>.</li></ul><p>Früher war Holz praktisch auf GK 1–3 begrenzt – das ist die zentrale Änderung für den modernen Holzbau.</p>"}, {"id": "hf3e", "group": "hf3", "deck": "HF3E", "n": 12, "typ": "v", "kennung": "HF3e-2", "tax": "Werten", "frage": "Ein Kunde bittet Sie, als <b>Zimmerermeister</b> den Bauantrag für sein <b>freistehendes Einfamilienhaus mit 130 m² Grundfläche</b> als Entwurfsverfasser einzureichen. Dürfen Sie das? Wie gehen Sie vor?", "erklaerung": "<p>§ 65 BbgBO regelt, wer Bauvorlagen als Entwurfsverfasser einreichen darf. Handwerksmeister haben nur eine eingeschränkte („kleine“) Bauvorlageberechtigung.</p>", "loesung": "<p><b>Nein.</b> Die kleine Bauvorlageberechtigung des Zimmerermeisters reicht nur für <b>freistehende Gebäude bis 100 m² Grundfläche</b> (§ 65 Abs. 1 Satz 2 Buchst. a) – 130 m² überschreiten das.</p><p><b>Vorgehen:</b> einen <b>bauvorlageberechtigten Entwurfsverfasser</b> (Architekt/in oder eingetragene/r Bauingenieur/in) für die Genehmigungsplanung hinzuziehen; du übernimmst Ausführung und Zimmererleistung.</p><p><b>Ausnahme:</b> Bei <b>GK 1–2</b> dürftest du <b>Dachgauben</b> oder <b>Änderungen an der Dachkonstruktion</b> (Sanierung/Instandhaltung) selbst einreichen (Buchst. e).</p>"}, {"id": "hf3f", "group": "hf3", "deck": "HF3F", "n": 1, "typ": "v", "kennung": "HF3f-1", "tax": "Wissen", "frage": "Ordnen Sie den <b>Planarten ihre Maßstäbe</b> zu.", "erklaerung": "<p>Je nach Detailtiefe wird ein anderer Maßstab gewählt – vom Überblick (Lageplan) bis zum 1:1-Detail.</p>", "loesung": "<table><tr><th>Planart</th><th>Maßstab</th></tr><tr><td>Lageplan</td><td>1:500 / 1:1000</td></tr><tr><td>Entwurfs-/Genehmigungsplan</td><td>1:100</td></tr><tr><td>Ausführungsplan</td><td><b>1:50</b> (Baustelle)</td></tr><tr><td>Detailzeichnung</td><td>1:20 / 1:10 / 1:5 / 1:1</td></tr></table>"}, {"id": "hf3f", "group": "hf3", "deck": "HF3F", "n": 2, "typ": "v", "kennung": "HF3f-2", "tax": "Wissen", "frage": "Welche <b>Linienarten</b> nach DIN ISO 128 gibt es und wofür stehen sie?", "erklaerung": "<p>Linienart und -breite tragen Information: Was ist geschnitten, was Kante, was verdeckt, was Achse. Korrektes Lesen/Zeichnen ist Prüfungsstoff.</p>", "loesung": "<ul><li><b>Breite Volllinie:</b> Schnittkanten, sichtbare Hauptkanten im Schnitt.</li><li><b>Schmale Volllinie:</b> sichtbare Kanten, Maßlinien, Schraffuren.</li><li><b>Strichlinie:</b> verdeckte (nicht sichtbare) Kanten.</li><li><b>Strichpunktlinie:</b> Achsen, Symmetrielinien, Schnittebene.</li><li><b>Punktlinie:</b> Teile vor der Schnittebene.</li></ul><p>Linienbreiten-Verhältnis ca. 1 : 2 : 4 (schmal : breit : sehr breit).</p>"}, {"id": "hf3f", "group": "hf3", "deck": "HF3F", "n": 3, "typ": "v", "kennung": "HF3f-2", "tax": "Wissen", "frage": "Wie wird <b>Holz in Schnittzeichnungen schraffiert</b>?", "erklaerung": "<p>Die Schraffur zeigt das Material und die Schnittrichtung relativ zur Faser.</p>", "loesung": "<ul><li><b>Quer zur Faser geschnitten (Hirnholz):</b> diagonales Kreuz mit Kreissegment/Jahrringandeutung.</li><li><b>Längs zur Faser geschnitten:</b> geschwungene, parallele Linien (Faserverlauf).</li></ul><p>So erkennt man im Plan sofort, ob ein Balken längs oder quer getroffen ist.</p>"}, {"id": "hf3f", "group": "hf3", "deck": "HF3F", "n": 4, "typ": "v", "kennung": "HF3f-2", "tax": "Wissen", "frage": "Auf welcher Höhe wird ein <b>Grundriss</b> geschnitten und was zeigt er?", "erklaerung": "<p>Der Grundriss ist ein waagerechter Schnitt durch das Geschoss, von oben betrachtet.</p>", "loesung": "<p>Der Schnitt liegt etwa <b>1,00 m über dem Fertigfußboden</b> (so werden Fenster und Türen geschnitten dargestellt). Der Grundriss zeigt Wände (geschnitten = breite Linie), Öffnungen, Maße, Bauteile und Einrichtungen in Draufsicht.</p>"}, {"id": "hf3f", "group": "hf3", "deck": "HF3F", "n": 5, "typ": "v", "kennung": "HF3f-2", "tax": "Wissen", "frage": "Unterscheiden Sie <b>Querschnitt und Längsschnitt</b> und wie die Blickrichtung gekennzeichnet wird.", "erklaerung": "<p>Schnitte zeigen die vertikale Struktur des Gebäudes. Die Schnittebene und Blickrichtung müssen im Grundriss angegeben sein.</p>", "loesung": "<ul><li><b>Querschnitt:</b> Schnitt <b>quer zum First</b> (zeigt Dachneigung, Sparren, Geschosshöhen).</li><li><b>Längsschnitt:</b> Schnitt <b>parallel zum First</b>.</li><li><b>Kennzeichnung:</b> Schnittebene als Strichpunktlinie mit <b>Pfeilen für die Blickrichtung</b> und Bezeichnung (A–A, B–B).</li></ul>"}, {"id": "hf3f", "group": "hf3", "deck": "HF3F", "n": 6, "typ": "v", "kennung": "HF3f-2", "tax": "Wissen", "frage": "Nennen Sie die wichtigsten <b>Bemaßungsregeln</b> in Bauzeichnungen.", "erklaerung": "<p>Maße müssen eindeutig und einheitlich angetragen werden, damit auf der Baustelle keine Verwechslung entsteht.</p>", "loesung": "<ul><li>Maße <b>≥ 1,00 m in Metern</b> (z. B. 2,45), <b>&lt; 1,00 m in cm</b> (z. B. 92).</li><li>Maßzahlen lesbar <b>von unten oder von rechts</b>.</li><li><b>Fenster/Türen:</b> Breite <b>über</b>, Höhe <b>unter</b> der Maßlinie; <b>Brüstungshöhe (BRH)</b> angeben.</li><li>Maßketten: Einzelmaße + Gesamtmaß, keine doppelten Maße.</li></ul>"}, {"id": "hf3f", "group": "hf3", "deck": "HF3F", "n": 7, "typ": "v", "kennung": "HF3f-2", "tax": "Wissen", "frage": "Was ist das <b>Baurichtmaß / der Achtelmeter</b> in der Maßordnung im Hochbau?", "erklaerung": "<p>Damit Bauteile zusammenpassen, basiert die Maßordnung auf einem Grundraster.</p>", "loesung": "<p>Das <b>Baurichtmaß</b> beruht auf dem <b>Achtelmeter-Raster = 12,5 cm</b> (1 M = 1/8 m). Vielfache davon (25, 37,5, 50 cm …) erleichtern die Abstimmung von Bauteilen, Rastern und Vorgewerken (Modulkoordination).</p>"}, {"id": "hf3f", "group": "hf3", "deck": "HF3F", "n": 8, "typ": "v", "kennung": "HF3f-2", "tax": "Wissen", "frage": "Was ist ein <b>statisches Modell</b> und welche Lastarten werden angesetzt?", "erklaerung": "<p>Für die Berechnung wird das reale Tragwerk idealisiert (Auflager, Stäbe). Die Lasten werden nach Art unterschieden.</p>", "loesung": "<ul><li><b>Statisches Modell:</b> Idealisierung als Einfeldträger, Durchlaufträger, Kragträger, Rahmen, Gelenke/Auflager.</li><li><b>Ständige Lasten (g):</b> Eigengewicht Holz, Deckung, Ausbau.</li><li><b>Veränderliche Lasten (q):</b> Schnee, Wind, Nutzlast/Personen.</li></ul><p>Aus dem Modell folgen Schnittgrößen (M, V, N) für die Bemessung.</p>"}, {"id": "hf3f", "group": "hf3", "deck": "HF3F", "n": 9, "typ": "v", "kennung": "HF3f-3", "tax": "Wissen", "frage": "Wie ist ein <b>Bau-Protokoll/Bericht</b> aufgebaut?", "erklaerung": "<p>Protokolle sichern Vereinbarungen und Feststellungen beweiskräftig. Eine klare Struktur ist Pflicht.</p>", "loesung": "<ul><li><b>Kopf:</b> Datum, Ort, Projekt, Beteiligte/Anwesende.</li><li><b>Inhalt:</b> Feststellungen, Beschlüsse/Maßnahmen, Verantwortliche, <b>Fristen</b>.</li><li><b>Abschluss:</b> nächster Termin, <b>Unterschriften</b>.</li></ul><p>Sachlich, eindeutig, nachvollziehbar (z. B. Bautagebuch, Abnahme-, Baubesprechungsprotokoll).</p>"}, {"id": "hf3g", "group": "hf3", "deck": "HF3G", "n": 1, "typ": "v", "kennung": "HF3g-1", "tax": "Wissen", "frage": "Nennen Sie wichtige <b>stationäre und handgeführte Maschinen</b> der Zimmerei und ihre Einsatzbereiche.", "erklaerung": "<p>Die Maschinenwahl bestimmt Qualität, Tempo und Sicherheit. Jede Maschine hat ihren Einsatzbereich und ihre Schutzregeln.</p>", "loesung": "<ul><li><b>Tisch-/Format-Kreissäge:</b> gerade Schnitte, Ablängen, Besäumen.</li><li><b>Abrichthobel:</b> ebene/winklige Bezugsfläche erzeugen.</li><li><b>Dickenhobel:</b> auf Maßdicke hobeln.</li><li><b>Kettensäge / Kettenstemmer:</b> Ablängen, Zapfenlöcher, Abbund.</li><li><b>Oberfräse/Kettenfräse:</b> Nuten, Verbindungen.</li></ul><p>Sicherheit: Schutzhauben, Spaltkeil, Schiebestock, PSA, Unterweisung.</p>"}, {"id": "hf3g", "group": "hf3", "deck": "HF3G", "n": 2, "typ": "p", "kennung": "HF3g-1", "tax": "Können", "frage": "Berechnen Sie den <b>Maschinenstundensatz</b> einer Hobelmaschine: Anschaffung 24 000 €, Nutzungsdauer 8 Jahre, 1 000 Bh/Jahr, Reparatur+Betriebsstoffe 4,50 €/h, Zins 6 % auf halben Wert.", "erklaerung": "<p>Der Maschinenstundensatz fasst Abschreibung, kalkulatorische Zinsen und laufende Kosten je Betriebsstunde zusammen.</p><div class=\"formula\">Satz = (AfA + Zins)/Bh + Reparatur + Betriebsstoffe</div>", "loesung": "<p><b>AfA/Jahr:</b> 24 000/8 = 3 000 € → /1000 = 3,00 €/h</p><p><b>Zins/Jahr:</b> 6 % · 12 000 = 720 € → /1000 = 0,72 €/h</p><p><b>Reparatur/Betriebsstoffe:</b> 4,50 €/h</p><div class=\"formula\">Satz = 3,00 + 0,72 + 4,50 = <b>8,22 €/h</b></div>"}, {"id": "hf3g", "group": "hf3", "deck": "HF3G", "n": 3, "typ": "v", "kennung": "HF3g-1", "tax": "Werten", "frage": "Welche <b>Hebezeuge</b> kommen im Holzbau zum Einsatz und wo liegen ihre Grenzen?", "erklaerung": "<p>Großbauteile (Binder, Wandelemente) müssen sicher gehoben werden. Die Wahl hängt von Gewicht, Reichweite und Standort ab.</p>", "loesung": "<ul><li><b>Mobil-/Autokran:</b> hohe Lasten/Reichweite; Traglast sinkt mit Ausladung (Lastdiagramm!), Aufstellfläche/Abstützung nötig.</li><li><b>Turmdrehkran:</b> für längere Bauzeiten.</li><li><b>Teleskoplader:</b> flexibel für Material/Montage in mittlerer Höhe.</li></ul><p>Grenzen: <b>Traglast bei Ausladung</b>, Standsicherheit, Freileitungen, Bodenpressung.</p>"}, {"id": "hf3g", "group": "hf3", "deck": "HF3G", "n": 4, "typ": "v", "kennung": "HF3g-2", "tax": "Wissen", "frage": "Bis zu welcher Höhe ist ein <b>Gerüst nach ATV DIN 18334 Nebenleistung</b>, und wann wird es Besondere Leistung?", "erklaerung": "<p>Die ATV regelt, welcher Gerüstaufwand im Einheitspreis steckt und welcher gesondert zu vergüten ist – wichtig für die Kalkulation.</p>", "loesung": "<ul><li><b>Nebenleistung</b> (im EP enthalten): Arbeits-/Schutzgerüste bis <b>3,50 m Arbeitshöhe</b> (seit 2016; früher 2,0 m).</li><li><b>Besondere Leistung</b> (gesondert zu vergüten): Gerüste <b>über 3,50 m</b> Arbeitshöhe oder bei <b>Dachneigung &gt; 22,5°</b> (Dachfanggerüst) und besondere Schutzmaßnahmen.</li></ul>"}, {"id": "hf3g", "group": "hf3", "deck": "HF3G", "n": 5, "typ": "v", "kennung": "HF3g-2", "tax": "Erkennen", "frage": "Unterscheiden Sie <b>Arbeitsgerüst und Schutzgerüst</b>.", "erklaerung": "<p>Gerüste dienen entweder als Arbeitsplattform oder dem Schutz vor Absturz/herabfallenden Teilen – das bestimmt Bauart und Anforderungen.</p>", "loesung": "<ul><li><b>Arbeitsgerüst:</b> bietet Standfläche und Materialablage zum Arbeiten (Lastklasse nach DIN EN 12811).</li><li><b>Schutzgerüst:</b> sichert Personen/Bereiche – <b>Fanggerüst</b> (fängt Absturz), <b>Dachfanggerüst</b> (an Traufe), <b>Schutzdach</b> (für Passanten).</li></ul>"}, {"id": "hf3g", "group": "hf3", "deck": "HF3G", "n": 6, "typ": "p", "kennung": "HF3g-1", "tax": "Werten", "frage": "Wie entscheidet man <b>Eigengerüst oder Fremdgerüst</b> wirtschaftlich?", "erklaerung": "<p>Gerüst kann selbst vorgehalten oder gemietet werden. Die Entscheidung hängt von Auslastung und Kapitalbindung ab.</p>", "loesung": "<ul><li><b>Eigengerüst:</b> lohnt bei <b>hoher Auslastung</b>/häufigem Einsatz; aber Kapitalbindung, Lager, Wartung, Transport, Prüfpflichten.</li><li><b>Fremdgerüst (Miete):</b> bei seltenem Einsatz oder Spitzen; planbare Kosten, kein Kapital, aber höherer Stückpreis.</li><li>Faustregel: Vergleich Vorhaltekosten/Jahr (Eigen) ↔ Mietkosten × Einsätze; Break-even über Auslastung.</li></ul>"}, {"id": "hf3g", "group": "hf3", "deck": "HF3G", "n": 7, "typ": "v", "kennung": "HF3g-2", "tax": "Wissen", "frage": "Welche Sicherheitsregeln regelt <b>DIN 4420 / DGUV</b> für Gerüste?", "erklaerung": "<p>Gerüste sind Hauptunfallquelle. Normen und DGUV-Vorschriften geben Lastklassen, Maße und Absturzsicherung vor.</p>", "loesung": "<ul><li><b>Lastklassen</b> (DIN EN 12811/4420): Zimmerarbeiten i. d. R. Klasse 3 (2,0 kN/m²).</li><li><b>Belagbreite</b> ≥ 60–90 cm; Wandabstand ≤ 30 cm.</li><li><b>Absturzsicherung</b> ab 2,0 m: dreiteiliger Seitenschutz.</li><li>Auf-/Abbau nur durch Unterwiesene; Prüfung und Kennzeichnung/Freigabe.</li></ul>"}, {"id": "hf3g", "group": "hf3", "deck": "HF3G", "n": 8, "typ": "v", "kennung": "HF3g-1", "tax": "Wissen", "frage": "Welche <b>Sicherheitsregeln</b> gelten an der stationären Tischkreissäge?", "erklaerung": "<p>Die Kreissäge ist eine der gefährlichsten Maschinen. Schutzeinrichtungen und Verhalten sind klar vorgeschrieben.</p>", "loesung": "<ul><li><b>Spaltkeil</b> und <b>Schutzhaube</b> verwenden (gegen Rückschlag).</li><li><b>Schiebestock</b> bei schmalen Werkstücken / Nähe zum Blatt.</li><li>Nicht über das laufende Blatt greifen; kein Bremsen von Hand.</li><li>PSA (eng anliegende Kleidung, Gehörschutz), Absaugung; Maschine warten/prüfen.</li></ul>"}, {"id": "hf3h", "group": "hf3", "deck": "HF3H", "n": 1, "typ": "v", "kennung": "HF3h-1", "tax": "Wissen", "frage": "Welche <b>Pflichtinhalte</b> gehören in einen Subunternehmer-/Nachunternehmervertrag?", "erklaerung": "<p>Ein klarer Vertrag verhindert Streit über Umfang, Geld und Haftung. Bestimmte Punkte sollten immer geregelt sein.</p>", "loesung": "<ul><li><b>Leistungsumfang</b> (eindeutiges LV, Schnittstellen).</li><li><b>Vergütung</b> und Zahlungsmodalitäten.</li><li><b>Termine</b>/Bauzeit, Vertragsstrafen.</li><li><b>Mängelhaftung/Gewährleistung</b>, Sicherheiten.</li><li>Geltung der VOB/B, Versicherung, Mindestlohn-Nachweise.</li></ul>"}, {"id": "hf3h", "group": "hf3", "deck": "HF3H", "n": 2, "typ": "v", "kennung": "HF3h-1", "tax": "Werten", "frage": "Wie ist die <b>Haftung</b> geregelt, wenn ein Subunternehmer Mängel verursacht?", "erklaerung": "<p>Gegenüber dem Bauherrn tritt der Hauptunternehmer als Vertragspartner auf – er steht für das Gesamtwerk gerade.</p>", "loesung": "<ul><li>Der <b>Hauptunternehmer haftet dem Auftraggeber</b> für die gesamte Leistung, auch für die seiner Subunternehmer (Erfüllungsgehilfe).</li><li>Intern kann er beim <b>Subunternehmer Regress</b> nehmen (Rückgriff).</li><li>Deshalb: <b>eigene Abnahme</b> der Subleistung vor Weiterberechnung an den AG.</li></ul>"}, {"id": "hf3h", "group": "hf3", "deck": "HF3H", "n": 3, "typ": "v", "kennung": "HF3h-2", "tax": "Wissen", "frage": "Wann muss ein <b>SiGeKo</b> bestellt werden (BaustellV)?", "erklaerung": "<p>Arbeiten auf einer Baustelle mehrere Arbeitgeber, muss die Sicherheit koordiniert werden. Die Baustellenverordnung regelt das.</p>", "loesung": "<ul><li>Ein <b>Sicherheits- und Gesundheitsschutzkoordinator (SiGeKo)</b> ist zu bestellen, wenn auf der Baustelle <b>Beschäftigte mehrerer Arbeitgeber</b> tätig werden.</li><li>Bei größeren Baustellen zusätzlich <b>Vorankündigung</b> an die Behörde und <b>SiGe-Plan</b> (Schwellenwerte: z. B. &gt; 30 Arbeitstage und &gt; 20 Beschäftigte gleichzeitig, oder &gt; 500 Personentage).</li><li>Verantwortlich für die Bestellung ist der <b>Bauherr</b>.</li></ul>"}, {"id": "hf3h", "group": "hf3", "deck": "HF3H", "n": 4, "typ": "v", "kennung": "HF3h-1", "tax": "Wissen", "frage": "Was schreibt <b>VOB/B § 4 Abs. 8</b> zur Vergabe an Nachunternehmer vor?", "erklaerung": "<p>Der Auftraggeber hat ein Interesse daran zu wissen, wer tatsächlich baut. Deshalb ist die Weitervergabe an Bedingungen geknüpft.</p>", "loesung": "<ul><li>Der Auftragnehmer hat die Leistung grundsätzlich <b>im eigenen Betrieb</b> auszuführen.</li><li>Weitervergabe an Nachunternehmer nur mit <b>Zustimmung des Auftraggebers</b> (besonders bei Leistungen, auf die der Betrieb eingerichtet ist).</li><li>Der AN bleibt voll verantwortlich.</li></ul>"}, {"id": "hf3h", "group": "hf3", "deck": "HF3H", "n": 5, "typ": "v", "kennung": "HF3h-2", "tax": "Werten", "frage": "Warum ist die <b>eigene Abnahme der Subunternehmerleistung</b> zwingend?", "erklaerung": "<p>Bevor der Hauptunternehmer eine Subleistung an den Bauherrn weitergibt, sollte er sie selbst prüfen und abnehmen.</p>", "loesung": "<ul><li>Feststellung von Mängeln <b>vor</b> der Weiterberechnung/Hauptabnahme.</li><li>Beweissicherung und Start der <b>eigenen Gewährleistungsfrist</b> gegenüber dem Sub.</li><li>Schutz vor Haftung gegenüber dem AG für fremde Mängel.</li><li>Mängelprotokoll, Fristsetzung zur Nacherfüllung.</li></ul>"}, {"id": "hf3h", "group": "hf3", "deck": "HF3H", "n": 6, "typ": "v", "kennung": "HF3h-2", "tax": "Können", "frage": "Was ist bei der <b>Terminkoordination</b> und der Behinderungsanzeige (VOB/B § 6) zu beachten?", "erklaerung": "<p>Mehrere Gewerke müssen zeitlich ineinandergreifen. Verzögerungen sind sofort anzuzeigen, um Ansprüche zu sichern.</p>", "loesung": "<ul><li><b>Bauzeitenplan/Meilensteine</b> abstimmen, Schnittstellen klären.</li><li>Bei Behinderung (z. B. Vorgewerk nicht fertig): <b>unverzüglich schriftlich</b> Behinderungsanzeige an den AG.</li><li>Ohne Anzeige: kein Anspruch auf Bauzeitverlängerung/Mehrkosten.</li></ul>"}, {"id": "hf3h", "group": "hf3", "deck": "HF3H", "n": 7, "typ": "v", "kennung": "HF3h-2", "tax": "Wissen", "frage": "Welche <b>Koordinationspflicht</b> ergibt sich aus ArbSchG § 8 bei Zusammenarbeit mehrerer Betriebe?", "erklaerung": "<p>Wenn mehrere Firmen am selben Ort arbeiten, können sich Gefährdungen gegenseitig verstärken. Das Gesetz verlangt Zusammenarbeit.</p>", "loesung": "<ul><li>Die Arbeitgeber müssen sich bei der Arbeitssicherheit <b>abstimmen</b> und gegenseitig über Gefahren <b>informieren</b>.</li><li>Maßnahmen koordinieren (z. B. gemeinsame Gerüst-/Krannutzung, Sperrbereiche).</li><li>Ergänzt durch die SiGeKo-Koordination nach BaustellV.</li></ul>"}, {"id": "hf3h", "group": "hf3", "deck": "HF3H", "n": 8, "typ": "p", "kennung": "HF3h-1", "tax": "Werten", "frage": "Ein Nachunternehmer (Dachdecker) verursacht einen Wasserschaden. Der Bauherr verlangt vom Zimmerer (Hauptunternehmer) Beseitigung. <b>Beurteilen Sie die Lage.</b>", "erklaerung": "<p>Typische Haftungsfrage: Wer steht gegenüber wem ein, und wer trägt am Ende die Kosten?</p>", "loesung": "<ul><li>Gegenüber dem <b>Bauherrn</b> haftet der <b>Hauptunternehmer</b> (Zimmerer) – er muss den Mangel beseitigen/beseitigen lassen.</li><li><b>Intern</b> nimmt der Hauptunternehmer beim Nachunternehmer <b>Regress</b> (Schadensersatz/Nacherfüllung), da dieser den Mangel verursacht hat.</li><li>Voraussetzung für sauberen Regress: dokumentierte eigene Abnahme, Mängelprotokoll, klarer Subvertrag.</li></ul>"}, {"id": "hf3i", "group": "hf3", "deck": "HF3I", "n": 1, "typ": "v", "kennung": "HF3i-1", "tax": "Wissen", "frage": "Welche <b>Übermessungsregeln</b> gelten nach ATV DIN 18334 für das Aufmaß?", "erklaerung": "<p>Beim Aufmaß werden kleine Öffnungen aus Vereinfachungsgründen „übermessen\" (nicht abgezogen). Das ist eine der häufigsten Rechenfallen.</p>", "loesung": "<ul><li><b>Wände/Decken/Dächer (Flächen):</b> Öffnungen bis <b>2,5 m²</b> Einzelfläche werden übermessen (nicht abgezogen).</li><li><b>Böden:</b> Öffnungen bis <b>0,5 m²</b> übermessen.</li><li><b>Längenmaße:</b> Unterbrechungen bis <b>1 m</b> Einzellänge übermessen.</li><li>Öffnungen <b>&gt; 2,5 m²</b>: abziehen, Leibungen ggf. gesondert berechnen.</li></ul>"}, {"id": "hf3i", "group": "hf3", "deck": "HF3I", "n": 2, "typ": "p", "kennung": "HF3i-1", "tax": "Können", "frage": "Eine Dachfläche misst 10,0 m × 6,0 m und enthält 2 Dachfenster à 1,2 m² sowie 1 Gaube-Öffnung von 3,0 m². <b>Berechnen Sie die abzurechnende Fläche</b> nach Übermessungsregel.", "erklaerung": "<p>Kleine Öffnungen (≤ 2,5 m²) werden übermessen, größere abgezogen. Erst Bruttofläche, dann nur die großen Öffnungen abziehen.</p>", "loesung": "<p><b>Bruttofläche:</b> 10,0 · 6,0 = 60,0 m²</p><ul><li>Dachfenster 1,2 m² (≤ 2,5) → <b>übermessen</b> (kein Abzug), beide.</li><li>Gaube 3,0 m² (&gt; 2,5) → <b>abziehen</b>.</li></ul><div class=\"formula\">A = 60,0 − 3,0 = <b>57,0 m²</b></div>"}, {"id": "hf3i", "group": "hf3", "deck": "HF3I", "n": 3, "typ": "v", "kennung": "HF3i-2", "tax": "Erkennen", "frage": "Unterscheiden Sie <b>Vor- und Nachkalkulation</b>.", "erklaerung": "<p>Die Vorkalkulation legt den Angebotspreis fest, die Nachkalkulation prüft nach Fertigstellung, ob er gestimmt hat – Basis für künftige Angebote.</p>", "loesung": "<ul><li><b>Vorkalkulation:</b> vor Ausführung – Einheitspreise aus geplanten Lohn-, Material-, Gerätekosten; Grundlage des Angebots.</li><li><b>Nachkalkulation:</b> nach Ausführung – <b>tatsächliche</b> Kosten erfassen und mit der Vorkalkulation vergleichen.</li><li><b>Soll-Ist-Abweichungen</b> analysieren (Stundenverbrauch, Materialpreise) → bessere künftige Kalkulation, Controlling.</li></ul>"}, {"id": "hf3i", "group": "hf3", "deck": "HF3I", "n": 4, "typ": "v", "kennung": "HF3i-4", "tax": "Wissen", "frage": "Was sind <b>Abschlagszahlungen</b> und worauf stützt sich der Anspruch?", "erklaerung": "<p>Damit der Unternehmer nicht den ganzen Auftrag vorfinanziert, kann er für erbrachte Teilleistungen Zwischenzahlungen verlangen.</p>", "loesung": "<ul><li><b>§ 632a BGB</b> bzw. <b>VOB/B § 16</b>: Anspruch auf Abschlagszahlungen für nachgewiesene, vertragsgemäße Teilleistungen.</li><li>Nachweis durch <b>prüfbare Aufstellung</b> (Aufmaß).</li><li>VOB/B: Abschlag <b>fällig binnen 21 Tagen</b> nach Zugang der prüfbaren Rechnung.</li></ul>"}, {"id": "hf3i", "group": "hf3", "deck": "HF3I", "n": 5, "typ": "v", "kennung": "HF3i-4", "tax": "Wissen", "frage": "Welche <b>Fristen</b> gelten für die Schlussrechnung nach VOB/B § 14?", "erklaerung": "<p>Damit abgerechnet werden kann, muss die Schlussrechnung prüfbar und fristgerecht eingereicht werden.</p>", "loesung": "<ul><li>Schlussrechnung <b>prüfbar</b> aufstellen (Mengen, EP, Aufmaß, Nachträge).</li><li>Einreichung i. d. R. binnen <b>12 Werktagen</b> nach Fertigstellung (bei kurzer Bauzeit), bei längerer Bauzeit entsprechend länger.</li><li>Fälligkeit der Schlusszahlung nach <b>Prüfung</b> (VOB/B § 16 Abs. 3: i. d. R. 30 Tage).</li></ul>"}, {"id": "hf3i", "group": "hf3", "deck": "HF3I", "n": 6, "typ": "v", "kennung": "HF3i-4", "tax": "Wissen", "frage": "Wann wird die <b>Vergütung fällig</b> (§ 641 BGB)?", "erklaerung": "<p>Das BGB knüpft die Fälligkeit der Vergütung an die Abnahme – erst dann muss der Besteller zahlen.</p>", "loesung": "<p>Die Vergütung ist <b>mit der Abnahme</b> des Werks fällig (§ 641 BGB). Bei Teilabnahmen entsprechend für die abgenommenen Teile. Abschlagszahlungen (§ 632a) sind davon unabhängig schon vorher möglich.</p>"}, {"id": "hf3i", "group": "hf3", "deck": "HF3I", "n": 7, "typ": "v", "kennung": "HF3i-3", "tax": "Wissen", "frage": "Was versteht man unter <b>Nachtragsmanagement</b>?", "erklaerung": "<p>Ändert sich während der Bauausführung der Leistungsumfang, muss das dokumentiert und vergütet werden – sonst bleibt der Unternehmer auf Mehrkosten sitzen.</p>", "loesung": "<ul><li><b>Mehr-/Minderleistungen</b> und geänderte Leistungen erkennen und <b>vor Ausführung schriftlich ankündigen</b>.</li><li>Nachtragsangebot mit Begründung (geänderte/zusätzliche Leistung) erstellen.</li><li>Grundlage: VOB/B § 2 (Mengenänderung, geänderte/zusätzliche Leistung) bzw. BGB § 650b/c (Anordnungsrecht, Vergütungsanpassung).</li></ul>"}, {"id": "hf3i", "group": "hf3", "deck": "HF3I", "n": 8, "typ": "v", "kennung": "HF3i-4", "tax": "Erkennen", "frage": "Unterscheiden Sie <b>Einheitspreis-, Pauschalpreis- und Regievertrag</b>.", "erklaerung": "<p>Je nach Vertragsart wird anders abgerechnet – das beeinflusst Risiko und Aufwand für beide Seiten.</p>", "loesung": "<table><tr><th>Art</th><th>Abrechnung</th></tr><tr><td><b>Einheitspreis</b></td><td>EP × tatsächliche Menge (Aufmaß) – Mengenrisiko beim AG</td></tr><tr><td><b>Pauschalpreis</b></td><td>Festpreis für definierte Leistung – Risiko beim AN</td></tr><tr><td><b>Regie (Stundenlohn)</b></td><td>nach tatsächlichem Aufwand (Std. + Material) – für kleine/unklare Arbeiten</td></tr></table>"}, {"id": "hf3i", "group": "hf3", "deck": "HF3I", "n": 9, "typ": "p", "kennung": "HF3i-4", "tax": "Können", "frage": "Erstellen Sie eine vereinfachte <b>Schlussrechnung</b>: Pos. A 57 m² à 30,50 €; Pos. B 12 Stk à 85,00 €; bereits geleistete Abschläge 1 500 €; 19 % MwSt.", "erklaerung": "<p>Die Schlussrechnung summiert alle Positionen (EP × Menge), schlägt MwSt auf und zieht geleistete Abschläge ab → Restzahlung.</p>", "loesung": "<p><b>Positionen (netto):</b></p><div class=\"formula\">A: 57 · 30,50 = 1 738,50 €<br>B: 12 · 85,00 = 1 020,00 €<br>Summe netto = 2 758,50 €</div><p><b>+ 19 % MwSt:</b></p><div class=\"formula\">2 758,50 · 1,19 = 3 282,62 € (brutto)</div><p><b>− Abschläge 1 500 €:</b></p><div class=\"formula\">Restzahlung = 3 282,62 − 1 500,00 = <b>1 782,62 €</b></div>"}, {"id": "hf4a", "group": "hf4", "deck": "HF4A", "n": 1, "typ": "v", "kennung": "HF4a-1", "tax": "Wissen", "frage": "Erklären Sie die <b>vertikale Gliederung der Zuschlagskalkulation</b> von den Einzelkosten bis zum Angebotspreis.", "erklaerung": "<p>Die Zuschlagskalkulation ist das Standardverfahren im Zimmererhandwerk. Sie baut den Preis stufenweise aus den Einzelkosten plus Zuschlägen auf.</p>", "loesung": "<ol><li><b>Einzelkosten der Teilleistungen:</b> Lohn + Material + Geräte + Nachunternehmer.</li><li>+ Baustellengemeinkosten = <b>Herstellkosten</b>.</li><li>+ Allgemeine Geschäftskosten = <b>Selbstkosten</b>.</li><li>+ <b>Wagnis & Gewinn</b> = Netto-Angebotspreis.</li><li>+ MwSt = Bruttoangebotspreis.</li></ol>"}, {"id": "hf4a", "group": "hf4", "deck": "HF4A", "n": 2, "typ": "p", "kennung": "HF4a-3", "tax": "Können", "frage": "Berechnen Sie den <b>Stundenverrechnungssatz</b>: Mittellohn 21,50 €/h, Lohnzusatzkosten 82 %, Gemeinkosten 90 % (auf Kalkulationslohn), Wagnis & Gewinn 7 %.", "erklaerung": "<p>Der Verrechnungssatz wird stufenweise aus dem Mittellohn aufgebaut: erst Lohnzusatzkosten, dann Gemeinkosten, dann W&G.</p>", "loesung": "<p><b>Kalkulationslohn:</b> 21,50 · 1,82 = 39,13 €/h</p><p><b>+ Gemeinkosten 90 %:</b> 39,13 · 1,90 = 74,35 €/h</p><p><b>+ W&G 7 %:</b></p><div class=\"formula\">74,35 · 1,07 = <b>79,55 €/h</b> (netto)</div>"}, {"id": "hf4a", "group": "hf4", "deck": "HF4A", "n": 3, "typ": "v", "kennung": "HF4a-1", "tax": "Wissen", "frage": "Unterscheiden Sie <b>Mittellohn A und Mittellohn AP</b>.", "erklaerung": "<p>Der Mittellohn ist der durchschnittliche Stundenlohn der eingesetzten Arbeitskräfte. Je nachdem, ob Aufsicht einbezogen wird, spricht man von A oder AP.</p>", "loesung": "<ul><li><b>Mittellohn A:</b> Durchschnitt nur der <b>produktiven gewerblichen</b> Arbeitskräfte (Facharbeiter, Helfer).</li><li><b>Mittellohn AP:</b> A <b>+ Aufsichtsanteile</b> (Polier, Meister) anteilig eingerechnet.</li></ul><p>Für die Kalkulation wird meist der AP-Lohn verwendet, da Aufsicht mitfinanziert werden muss.</p>"}, {"id": "hf4a", "group": "hf4", "deck": "HF4A", "n": 4, "typ": "v", "kennung": "HF4a-1", "tax": "Wissen", "frage": "Welche <b>Kostenarten</b> unterscheidet man in der Baukalkulation?", "erklaerung": "<p>Kosten werden nach Herkunft gegliedert. Diese Trennung ist Grundlage für eine saubere Kalkulation.</p>", "loesung": "<ul><li><b>Lohnkosten:</b> Tariflohn + Bauzuschlag + Soziallöhne.</li><li><b>Materialkosten:</b> Einkauf frei Baustelle + Verschnitt + Materialgemeinkosten.</li><li><b>Gerätekosten:</b> Vorhaltekosten (Abschreibung, Verzinsung, Reparatur).</li><li><b>Gemeinkosten:</b> Baustellen- + allgemeine Geschäftskosten.</li><li><b>Sonderkosten / Nachunternehmer.</b></li></ul>"}, {"id": "hf4a", "group": "hf4", "deck": "HF4A", "n": 5, "typ": "p", "kennung": "HF4a-2", "tax": "Können", "frage": "Berechnen Sie die <b>Materialkosten</b> für 0,90 m³ Bauholz: Einkaufspreis 420 €/m³, Verschnitt 1,5 %, Materialgemeinkosten 10 %.", "erklaerung": "<p>Auf den Einkaufspreis kommen Verschnitt und Materialgemeinkosten (Lager, Handling) – so entstehen die kalkulatorischen Materialkosten.</p><div class=\"formula\">K = Menge · EK · (1 + Verschnitt) · (1 + MGK)</div>", "loesung": "<p><b>Materialwert:</b> 0,90 · 420 = 378,00 €</p><p><b>+ Verschnitt 1,5 %:</b> 378,00 · 1,015 = 383,67 €</p><p><b>+ Materialgemeinkosten 10 %:</b></p><div class=\"formula\">383,67 · 1,10 = <b>422,04 €</b></div>"}, {"id": "hf4a", "group": "hf4", "deck": "HF4A", "n": 6, "typ": "v", "kennung": "HF4a-1", "tax": "Wissen", "frage": "Unterscheiden Sie <b>Lohnzusatzkosten und Lohnnebenkosten</b>.", "erklaerung": "<p>Beide erhöhen die reinen Lohnkosten, haben aber unterschiedliche Ursachen – ein häufiger Prüfungsbegriff.</p>", "loesung": "<ul><li><b>Lohnzusatzkosten (≈ 81–82,5 %):</b> gesetzliche/tarifliche Sozialaufwendungen – Sozialversicherungs-Arbeitgeberanteile, bezahlter Urlaub, Lohnfortzahlung, Zusatzversorgung (SOKA-BAU).</li><li><b>Lohnnebenkosten:</b> auftrags-/baustellenbezogene Kosten wie <b>Fahrtkosten, Auslösung, Verpflegungszuschüsse</b>, Wegezeit.</li></ul>"}, {"id": "hf4a", "group": "hf4", "deck": "HF4A", "n": 7, "typ": "p", "kennung": "HF4a-3", "tax": "Können", "frage": "Ermitteln Sie den <b>Einheitspreis</b> einer Position: Material 18,00 €/Stk, Zeitaufwand 0,40 h/Stk, Stundensatz 79,55 €/h.", "erklaerung": "<p>Der Einheitspreis ist die Summe aus Materialkosten je Einheit und Lohnkosten (Zeit × Verrechnungssatz).</p><div class=\"formula\">EP = Material + Zeit · Stundensatz</div>", "loesung": "<p><b>Lohnanteil:</b> 0,40 · 79,55 = 31,82 €/Stk</p><div class=\"formula\">EP = 18,00 + 31,82 = <b>49,82 €/Stk</b> (netto)</div>"}, {"id": "hf4a", "group": "hf4", "deck": "HF4A", "n": 8, "typ": "v", "kennung": "HF4a-4", "tax": "Werten", "frage": "Welchen Einfluss hat der <b>Beschäftigungsgrad</b> auf die Gemeinkostenbelastung?", "erklaerung": "<p>Fixe Gemeinkosten (Miete, Verwaltung) fallen unabhängig von der Auslastung an. Wie sie pro Stunde belasten, hängt von der Beschäftigung ab.</p>", "loesung": "<p>Je <b>höher die Auslastung</b> (mehr produktive Stunden), desto <b>geringer</b> die anteilige Gemeinkostenbelastung pro Stunde – die Fixkosten verteilen sich auf mehr Stunden. Bei Unterauslastung steigt der Gemeinkostenzuschlag, der Stundensatz muss höher kalkuliert werden (sonst Verlust). → Auslastung ist ein zentraler Hebel für die Wirtschaftlichkeit.</p>"}, {"id": "hf4a", "group": "hf4", "deck": "HF4A", "n": 9, "typ": "p", "kennung": "HF4a-3", "tax": "Können", "frage": "Die Selbstkosten eines Auftrags betragen 12 000 €. <b>Berechnen Sie den Netto-Angebotspreis</b> bei 8 % Wagnis & Gewinn.", "erklaerung": "<p>Wagnis & Gewinn wird als Zuschlag auf die Selbstkosten aufgeschlagen, um den Angebotspreis zu erhalten.</p><div class=\"formula\">Angebot = Selbstkosten · (1 + W&G)</div>", "loesung": "<div class=\"formula\">Netto = 12 000 · 1,08 = <b>12 960 €</b></div><p>Davon W&G = 960 €. + 19 % MwSt → Brutto = 12 960 · 1,19 = 15 422,40 €.</p>"}, {"id": "hf4b", "group": "hf4", "deck": "HF4B", "n": 1, "typ": "v", "kennung": "HF4b-2", "tax": "Wissen", "frage": "Was ist ein <b>Betriebsabrechnungsbogen (BAB)</b> und wozu dient er?", "erklaerung": "<p>Der BAB verteilt die Gemeinkosten auf Kostenstellen und liefert realistische Zuschlagssätze für die Kalkulation.</p>", "loesung": "<ul><li>Der BAB ist das Instrument der <b>Kostenstellenrechnung</b>: er verteilt die Gemeinkosten verursachungsgerecht auf <b>Kostenstellen</b> (Material, Fertigung, Verwaltung, Vertrieb).</li><li>Ergebnis: realistische <b>Gemeinkostenzuschlagssätze</b> für die Kalkulation.</li><li>Brücke zwischen Buchhaltung (Kostenartenrechnung) und Kalkulation (Kostenträgerrechnung).</li></ul>"}, {"id": "hf4b", "group": "hf4", "deck": "HF4B", "n": 2, "typ": "p", "kennung": "HF4b-1", "tax": "Können", "frage": "Ein Mitarbeiter hat 1 700 bezahlte Jahresstunden, davon 1 360 produktive Stunden. <b>Berechnen Sie den Produktivstundenanteil.</b>", "erklaerung": "<p>Nicht alle bezahlten Stunden sind verrechenbar (Urlaub, Krankheit, Rüst-/Wegezeiten). Der Produktivanteil bestimmt den Stundenverrechnungssatz.</p><div class=\"formula\">Produktivanteil = produktive Std. / bezahlte Std. · 100</div>", "loesung": "<div class=\"formula\">1 360 / 1 700 · 100 = <b>80 %</b></div><p>Typisch sind 75–80 % produktive Stunden. Je niedriger der Anteil, desto höher muss der Verrechnungssatz sein, damit die unproduktiven Stunden mitfinanziert werden.</p>"}, {"id": "hf4b", "group": "hf4", "deck": "HF4B", "n": 3, "typ": "v", "kennung": "HF4b-2", "tax": "Wissen", "frage": "Was versteht man unter <b>Betriebsvergleich / Benchmarking</b>?", "erklaerung": "<p>Benchmarking vergleicht die eigenen Kennzahlen mit Referenzwerten (Branche/Beste), um Schwächen und Potenziale zu erkennen.</p>", "loesung": "<ul><li>Vergleich eigener Kennzahlen (z. B. Materialquote, Stundensatz, Umsatz/MA) mit dem <b>Branchendurchschnitt</b> (z. B. ZDB-Statistiken) oder den Besten.</li><li>Ziel: <b>Abweichungen erkennen</b>, Ursachen analysieren, Verbesserungen ableiten.</li><li>Interner Vergleich (Projekte/Jahre) und externer Vergleich.</li></ul>"}, {"id": "hf4b", "group": "hf4", "deck": "HF4B", "n": 4, "typ": "v", "kennung": "HF4b-2", "tax": "Werten", "frage": "Welche Bedeutung hat der <b>Soll-Ist-Vergleich (Nachkalkulation)</b> im Controlling?", "erklaerung": "<p>Die Nachkalkulation prüft, ob die kalkulierten Kosten gehalten wurden. Sie ist das Frühwarnsystem des Betriebs.</p>", "loesung": "<ul><li>Vergleich der <b>geplanten (Soll-)</b> mit den <b>tatsächlichen (Ist-)</b> Kosten je Auftrag.</li><li>Abweichungsanalyse: Stundenverbrauch, Materialpreise, Geräteeinsatz.</li><li>Erkennt <b>unprofitable Projekte</b> und liefert Lernpunkte für die nächste Kalkulation.</li></ul>"}, {"id": "hf4b", "group": "hf4", "deck": "HF4B", "n": 5, "typ": "p", "kennung": "HF4b-1", "tax": "Können", "frage": "Die kalkulierten Jahres-Gemeinkosten betragen 96 000 €, die produktiven Jahresstunden 4 000 h. <b>Berechnen Sie den Gemeinkostenzuschlag je Stunde.</b>", "erklaerung": "<p>Die Gemeinkosten werden auf die produktiven Stunden umgelegt, um sie pro Stunde in den Verrechnungssatz einzurechnen.</p><div class=\"formula\">GK-Satz = Gemeinkosten / produktive Stunden</div>", "loesung": "<div class=\"formula\">96 000 € / 4 000 h = <b>24,00 €/h</b></div><p>Pro produktiver Stunde sind 24,00 € Gemeinkosten zu decken. Sinkt die Auslastung (weniger Stunden), steigt dieser Satz.</p>"}, {"id": "hf4b", "group": "hf4", "deck": "HF4B", "n": 6, "typ": "v", "kennung": "HF4b-1", "tax": "Werten", "frage": "Was ist <b>Liquidität / Cash-Flow-Planung</b> und warum ist sie überlebenswichtig?", "erklaerung": "<p>Ein Betrieb kann profitabel und trotzdem zahlungsunfähig sein, wenn Ein- und Auszahlungen zeitlich nicht passen.</p>", "loesung": "<ul><li><b>Liquidität:</b> jederzeitige Zahlungsfähigkeit (Rechnungen, Löhne, Material zahlen können).</li><li><b>Cash-Flow-Planung:</b> monatliche Gegenüberstellung erwarteter Ein-/Auszahlungen → Engpässe früh erkennen.</li><li>Maßnahmen: Abschlagszahlungen vereinbaren, Zahlungsziele steuern, Reserven/Kontokorrent.</li><li><b>Grundsatz:</b> „Liquidität vor Rentabilität\" – Zahlungsunfähigkeit = Insolvenzgrund.</li></ul>"}, {"id": "hf4b", "group": "hf4", "deck": "HF4B", "n": 7, "typ": "v", "kennung": "HF4b-1", "tax": "Wissen", "frage": "Nennen Sie wichtige <b>betriebliche Kennzahlen</b> und ihren Nutzen.", "erklaerung": "<p>Kennzahlen verdichten komplexe Sachverhalte zu steuerbaren Größen – Grundlage für Entscheidungen (ZDF: Zahlen, Daten, Fakten).</p>", "loesung": "<ul><li><b>Materialquote</b> = Material / Umsatz – Einkaufseffizienz.</li><li><b>Lohnquote</b> = Lohnkosten / Umsatz.</li><li><b>Produktivstundenanteil</b> – Auslastung.</li><li><b>Rentabilität</b> = Gewinn / Kapital · 100.</li><li><b>Deckungsbeitrag</b> = Erlös − variable Kosten.</li></ul><p>Nutzen: Steuerung, Frühwarnung, Benchmarking, fundierte Entscheidungen.</p>"}, {"id": "hf4b", "group": "hf4", "deck": "HF4B", "n": 8, "typ": "p", "kennung": "HF4b-1", "tax": "Können", "frage": "Ein Betrieb erzielt 18 000 € Gewinn bei 120 000 € eingesetztem Kapital. <b>Berechnen Sie die Rentabilität.</b>", "erklaerung": "<p>Die (Kapital-)Rentabilität zeigt, wie sich das eingesetzte Kapital verzinst – wichtig für Investitionsentscheidungen.</p><div class=\"formula\">Rentabilität = Gewinn / Kapital · 100</div>", "loesung": "<div class=\"formula\">18 000 / 120 000 · 100 = <b>15 %</b></div><p>15 % Kapitalrentabilität – deutlich über dem Kapitalmarktzins, also wirtschaftlich attraktiv.</p>"}, {"id": "hf4c", "group": "hf4", "deck": "HF4C", "n": 1, "typ": "v", "kennung": "HF4c-2", "tax": "Wissen", "frage": "Erklären Sie die <b>AIDA-Formel</b>.", "erklaerung": "<p>AIDA beschreibt die Wirkungsstufen, die Werbung durchlaufen sollte, bis ein Kunde handelt.</p>", "loesung": "<ul><li><b>A – Attention</b> (Aufmerksamkeit wecken)</li><li><b>I – Interest</b> (Interesse erzeugen)</li><li><b>D – Desire</b> (Wunsch/Bedürfnis wecken)</li><li><b>A – Action</b> (Handlung/Kaufabschluss auslösen)</li></ul><p>Anwendung z. B. beim Aufbau von Flyer, Website oder Anzeige.</p>"}, {"id": "hf4c", "group": "hf4", "deck": "HF4C", "n": 2, "typ": "v", "kennung": "HF4c-1", "tax": "Wissen", "frage": "Was ist eine <b>SWOT-Analyse</b> und wie ist sie aufgebaut?", "erklaerung": "<p>Die SWOT-Analyse verschafft Überblick über die Lage des Betriebs – intern und extern – als Basis für die Strategie.</p>", "loesung": "<table><tr><th>intern</th><th>extern</th></tr><tr><td><b>Strengths</b> (Stärken)</td><td><b>Opportunities</b> (Chancen)</td></tr><tr><td><b>Weaknesses</b> (Schwächen)</td><td><b>Threats</b> (Risiken)</td></tr></table><p>Stärken/Schwächen = im Betrieb beeinflussbar; Chancen/Risiken = Markt/Umfeld. Strategie: Stärken nutzen, Schwächen abbauen, Chancen ergreifen, Risiken begegnen.</p>"}, {"id": "hf4c", "group": "hf4", "deck": "HF4C", "n": 3, "typ": "v", "kennung": "HF4c-1", "tax": "Wissen", "frage": "Was bedeutet die <b>SMART-Regel</b> für Marketingziele? Nennen Sie ein Beispiel.", "erklaerung": "<p>Gute Ziele sind konkret und überprüfbar. SMART liefert die Kriterien dafür.</p>", "loesung": "<ul><li><b>S</b>pezifisch · <b>M</b>essbar · <b>A</b>ttraktiv/Ansprechend · <b>R</b>ealistisch · <b>T</b>erminiert</li></ul><p><b>Beispiel:</b> „20 % mehr Anfragen über die Website innerhalb von 6 Monaten\" – konkret, messbar, mit Frist.</p>"}, {"id": "hf4c", "group": "hf4", "deck": "HF4C", "n": 4, "typ": "v", "kennung": "HF4c-1", "tax": "Werten", "frage": "Erklären Sie den <b>Marketing-Mix (4 P)</b> mit Bezug zum Zimmereibetrieb.", "erklaerung": "<p>Der Marketing-Mix bündelt die Stellhebel, mit denen ein Betrieb seinen Markt bearbeitet.</p>", "loesung": "<ul><li><b>Product (Leistung):</b> Kernleistung (Dachstuhl) + Zusatznutzen (3D-Visualisierung, Energieberatung, Garantie).</li><li><b>Price (Preis):</b> Kalkulation + Preispsychologie (Paket-/Ab-Preise), Rabatte.</li><li><b>Place (Vertrieb):</b> Direktvertrieb, Architektenkooperation, Online-Anfragen.</li><li><b>Promotion (Kommunikation):</b> Website, Social Media, Flyer, PR, Fahrzeugbeschriftung.</li></ul>"}, {"id": "hf4c", "group": "hf4", "deck": "HF4C", "n": 5, "typ": "v", "kennung": "HF4c-1", "tax": "Werten", "frage": "Was ist ein <b>USP</b> und worauf kommt es dabei an?", "erklaerung": "<p>Der USP (Alleinstellungsmerkmal) macht den Betrieb unverwechselbar und begründet, warum Kunden gerade hier kaufen.</p>", "loesung": "<ul><li><b>USP = Unique Selling Proposition:</b> einzigartiger, <b>kundennutzenorientierter</b>, klar kommunizierbarer Vorteil.</li><li>Beispiele Zimmerer: „Fachwerksanierung mit 3D-Scan\", „ausschließlich regionale Hölzer\", „termingarantierte Montage\".</li><li>Abgrenzung über das <b>Wettbewerbsdreieck</b>: Kundenbedürfnis ↔ eigene Stärken ↔ Konkurrenz.</li></ul>"}, {"id": "hf4c", "group": "hf4", "deck": "HF4C", "n": 6, "typ": "v", "kennung": "HF4c-1", "tax": "Werten", "frage": "Wie funktioniert die <b>BCG-Matrix (Portfolio-Analyse)</b> und welche Strategien folgen daraus?", "erklaerung": "<p>Die BCG-Matrix ordnet Leistungen/Produkte nach Marktwachstum und Marktanteil ein, um Investitionsentscheidungen abzuleiten.</p>", "loesung": "<table><tr><th>Feld</th><th>Bedeutung / Strategie</th></tr><tr><td><b>Question Marks</b></td><td>hohes Wachstum, kleiner Anteil → investieren oder aufgeben</td></tr><tr><td><b>Stars</b></td><td>hohes Wachstum, hoher Anteil → fördern/investieren</td></tr><tr><td><b>Cash Cows</b></td><td>geringes Wachstum, hoher Anteil → „melken\", Gewinn abschöpfen</td></tr><tr><td><b>Poor Dogs</b></td><td>geringes Wachstum/Anteil → eliminieren</td></tr></table>"}, {"id": "hf4c", "group": "hf4", "deck": "HF4C", "n": 7, "typ": "v", "kennung": "HF4c-2", "tax": "Wissen", "frage": "Unterscheiden Sie <b>Corporate Design (CD) und Corporate Identity (CI)</b>.", "erklaerung": "<p>Ein einheitlicher Auftritt schafft Wiedererkennung und Vertrauen. CD ist das Sichtbare, CI das Gesamtbild.</p>", "loesung": "<ul><li><b>Corporate Design (CD):</b> das <b>visuelle Erscheinungsbild</b> – Logo, Farben, Schriften, Bildsprache; angewendet auf Visitenkarten, Flyer, Fahrzeuge, Arbeitskleidung, Baustellenschilder.</li><li><b>Corporate Identity (CI):</b> das <b>Gesamtbild</b> = CD + Unternehmenskultur + Kommunikation + Verhalten.</li></ul><p>CD ist Teil der CI.</p>"}, {"id": "hf4c", "group": "hf4", "deck": "HF4C", "n": 8, "typ": "v", "kennung": "HF4c-4", "tax": "Wissen", "frage": "Welche Bausteine der <b>digitalen Präsenz</b> sind für einen Handwerksbetrieb wichtig (inkl. SEO/SEA/GMB)?", "erklaerung": "<p>Kunden suchen heute zuerst online. Eine durchdachte digitale Präsenz bringt Anfragen und Vertrauen.</p>", "loesung": "<ul><li><b>Website</b> (Herzstück): Referenzen, Team, Kontakt, Impressum, <b>Datenschutz (DSGVO)</b>.</li><li><b>SEO:</b> organisches Ranking verbessern (Inhalte, lokale Keywords).</li><li><b>SEA:</b> bezahlte Suchanzeigen (Google Ads).</li><li><b>Google Business Profile:</b> lokale Sichtbarkeit, Bewertungen, Öffnungszeiten.</li><li><b>Social Media</b> (Instagram: Vorher-Nachher, Facebook: Stellenanzeigen).</li></ul>"}, {"id": "hf4c", "group": "hf4", "deck": "HF4C", "n": 9, "typ": "p", "kennung": "HF4c-1", "tax": "Können", "frage": "Entwickeln Sie ein <b>Marketingkonzept in 6 Schritten</b> für die Einführung einer neuen Leistung (z. B. Carport-Bau).", "erklaerung": "<p>Ein Marketingkonzept geht systematisch von der Zielsetzung bis zur Erfolgskontrolle – beliebte Klausuraufgabe.</p>", "loesung": "<ol><li><b>Ziel</b> festlegen (SMART, z. B. 15 Carport-Aufträge/Jahr).</li><li><b>Zielgruppe</b> bestimmen (Eigenheimbesitzer im Umkreis).</li><li><b>USP</b> definieren (regionales Holz, Festpreis, 2 Wochen Montage).</li><li><b>Marketing-Mix</b> festlegen (Product/Price/Place/Promotion).</li><li><b>Budget</b> planen (Anzeigen, Flyer, Website).</li><li><b>Kontrolle</b> (Anfragen messen, Soll-Ist, nachsteuern).</li></ol>"}, {"id": "hf4d", "group": "hf4", "deck": "HF4D", "n": 1, "typ": "v", "kennung": "HF4d-1", "tax": "Wissen", "frage": "Erklären Sie den <b>PDCA-Zyklus</b> (Deming-Rad).", "erklaerung": "<p>Der PDCA-Zyklus ist das Herzstück kontinuierlicher Verbesserung (KVP) – ständiges Optimieren, nicht einmalig.</p>", "loesung": "<ul><li><b>P – Plan (Planen):</b> Ziele setzen, Prozess entwerfen, Maßnahmen planen.</li><li><b>D – Do (Ausführen):</b> Maßnahmen umsetzen, Daten sammeln, Prozess durchlaufen.</li><li><b>C – Check (Überprüfen):</b> Ergebnisse mit Plan vergleichen, Abweichungen erkennen.</li><li><b>A – Act (Handeln):</b> Erkenntnisse nutzen, Verbesserungen verstetigen, nächsten Zyklus starten.</li></ul><p>Wiederholung führt zu kontinuierlicher Verbesserung.</p>"}, {"id": "hf4d", "group": "hf4", "deck": "HF4D", "n": 2, "typ": "v", "kennung": "HF4d-1", "tax": "Wissen", "frage": "Was bedeutet <b>Qualitätsmanagementsystem nach DIN EN ISO 9001</b>?", "erklaerung": "<p>ISO 9001 ist die weltweit anerkannte QM-Norm – Zertifizierung zeigt Kompetenz und Seriosität.</p>", "loesung": "<ul><li><b>Grundprinzipien:</b> Kundenorientierung, Mitarbeiter-Engagement, prozessgerichtetes Denken, kontinuierliche Verbesserung.</li><li><b>Anforderungen:</b> Dokumentation (QM-Handbuch), Prozessregelungen, interne Audits, Managementbewertung, Risikomanagement.</li><li><b>Vorteil:</b> Systematische Qualität, Fehlerreduktion, Kundenzufriedenheit, Marktvorteil (Zertifikat).</li></ul>"}, {"id": "hf4d", "group": "hf4", "deck": "HF4D", "n": 3, "typ": "v", "kennung": "HF4d-2", "tax": "Wissen", "frage": "Was ist ein <b>Ishikawa-Diagramm (Fischgräten-Diagramm)</b> und wie nutzt man es?", "erklaerung": "<p>Das Ishikawa-Diagramm ordnet Fehlerursachen systematisch – hilfreich, um nicht beim Symptom stehen zu bleiben.</p>", "loesung": "<p><b>6 Kategorien (die \"6 M\"):</b></p><ul><li><b>Mensch:</b> Qualifikation, Müdigkeit, Fehler</li><li><b>Maschine:</b> Verschleiß, falsche Einstellung, Wartung</li><li><b>Methode:</b> Prozess, Arbeitsschritte, Standards</li><li><b>Material:</b> Fehlerhafte Rohstoffe, Lagerung</li><li><b>Mitwelt:</b> Umgebung, Witterung, Baustelle</li><li><b>Messung:</b> Messpunkte, -genauigkeit, Prüfung</li></ul><p>Einsatz: Fehler analysieren, alle möglichen Ursachen sammeln, Lösungen ableiten.</p>"}, {"id": "hf4d", "group": "hf4", "deck": "HF4D", "n": 4, "typ": "v", "kennung": "HF4d-2", "tax": "Wissen", "frage": "Was ist <b>Reklamationsmanagement</b> und warum ist Kundenzufriedenheit die beste Werbung?", "erklaerung": "<p>Beschwerden sind Chancen, nicht Ärger – wer sie nutzt, gewinnt Kunden.</p>", "loesung": "<ul><li><b>Prozess:</b> Beschwerde entgegennehmen (schnell + respektvoll), Ursache prüfen, Lösung anbieten, Kulanz, Follow-up.</li><li><b>Nutzen:</b> Kundenzufriedenheit wiederherstellen, Prozessverbesserung ablesen, Kundenloyalität.</li><li><b>Psychologisch:</b> Wer richtig reklamiert wird, ist oft zufriedener als ohne Mangel!</li></ul>"}, {"id": "hf4d", "group": "hf4", "deck": "HF4D", "n": 5, "typ": "v", "kennung": "HF4d-1", "tax": "Wissen", "frage": "Unterscheiden Sie <b>Prozessdokumentation, Arbeitsanweisung und Checkliste</b>.", "erklaerung": "<p>Klare Schriftlichkeit verhindert Fehler und Wiederholung – QM lebt von Dokumentation.</p>", "loesung": "<table><tr><th>Dokument</th><th>Zweck</th></tr><tr><td><b>Prozessdokumentation</b></td><td>Überblick: wie läuft der Gesamtprozess ab (Ablaufdiagramm, Schritte)</td></tr><tr><td><b>Arbeitsanweisung</b></td><td>Detaillierte Beschreibung: Schritt für Schritt wie wird's gemacht</td></tr><tr><td><b>Checkliste</b></td><td>Kontrollliste: Was muss geprüft/abgehakt werden (schnell abarbeitsbar)</td></tr></table>"}, {"id": "hf4d", "group": "hf4", "deck": "HF4D", "n": 6, "typ": "v", "kennung": "HF4d-1", "tax": "Werten", "frage": "Was ist eine <b>Qualifikationsmatrix</b> und was zeigt sie?", "erklaerung": "<p>Die Matrix ordnet Mitarbeiter nach Tätigkeiten und Qualifikation – zeigt, wer was kann und wer Schulung braucht.</p>", "loesung": "<p>Aufbau: Spalten = Tätigkeiten/Prozesse, Zeilen = Mitarbeiter. Eintrag: ✓ (kann), ~ (mit Anleitung), ✗ (kann nicht).</p><p><b>Nutzen:</b> Schnelle Übersicht, Engpässe erkennen, Schulungsbedarf planen, Personalentwicklung steuern (M.A.Z.O.: Mitarbeiter, richtige Zeit, richtige Aktivität, richtiger Ort).</p>"}, {"id": "hf4d", "group": "hf4", "deck": "HF4D", "n": 7, "typ": "p", "kennung": "HF4d-2", "tax": "Können", "frage": "Ein Fehler bei Dachdeckung führt zu Wasserschaden (1 500 € Kosten). <b>Gestalten Sie den Reklamationsprozess.</b>", "erklaerung": "<p>Praxis: Wie reagiert professionelle Firma auf Reklamation?</p>", "loesung": "<ol><li><b>Schnell reagieren:</b> Innerhalb 24h Kontakt mit Kunde, Verständnis zeigen, Wertschätzung.</li><li><b>Ursache analysieren:</b> Ishikawa-Diagramm oder Fehleranalyse (Material? Montage? Wartung?).</li><li><b>Lösung anbieten:</b> Beseitigung (Nachbesserung), ggf. Kulanzzahlung oder Regress beim Subunternehmer.</li><li><b>Prozess verbessern:</b> Erkenntnisse in Checkliste/Arbeitsanweisung aufnehmen, Team schulen.</li><li><b>Follow-up:</b> Nach Woche nachfragen, ob Kunde zufrieden, weitere Unterstützung anbieten.</li></ol>"}, {"id": "hf4d", "group": "hf4", "deck": "HF4D", "n": 8, "typ": "v", "kennung": "HF4d-2", "tax": "Wissen", "frage": "Was ist <b>kontinuierlicher Verbesserungsprozess (KVP)</b> und wie sieht ein Beispiel aus?", "erklaerung": "<p>KVP ist nicht einmalig – es ist Unternehmenskultur, kleine Schritte ständig zu optimieren.</p>", "loesung": "<p><b>Beispiel Zimmerei:</b></p><ol><li><b>Beobachtung:</b> Beim Abbund wird oft nachgemessen (ineffizient).</li><li><b>PDCA:</b> Plan (Genauigkeitstoleranz definieren) → Do (CNC-Software anpassen) → Check (Ausschuss sinkt von 8 % auf 2 %) → Act (Standard fortschreiben).</li><li><b>Kultur:</b> Mitarbeiter sammeln Verbesserungsvorschläge (Ideenbox), regelmäßig besprechen, kleine Verbesserungen verstetigen.</li></ol>"}, {"id": "hf4e", "group": "hf4", "deck": "HF4E", "n": 1, "typ": "v", "kennung": "HF4e-3", "tax": "Werten", "frage": "Vergleichen Sie die <b>Lohnformen</b> (Zeitlohn, Akkordlohn, Prämienlohn) – Vor- und Nachteile.", "erklaerung": "<p>Die Lohnform beeinflusst Motivation und Qualität – richtige Wahl ist wichtig.</p>", "loesung": "<table><tr><th>Form</th><th>Vorteil</th><th>Nachteil</th></tr><tr><td><b>Zeitlohn</b></td><td>fair, kein Sicherheitsrisiko</td><td>weniger Leistungsanreiz</td></tr><tr><td><b>Akkordlohn</b></td><td>hoher Leistungsanreiz</td><td>Qualitätsgefahr, nur für messbare Leistung</td></tr><tr><td><b>Prämienlohn</b></td><td>vielfältige Ziele (Qualität, Termine)</td><td>Abrechnung komplex</td></tr></table><p><b>Praxis Zimmerei:</b> meist Zeitlohn auf Baustelle (Sicherheit prioritär), ggf. Akkord in Werkstatt (Abbund).</p>"}, {"id": "hf4e", "group": "hf4", "deck": "HF4E", "n": 2, "typ": "v", "kennung": "HF4e-2", "tax": "Wissen", "frage": "Was sind <b>SOKA-BAU</b> und welche Bestandteile hat sie?", "erklaerung": "<p>SOKA-BAU ist das Sozialkassensystem der Bauwirtschaft – komplex aber zentral für Betriebskosten.</p>", "loesung": "<ul><li><b>ZVK (Zusatzversorgungskasse):</b> betriebliche Altersvorsorge Bau (Rente).</li><li><b>ULAK (Urlaubs- und Lohnausgleichskasse):</b> verrechnet Urlaubsansprüche zwischen Betrieben (mobiler Arbeitsmarkt im Bau).</li><li><b>BBTV (Berufsbildungsabgabe):</b> Finanzierung Berufsausbildung.</li><li>Beiträge: AG zahlt prozentuale Anteile (meist 10–15 % der Lohnsumme), dokumentiert durch Entgeltzettel.</li></ul>"}, {"id": "hf4e", "group": "hf4", "deck": "HF4E", "n": 3, "typ": "p", "kennung": "HF4e-2", "tax": "Können", "frage": "Ein Geselle verdient 24,50 €/h brutto. <b>Berechnen Sie die SOKA-Umlage des Arbeitgebers</b> für einen 160-Stunden-Monat bei ca. 12 % SOKA-Umlage.", "erklaerung": "<p>Lohnnebenkosten sind oft unterschätzt – die Rechnung zeigt das wahre Personalkosten-Bild.</p>", "loesung": "<p><b>Bruttolohn/Monat:</b> 24,50 · 160 = 3 920,00 €</p><p><b>SOKA-Umlage 12 % (wie vorgegeben):</b></p><div class=\"formula\">3 920,00 · 0,12 = 470,40 €/Monat</div><p><b>Bruttolohn + SOKA:</b> 3 920,00 + 470,40 = <b>4 390,40 €/Monat</b></p><p><b>Wichtig:</b> Das ist <i>nur</i> die SOKA-Umlage. Die gesamten Lohnzusatzkosten im Bau (inkl. Sozialversicherungs-Arbeitgeberanteile) liegen bei rund <b>80 %</b> des Bruttolohns (siehe HF 4a) – Personalkosten also ≈ 1,8× Bruttoentgelt.</p>"}, {"id": "hf4e", "group": "hf4", "deck": "HF4E", "n": 4, "typ": "v", "kennung": "HF4e-1", "tax": "Wissen", "frage": "Was gehört in einen <b>Arbeitsvertrag</b>? Nennen Sie die Pflichtinhalte.", "erklaerung": "<p>Ein schriftlicher Vertrag schützt beide Seiten und verhindert Missverständnisse.</p>", "loesung": "<ul><li><b>Pflichtinhalte nach § 2 NachwG (Nachweisgesetz):</b> Name/Anschrift der Parteien, Beginn, Tätigkeit, Arbeitsort, Vergütung, Arbeitszeit, Urlaub, Kündigungsfristen.</li><li><b>Zusätzlich empfohlen:</b> Probezeit, Bezug auf Tarifvertrag (BRTV), betriebliche Regelungen.</li><li><b>Form:</b> wesentliche Bedingungen <b>schriftlich</b> niederzulegen (§ 2 NachwG; Aushändigung z. T. ab dem 1. Arbeitstag).</li><li><b>Probezeit:</b> max. 6 Monate (§ 622 BGB).</li></ul>"}, {"id": "hf4e", "group": "hf4", "deck": "HF4E", "n": 5, "typ": "v", "kennung": "HF4e-1", "tax": "Wissen", "frage": "Was regelt das <b>Kündigungsschutzgesetz (KSchG)</b>?", "erklaerung": "<p>KSchG schützt Mitarbeiter vor willkürlicher Kündigung – wichtig zu kennen für faire Kommunikation.</p>", "loesung": "<ul><li><b>Geltung:</b> ab <b>10+ Mitarbeiter</b> im Betrieb UND mind. <b>6 Monate</b> Betriebszugehörigkeit.</li><li><b>Anforderungen:</b> Kündigung nur bei <b>wichtigem Grund</b> oder in <b>Betriebsänderung</b> (Sozialplan).</li><li><b>Wichtige Gründe:</b> verhaltensbedingter Grund (schlechte Leistung, Pflichtverletzung mit Abmahnung), personenbedingter Grund (Krankheit, fehlende Eignung), betriebsbedingter Grund (Wirtschaftlichkeit).</li><li><b>Verfahren:</b> Schriftform, Begründung, Widerspruchsmöglichkeit (Kündigungsschutzklage 3 Wochen).</li></ul>"}, {"id": "hf4e", "group": "hf4", "deck": "HF4E", "n": 6, "typ": "v", "kennung": "HF4e-1", "tax": "Erkennen", "frage": "Unterscheiden Sie <b>ordentliche und außerordentliche (fristlose) Kündigung</b>.", "erklaerung": "<p>Die Unterscheidung ist rechtlich entscheidend – fristlose Kündigung braucht extremen Grund.</p>", "loesung": "<ul><li><b>Ordentliche Kündigung:</b> einhält Fristen (BGB oder Tarifvertrag, jeweils die längere); braucht Grund (bei KSchG) oder gar keinen (ohne KSchG).</li><li><b>Außerordentliche Kündigung (fristlos):</b> sofortige Beendigung; nur bei <b>wichtigem Grund</b> nach § 626 BGB (grobe Pflichtverletzung, z. B. Diebstahl, Gewalt); muss innerhalb 2 Wochen erfolgen.</li></ul>"}, {"id": "hf4e", "group": "hf4", "deck": "HF4E", "n": 7, "typ": "v", "kennung": "HF4e-3", "tax": "Wissen", "frage": "Nennen Sie die <b>Führungsstile</b> und wann sie passen.", "erklaerung": "<p>Unterschiedliche Situationen brauchen unterschiedliche Führung – flexibel sein ist die Kunst.</p>", "loesung": "<ul><li><b>Autoritär:</b> Vorgesetzter trifft Entscheidung allein; schnell, aber wenig Mitarbeitermotivation; Einsatz: Notfall, klare Hierarchie nötig.</li><li><b>Kooperativ/Demokratisch:</b> MA werden beteiligt; zeitaufwändig, aber hohe Motivation; Einsatz: etablierte Teams, Problemlösung.</li><li><b>Situativ:</b> Je nach MA und Situation angepasst (modern, bewährt); Einsatz: flexible Führung, Vertrauen.</li></ul>"}, {"id": "hf4e", "group": "hf4", "deck": "HF4E", "n": 8, "typ": "v", "kennung": "HF4e-3", "tax": "Wissen", "frage": "Was ist ein <b>Mitarbeitergespräch</b> und worum sollte es gehen?", "erklaerung": "<p>Regelmäßige Gespräche sind günstige Prävention von Problemen und fördern Entwicklung.</p>", "loesung": "<ul><li><b>Häufigkeit:</b> mind. 1–2x pro Jahr; kürzere Abstände bei Neuen oder Problemen.</li><li><b>Inhalte:</b> Beurteilung Leistung/Verhalten, Zielvereinbarung, Entwicklungswünsche, Weiterbildung, Feedback (loben + konstruktiv kritisieren).</li><li><b>Vorbereitung:</b> Noten sammeln, Gesprächsführung überlegen, ruhiger Raum.</li><li><b>Dokumentation:</b> Notizen & Unterschrift (rechtliche Absicherung).</li></ul>"}, {"id": "hf4e", "group": "hf4", "deck": "HF4E", "n": 9, "typ": "p", "kennung": "HF4e-3", "tax": "Können", "frage": "Ein langjähriger Geselle, der gut arbeitet, häuft Fehltage an (Krankheit). <b>Wie führt der Meister das Gespräch?</b>", "erklaerung": "<p>Praktisches Fallbeispiel: Wie handhabe ich zwischenmenschlich schwierige Situationen konstruktiv?</p>", "loesung": "<ol><li><b>Sachlich & respektvoll:</b> Mir ist aufgefallen, dass deine Fehlzeiten in letzten 3 Monaten gestiegen sind.</li><li><b>Offene Fragen stellen:</b> Was ist da los? Wie geht's dir? Können wir dir helfen?</li><li><b>Zuhören:</b> Ev. persönliche/gesundheitliche Probleme? Burnout?</li><li><b>Lösungen suchen:</b> Gemeinsam Möglichkeiten erarbeiten (Arzt, Betriebsrat, flexible Arbeitszeit).</li><li><b>Grenzen setzen:</b> Falls es nicht besser wird, müssen wir betriebsärztlich abklären (fair & rechtsicher).</li></ol>"}, {"id": "hf4f", "group": "hf4", "deck": "HF4F", "n": 1, "typ": "v", "kennung": "HF4f-1", "tax": "Können", "frage": "Erklären Sie die <b>7 Schritte der Gefährdungsbeurteilung (GFB)</b>.", "erklaerung": "<p>Die GFB ist die Basis aller Arbeitsschutzmaßnahmen – ohne sie weiß man nicht, wo die Risiken liegen.</p>", "loesung": "<ol><li><b>Arbeitsbereiche/Tätigkeiten festlegen</b> (z. B. Dacharbeiten, Sägearbeiten).</li><li><b>Gefährdungen ermitteln</b> (Absturz, Schnittgefahr, Lärm, Staub, psychische Belastung).</li><li><b>Gefährdungen bewerten</b> (Eintrittswahrscheinlichkeit × Schweregrad → Risikomatrix).</li><li><b>Maßnahmen festlegen</b> (Prävention nach STOP-Prinzip).</li><li><b>Maßnahmen durchführen</b> (Umsetzung mit Termin & Verantwortlichem).</li><li><b>Wirksamkeit prüfen</b> (Sind Maßnahmen wirksam? Zielüberprüfung).</li><li><b>GFB fortschreiben</b> (nach Unfall, neuer Tätigkeit, Änderung).</li></ol>"}, {"id": "hf4f", "group": "hf4", "deck": "HF4F", "n": 2, "typ": "v", "kennung": "HF4f-1", "tax": "Wissen", "frage": "Was ist das <b>STOP-Prinzip</b> in der Rangfolge der Schutzmaßnahmen?", "erklaerung": "<p>Nicht alle Maßnahmen sind gleich wirksam – STOP ordnet sie nach Effektivität.</p>", "loesung": "<ol><li><b>S – Substitution:</b> Gefahr beseitigen (z. B. lärmlose Maschine statt laute).</li><li><b>T – Technische Maßnahmen:</b> Schutzvorrichtungen, Absturzsicherung baulich, Lüftung.</li><li><b>O – Organisatorische Maßnahmen:</b> Arbeitsorganisation, Pausenzeiten, Bereiche sperren.</li><li><b>P – PSA (Persönliche Schutzausrüstung):</b> Helm, Handschuhe, Gehörschutz – <b>letzte Option!</b></li></ol><p>Grund: Je früher in der Kette, desto mehr Leute profitieren (nicht jeder muss PSA tragen).</p>"}, {"id": "hf4f", "group": "hf4", "deck": "HF4F", "n": 3, "typ": "p", "kennung": "HF4f-1", "tax": "Können", "frage": "Auf Baustelle sollen Dacharbeiten stattfinden (Neigung 18°, 80 m² Fläche, 3 Personen). <b>Ab welcher Höhe ist Absturzsicherung erforderlich?</b>", "erklaerung": "<p>Dacharbeiten haben Sonderregeln – niedrigere Grenzen als andere Arbeitsplätze, aber mit Bedingungen.</p>", "loesung": "<p><b>Sonderregel Dachregel (DGUV V38):</b> Bei Neigung ≤ 22,5° und Fläche ≤ 50 m² → Verzicht auf Absturzsicherung bis <b>3,00 m Höhe</b> möglich (nur für fachlich qualifizierte, besonders unterwiesene Personen).</p><p>Hier: 18° ≤ 22,5° ✓ und 80 m² &gt; 50 m² ✗ → Sonderregel fällt weg! <b>Ab 2,00 m</b> (normale Regel) ist Sicherung erforderlich.</p>"}, {"id": "hf4f", "group": "hf4", "deck": "HF4F", "n": 4, "typ": "v", "kennung": "HF4f-3", "tax": "Wissen", "frage": "Wer trägt die Kosten für die <b>Bereitstellung von PSA</b>?", "erklaerung": "<p>PSA ist kostspielig – die Frage der Kostentragung ist rechtlich klar geregelt.</p>", "loesung": "<p><b>Der Unternehmer trägt alle Kosten:</b> Anschaffung, Reinigung, Instandhaltung, Reparatur, Austausch (§ 29 DGUV V1). Die PSA ist kostenlos für Mitarbeiter bereitzustellen.</p>"}, {"id": "hf4f", "group": "hf4", "deck": "HF4F", "n": 5, "typ": "v", "kennung": "HF4f-3", "tax": "Wissen", "frage": "Wie oft und wann muss eine <b>Unterweisung</b> durchgeführt werden?", "erklaerung": "<p>Unterweisung ist Pflicht und muss dokumentiert werden – Nachweis im Unfall-/Kontrollfall entscheidend.</p>", "loesung": "<ul><li><b>Erstunterweisung:</b> vor Aufnahme der Beschäftigung (auch Neue, Praktikanten, Leiharbeiter).</li><li><b>Regelmäßig:</b> mindestens <b>1x jährlich</b> (§ 4 DGUV V1).</li><li><b>Zusätzlich:</b> bei Arbeitsplatzwechsel, neuen Maschinen/Stoffen, nach Unfall.</li><li><b>PSAgA-Unterweisung:</b> mit praktischen Übungen + Rettungsszenarien (lebensrettend!).</li><li><b>Dokumentation:</b> schriftlich, Unterschrift der Unterwiesenen, Archivierung.</li></ul>"}, {"id": "hf4f", "group": "hf4", "deck": "HF4F", "n": 6, "typ": "v", "kennung": "HF4f-3", "tax": "Wissen", "frage": "Was versteht man unter <b>Arbeitsplatzgrenzwert (AGW)</b> für Holzstaub?", "erklaerung": "<p>Grenzwerte definieren, ab wann ein Stoff gesundheitsschädlich wird – Basis für Maßnahmen und Überwachung.</p>", "loesung": "<ul><li><b>Holzstaub-AGW:</b> <b>2 mg/m³</b> (TRGS 900) – <b>krebsverdächtig (Kategorie 1A)</b>!</li><li>Anforderungen: Absaugung, Atemschutz bei Überschreitung, Messungen, Entsorgungsklasse beachten.</li><li>Andere Grenzwerte: Lärmgrenzwert 87 dB(A).</li></ul>"}, {"id": "hf4f", "group": "hf4", "deck": "HF4F", "n": 7, "typ": "v", "kennung": "HF4f-1", "tax": "Können", "frage": "Welche <b>Dokumentationen</b> sind bei Arbeitsunfällen erforderlich?", "erklaerung": "<p>Verletzungen sind schnell passiert – die richtige Dokumentation schützt später Betrieb und Betroffene.</p>", "loesung": "<ul><li><b>Verbandbuch:</b> auch Kleinstverletzungen eintragen (Beweis für Arbeitsunfall).</li><li><b>Unfallanzeige:</b> bei Arbeitsunfähigkeit &gt; 3 Tage → Meldung an Berufsgenossenschaft (innerhalb 3 Tagen).</li><li><b>Beinahe-Unfälle:</b> auch dokumentieren – Warnsignale für Verbesserung.</li><li><b>GFB-Aktualisierung:</b> nach jedem Unfall nötig.</li></ul>"}, {"id": "hf4f", "group": "hf4", "deck": "HF4F", "n": 8, "typ": "p", "kennung": "HF4f-4", "tax": "Können", "frage": "Entwickeln Sie ein <b>Abfallentsorgungskonzept</b> für einen Dachsanierungsauftrag (Fläche 150 m²).", "erklaerung": "<p>Prüfungsklassiker – zeigt, ob Betrieb rechtlich und ökologisch bewusst arbeitet.</p>", "loesung": "<ol><li><b>Abfallarten schätzen:</b> Altes Dachdeckungsmaterial (Ziegel/Schindeln), Holz (Sparren), Dämmstoffe, Folien, Nägel/Metallteile. Anhaltswert: 0,02–0,04 m³ pro m³ umbautem Raum → hier ca. 5–10 m³ Abfall.</li><li><b>Sortierung:</b> Mineralische Dachausbauten (A/B/C), Holz (A I–A II), Metall, gefährliche Stoffe.</li><li><b>Behälter/Container:</b> Größe & Anzahl festlegen, Standort auf Baustelle, Zugang für Entsorger.</li><li><b>Entsorgungswege:</b> Recycler/Bauschutt­platz, Holzaufbereiter, Schrotthandel.</li><li><b>Dokumentation:</b> Abfallbilanz, Abnahmelieferscheine aufbewahren (10 Jahre).</li></ol>"}, {"id": "hf4f", "group": "hf4", "deck": "HF4F", "n": 9, "typ": "v", "kennung": "HF4f-4", "tax": "Wissen", "frage": "Was regelt das <b>Kreislaufwirtschaftsgesetz (KrWG)</b>?", "erklaerung": "<p>Das KrWG setzt die Prioritäten für Abfallwirtschaft – vom Vermeide bis zur Beseitigung.</p>", "loesung": "<p><b>Abfallhierarchie (5-stufig):</b></p><ol><li>Vermeiden</li><li>Vorbereitung zur Wiederverwendung</li><li>Recycling</li><li>Sonstige Verwertung (z. B. thermisch)</li><li>Beseitigung (Deponie)</li></ol><p><b>Auf Baustellen:</b> Holzschnitt + Verschnitt separat sammeln (verwertbar); Dachausbauten fachgerecht trennen; Bauschutt vom Holz trennen.</p>"}, {"id": "hf4g", "group": "hf4", "deck": "HF4G", "n": 1, "typ": "p", "kennung": "HF4g-1", "tax": "Können", "frage": "Berechnen Sie die <b>jährlichen Vorhaltekosten</b> einer Abbundanlage: Neuwert 80 000 €, Nutzungsdauer 10 Jahre, Reparatursatz 3,5 % p.a., Zinssatz 6 %, Reparaturfaktor 1,49.", "erklaerung": "<p>Gerätekosten bestimmen Stundenkalkulation – diese Rechnung ist eine Klassiker-Aufgabe.</p>", "loesung": "<p><b>Abschreibung (AfA):</b> 80 000 / 10 = 8 000 €/Jahr</p><p><b>Verzinsung:</b> (80 000 / 2) × 6 % = 2 400 €/Jahr</p><p><b>Reparatur mit Faktor:</b> 80 000 × 3,5 % × 1,49 = 4 172 €/Jahr</p><div class=\"formula\">Vorhaltekosten/Jahr = 8 000 + 2 400 + 4 172 = <b>14 572 €</b>/Jahr</div><p>Bei 1 200 Betriebsstunden/Jahr: 14 572 / 1 200 = <b>12,14 €/h Maschinenkosten.</b></p>"}, {"id": "hf4g", "group": "hf4", "deck": "HF4G", "n": 2, "typ": "v", "kennung": "HF4g-1", "tax": "Wissen", "frage": "Unterscheiden Sie <b>Leistungsgeräte und Bereitstellungsgeräte</b>.", "erklaerung": "<p>Nicht alle Geräte werden gleich verrechnet – die Unterscheidung bestimmt die Kostenzuordnung.</p>", "loesung": "<ul><li><b>Leistungsgeräte:</b> direkt einer Position zuordenbar (z. B. Kran, Abbundanlage, Säge) – Kosten pro Position berechnet.</li><li><b>Bereitstellungsgeräte:</b> allgemeine Baustellenausstattung (z. B. Baucontainer, Toilette, Werkstätte) – Gemeinkosten oder Baustelle pauschal.</li></ul><p>Folge: Leistungsgeräte belasten einzelne Positionen, Bereitstellungsgeräte den ganzen Auftrag.</p>"}, {"id": "hf4g", "group": "hf4", "deck": "HF4G", "n": 3, "typ": "v", "kennung": "HF4g-4", "tax": "Werten", "frage": "Was ist eine <b>Break-Even-Analyse</b> und wie nutzt man sie für Investitionsentscheidungen?", "erklaerung": "<p>Break-Even zeigt, ab wann sich eine Investition amortisiert – kritische Entscheidungshilfe.</p>", "loesung": "<p><b>Break-Even-Punkt</b> = Auslastung (Betriebsstunden oder Umsatz), bei der Erlöse = Kosten.</p><div class=\"formula\">Break-Even = Fixkosten / (Preis − variable Kosten je Einheit)</div><p><b>Beispiel:</b> Neue Maschine kostet 30 000 €/Jahr (Fix), Betrieb kostet 15 €/Stunde (variabel), Verrechnung 45 €/h. Dann: BE = 30 000 / (45−15) = 1 000 h/Jahr. <b>Ab 1 000 h ist die Maschine rentabel.</b></p>"}, {"id": "hf4g", "group": "hf4", "deck": "HF4G", "n": 4, "typ": "v", "kennung": "HF4g-4", "tax": "Wissen", "frage": "Was versteht man unter <b>Amortisationsrechnung</b>?", "erklaerung": "<p>Die Amortisationszeit zeigt, wie lange es dauert, bis die Investition durch Gewinne zurückgewonnen ist.</p>", "loesung": "<div class=\"formula\">Amortisationszeit = Investitionssumme / (jährlicher Gewinn + Abschreibung)</div><p><b>Beispiel:</b> Maschine 100 000 €, erwarteter Gewinn 15 000 €/Jahr, AfA 10 000 €/Jahr. Rückfluss = 25 000 €/Jahr. Amortisationszeit = 100 000 / 25 000 = <b>4 Jahre</b>. Nach 4 Jahren hat sich die Maschine bezahlt.</p><p>Faustregel: < 5 Jahre = attraktiv.</p>"}, {"id": "hf4g", "group": "hf4", "deck": "HF4G", "n": 5, "typ": "v", "kennung": "HF4g-1", "tax": "Wissen", "frage": "Welche Kostenarten gehören in die <b>Fuhrpark-Kalkulation</b>?", "erklaerung": "<p>Fahrzeugkosten sind oft versteckt – wer sie nicht rechnet, kalkuliert zu niedrig.</p>", "loesung": "<ul><li><b>Anschaffungskosten:</b> Kaufpreis (oder Leasing-Raten).</li><li><b>Abschreibung:</b> Wertverlust p.a.</li><li><b>Versicherung & Steuer:</b> Jahresbeiträge.</li><li><b>Betriebsstoffe:</b> Kraftstoff, Öl, Kühlmittel.</li><li><b>Wartung & Reparatur:</b> planmäßig (Service), ungeplant.</li><li><b>Zinsen:</b> falls finanziert.</li></ul><p>Gesamt/km ist der Verrechnungssatz (z. B. 0,85 €/km).</p>"}, {"id": "hf4g", "group": "hf4", "deck": "HF4G", "n": 6, "typ": "v", "kennung": "HF4g-2", "tax": "Wissen", "frage": "Was ist das <b>REFA-System</b> und wie ordnet es Arbeitszeiten?", "erklaerung": "<p>REFA standardisiert Zeitmessungen und Prozessoptimierung – wichtig für Produktivität.</p>", "loesung": "<p><b>REFA unterteilt Arbeitszeit:</b></p><ul><li><b>Rüstzeit:</b> Vorbereitung (Maschine einstellen, Material holen).</li><li><b>Grundzeit:</b> reine Bearbeitungszeit.</li><li><b>Erholungszeit:</b> physiologische Pausen.</li><li><b>Verteilzeit:</b> Tätigkeiten, die nicht direkt zum Produkt, aber notwendig (Putzen, Papiere).</li></ul><p><b>Nutzen:</b> Realistische Zeitsätze, Bottleneck-Erkennung, KVP (Rüstzeit reduzieren = Produktivität steigt).</p>"}, {"id": "hf4g", "group": "hf4", "deck": "HF4G", "n": 7, "typ": "v", "kennung": "HF4g-1", "tax": "Wissen", "frage": "Was sind Anforderungen an eine <b>optimale Werkstatt-/Lagerplanung</b>?", "erklaerung": "<p>Gutes Layout spart Laufwege, Fehler und Kosten – langfristige Investition.</p>", "loesung": "<ul><li><b>Logistik:</b> Materialfluss optimieren (kurze Wege, FIFO-Prinzip).</li><li><b>Sicherheit:</b> Verkehrswege, Lagerzone getrennt, Notausgänge.</li><li><b>Arbeitsplätze:</b> ergonomisch, genug Platz, Licht/Lüftung.</li><li><b>Lagerverwaltung:</b> geordnet, Regalplanung, Zufahrts-/Umschlagszone.</li><li><b>Kapazität:</b> für erwartetes Wachstum dimensionieren, flexible Erweiterung.</li></ul>"}, {"id": "hf4g", "group": "hf4", "deck": "HF4G", "n": 8, "typ": "p", "kennung": "HF4g-4", "tax": "Werten", "frage": "Vergleichen Sie <b>Kauf vs. Leasing</b> eines Fahrzeugs – Vor/Nachteile.", "erklaerung": "<p>Typisches Investitionsproblem – beide Wege haben Argumente.</p>", "loesung": "<table><tr><th></th><th>Kauf</th><th>Leasing</th></tr><tr><td><b>Kosten</b></td><td>hoch initial (Finanzierung), dann fix</td><td>monatlich planbar, weniger Eigenkapital</td></tr><tr><td><b>Flexibilität</b></td><td>Fahrzeug lange, Restwertrisiko</td><td>kurze Vertragslaufzeiten (2–3 Jahre)</td></tr><tr><td><b>Wartung</b></td><td>Eigenverantwortung</td><td>oft im Leasing enthalten</td></tr><tr><td><b>Nutzung</b></td><td>Privatnutzung erlaubt</td><td>gewerblich, Kilometer-Limits</td></tr></table><p>Entscheidung: Langfristig & hohe Km → Kauf; kurzfristig & planbare Kosten → Leasing.</p>"}, {"id": "hf4h", "group": "hf4", "deck": "HF4H", "n": 1, "typ": "v", "kennung": "HF4h-1", "tax": "Wissen", "frage": "Unterscheiden Sie <b>ARGE, Bietergemeinschaft und Subunternehmer</b>.", "erklaerung": "<p>Kooperationen haben unterschiedliche Intensität und rechtliche Struktur – das bestimmt Haftung und Erfolg.</p>", "loesung": "<table><tr><th>Form</th><th>Zweck / Struktur</th><th>Haftung</th></tr><tr><td><b>ARGE</b></td><td>längerfristig für Projekt, GbR</td><td>Gesamtschuldner (volle Haftung!)</td></tr><tr><td><b>Bietergemeinschaft</b></td><td>nur für Angebotszusammenstellung</td><td>locker, danach Trennung</td></tr><tr><td><b>Subunternehmer</b></td><td>Teilleistung übertragen</td><td>HU haftet, SU eingeschränkt</td></tr></table>"}, {"id": "hf4h", "group": "hf4", "deck": "HF4H", "n": 2, "typ": "v", "kennung": "HF4h-1", "tax": "Wissen", "frage": "Was ist eine <b>ARGE (Arbeitsgemeinschaft)</b> und wie funktioniert sie?", "erklaerung": "<p>ARGEs sind häufig bei großen Projekten – mehrere Betriebe vereint für Gesamtvergabe.</p>", "loesung": "<ul><li><b>Rechtliche Basis:</b> GbR (Gesellschaft bürgerlichen Rechts).</li><li><b>Merkmale:</b> Teilnehmer bilden gemeinsamen Betrieb, eigener Buchungskreis, ARGE-Führung (ein Geschäftsführer).</li><li><b>Haftung:</b> <b>Gesamtschuldnerisch</b> – jeder haftet für das Ganze! (Risiko).</li><li><b>Abrechnung:</b> nach Leistungsanteil-Schlüssel (z. B. 40 % Zimmerer, 60 % Dachdecker).</li></ul>"}, {"id": "hf4h", "group": "hf4", "deck": "HF4H", "n": 3, "typ": "v", "kennung": "HF4h-1", "tax": "Wissen", "frage": "Vergleichen Sie <b>Einzelunternehmen, GbR und GmbH</b> – Haftung, Kapital, Verwaltung.", "erklaerung": "<p>Prüfungsklassiker – die Rechtsform bestimmt Haftungsrisiko und Komplexität.</p>", "loesung": "<table><tr><th></th><th>Einzelunternehmen</th><th>GbR</th><th>GmbH</th></tr><tr><td><b>Haftung</b></td><td>Privat­vermögen</td><td>unbeschränkt, alle Partner</td><td>Betriebsvermögen (Haftungsbeschränkung)</td></tr><tr><td><b>Kapital</b></td><td>beliebig</td><td>keine Min., Vertrag</td><td>25 000 € (davon 12 500 € Gründung)</td></tr><tr><td><b>Verwaltung</b></td><td>einfach</td><td>einfach, Vertrag</td><td>komplex, Buchhaltung, Jahresabschluss</td></tr></table>"}, {"id": "hf4h", "group": "hf4", "deck": "HF4H", "n": 4, "typ": "v", "kennung": "HF4h-1", "tax": "Wissen", "frage": "Was ist eine <b>UG (Unternehmergesellschaft)</b> und wofür ist sie geeignet?", "erklaerung": "<p>Die UG ist eine Variante der GmbH – für kleine Betriebe attraktiv, die mit wenig Kapital starten.</p>", "loesung": "<ul><li><b>GmbH-light:</b> Haftungsbeschränkung wie GmbH.</li><li><b>Gründungskapital:</b> ab <b>1 €</b> (statt 25 000 €).</li><li><b>Ansparungspflicht:</b> 25 % des Gewinns bis 25 000 € erreicht, dann Umwandlung in GmbH (automatisch/optional).</li><li><b>Einsatz:</b> Kleine Betriebe, Start-ups, Zweigbetriebe.</li></ul>"}, {"id": "hf4h", "group": "hf4", "deck": "HF4H", "n": 5, "typ": "v", "kennung": "HF4h-1", "tax": "Wissen", "frage": "Welche <b>Verbände und Organisationen</b> sind für einen Zimmereibetrieb relevant?", "erklaerung": "<p>Verbände bieten Unterstützung, Austausch und Vertretung – Mitgliedschaft lohnt sich oft.</p>", "loesung": "<ul><li><b>Handwerkskammer (HWK):</b> <b>Pflichtmitgliedschaft</b>, Berufsausbildung, Meisterprüfung, Recht, Schiedsverfahren.</li><li><b>Innung:</b> <b>Freiwillig</b>, Tarifverträge, Fachvertretung, Weiterbildung, Branchenvertretung.</li><li><b>ZDB (Zentralverband Deutsches Baugewerbe):</b> Bundesverband, Interessenvertretung.</li><li><b>Einkaufsgenossenschaften:</b> Rahmenverträge, bessere Konditionen durch Sammelbestellungen.</li></ul>"}, {"id": "hf4h", "group": "hf4", "deck": "HF4H", "n": 6, "typ": "v", "kennung": "HF4h-1", "tax": "Wissen", "frage": "Was regelt <b>VOB/B § 13</b> zu Mängelansprüchen und Gewährleistungsfristen?", "erklaerung": "<p>Gewährleistung ist das Thema bei Streitigkeiten – die Fristen sind entscheidend.</p>", "loesung": "<ul><li><b>VOB/B § 13:</b> Mängelansprüche (Nacherfüllung, Minderung, Schadensersatz).</li><li><b>Gewährleistungsfrist Bauwerk:</b> <b>4 Jahre</b> ab Abnahme (VOB, kürzer als BGB!).</li><li><b>BGB (ohne VOB):</b> <b>5 Jahre</b> ab Abnahme Bauwerk.</li><li>Mängel müssen <b>unverzüglich</b> nach Entdeckung gerügt werden (Versäumnis → Mithaftung).</li></ul>"}, {"id": "hf4h", "group": "hf4", "deck": "HF4H", "n": 7, "typ": "p", "kennung": "HF4h-1", "tax": "Können", "frage": "Eine ARGE aus 3 Zimmereien bekommt einen Auftrag 600 000 € (50:30:20 Verteilung). <b>Wie ist die Haftung geregelt?</b>", "erklaerung": "<p>Praktischer Fall: Wie funktioniert die Haftung bei Gesamtschuldnerschaft?</p>", "loesung": "<p>Bei Mängeln/Schäden (z. B. 30 000 €) kann der Bauherr jeden der ARGE-Partner voll in Haftung nehmen – nicht nur nach Anteilquote. Beispiel: Der Bauherr klagt den 50%-Partner auf 30 000 €. Der muss zahlen, obwohl sein Anteil 50 % wäre. <b>Gesamtschuldnerische Haftung = hohes Risiko</b> der schwächeren Partner!</p><p>→ Deshalb in ARGE-Verträgen: klare Einzelverantwortlichkeiten, Versicherungen, Regress-Klauseln.</p>"}, {"id": "hf4h", "group": "hf4", "deck": "HF4H", "n": 8, "typ": "v", "kennung": "HF4h-1", "tax": "Wissen", "frage": "Was ist das <b>Schwarzarbeitsbekämpfungsgesetz (SchwArbG)</b> und wie wirkt es sich auf Subaufträge aus?", "erklaerung": "<p>Schwarzarbeit ist illegal und teuer – der Unternehmer trägt die Verantwortung und Risiken.</p>", "loesung": "<ul><li><b>SchwArbG:</b> Bestrafung verborgen beschäftigter Arbeitnehmer, Steuerhinterziehung, Sozialabgaben.</li><li><b>Auswirkung auf Subaufträge:</b> Unternehmer haftet, wenn Subunternehmer Schwarzarbeit leistet (auch wenn er nichts wusste!).</li><li><b>Kontrollen:</b> Zollbeamte dürfen Baustellen inspizieren, Arbeitnehmer befragen, Papiere prüfen.</li><li><b>Schutz:</b> Verträge schriftlich, Lohnbelege prüfen, Mindestlohn-Nachweise fordern.</li></ul>"}];
